window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0067", [{"word":"biochemical","ipa_uk":"/ˌbaɪəʊˈkemɪkl/","ipa_us":"/ˌbaɪoʊˈkemɪkl/","definition_zh":"生物化学的；与生物体内化学反应有关的","definition_en":"relating to the chemical reactions and substances of living organisms","core_image":"细胞内部一张看不见的化学反应网正在运转","scene":"A doctor orders a biochemical test after the patient's liver enzymes rise.","sceneCN":"这里 biochemical 指「生化检验的」（第 3 个义项：用化学反应测定体内物质的检验）；句意：患者肝酶升高后，医生开了一项生化检验。","pos":[{"tag":"adj.","zh":"生物化学的；生化反应的；生化检验的"}],"collocations":[{"phrase":"biochemical reaction","zh":"生化反应"},{"phrase":"biochemical analysis","zh":"生化分析"},{"phrase":"biochemical pathway","zh":"生化通路"},{"phrase":"biochemical marker","zh":"生化标志物"},{"phrase":"biochemical oxygen demand","zh":"生化需氧量"},{"phrase":"biochemical engineering","zh":"生化工程"}],"forms":[{"label":"比较级","form":"more biochemical"},{"label":"最高级","form":"most biochemical"},{"label":"副词形式","form":"biochemically（从生化角度；生化上）"},{"label":"名词形式","form":"biochemistry（生物化学）"}],"derivatives":[{"word":"biochemistry","pos":"n.","zh":"生物化学"},{"word":"biochemist","pos":"n.","zh":"生物化学家"},{"word":"biochemically","pos":"adv.","zh":"从生物化学角度；生化上"},{"word":"biochemicals","pos":"n.","zh":"生化物质；生化制品（复数）"}],"senses":[{"no":"01","title":"Chemistry inside life","titleCN":"生命体内的化学","definition":"relating to the chemical reactions that take place inside living organisms","definitionCN":"生物化学的；涉及生物体内化学反应的","example":"Biochemical reactions in the liver break down most of the alcohol we drink.","exampleCN":"肝脏中的生化反应分解了我们饮用的大部分酒精。","why":"bio- names life and chemical names the kind of reaction chemistry studies; joining them yields an adjective for chemistry seen from inside a living body.","whyCN":"bio- 指生命，chemical 指化学所研究的那类反应；两者合并，就得到「从生命体内部看化学」的形容词。"},{"no":"02","title":"The substances themselves","titleCN":"生物体内的化学物质","definition":"concerning the chemical substances that living cells contain or produce","definitionCN":"生物体内化学物质的；涉及活细胞所含或所产生的物质的","example":"The study compared biochemical profiles of healthy and diseased tissue.","exampleCN":"这项研究比较了健康组织与患病组织的生化成分图谱。","why":"Once reactions are named, the molecules they involve also need a label, so the same adjective shifts from the process to the material.","whyCN":"反应被命名之后，参与反应的分子也需要一个说法，于是同一个形容词从「过程」转向「物质」。"},{"no":"03","title":"Laboratory testing","titleCN":"生化检验的","definition":"describing a laboratory test that measures chemical substances in blood or other body fluids","definitionCN":"生化检验的；指测定血液等体液中化学物质的实验室检查","example":"A routine biochemical screen flagged her elevated liver enzymes.","exampleCN":"一项常规生化筛查发现她的肝酶升高。","why":"Hospitals borrowed the adjective for tests that read the body's chemistry, because such a test measures exactly the substances the word already describes.","whyCN":"医院借用这个形容词来指读取体内化学状况的检查，因为这类检查测的正是这个词所描述的物质。"},{"no":"04","title":"Pathways and cycles","titleCN":"生化通路的","definition":"relating to a linked series of reactions inside a cell","definitionCN":"生化通路的；指细胞内一串相互衔接的反应","example":"Glycolysis is the biochemical pathway that begins the release of energy from glucose.","exampleCN":"糖酵解是启动葡萄糖释能的生化通路。","why":"A pathway is a route through the cell's chemical network, so the adjective marks the route rather than any single reaction.","whyCN":"通路是穿越细胞化学网络的一条路线，因此这个形容词标出的是路线，而不是某一个单独的反应。"},{"no":"05","title":"Oxygen demand in water","titleCN":"生化需氧量的","definition":"in environmental science, describing the oxygen that microbes consume while decomposing organic matter in water","definitionCN":"生化需氧量的；环境科学中指微生物分解水中有机物时所耗的氧","example":"The biochemical oxygen demand of the effluent was twice the permitted level.","exampleCN":"该废水的生化需氧量是允许水平的两倍。","why":"The standard test lets living microbes do the chemical work, so the adjective records that a biological agent carries out the oxidation being measured.","whyCN":"这项标准检测让活的微生物去完成化学工作，因此这个形容词说明：被测量的氧化过程是由生物主体完成的。"},{"no":"06","title":"Markers and signatures","titleCN":"生化标志物的","definition":"describing a molecule whose level signals a disease or a biological state","definitionCN":"生化标志物的；指含量可提示疾病或生理状态的分子","example":"A biochemical marker in the blood can reveal heart muscle damage.","exampleCN":"血液中的一种生化标志物可以提示心肌损伤。","why":"A marker is a substance that stands for a hidden condition, and the adjective says the signal is chemical and arises from a living process.","whyCN":"标志物是用一种物质代表看不见的状况，而这个形容词说明信号是化学的、来自生命过程。"},{"no":"07","title":"Weapons and agents","titleCN":"生化战剂的","definition":"relating to weapons that use chemicals or living organisms to cause harm","definitionCN":"生化战剂的；指用化学物质或活生物造成伤害的武器","example":"International law prohibits the development of biochemical weapons.","exampleCN":"国际法禁止研发生化武器。","why":"The compound was extended from laboratory chemistry to the chemistry of life turned into a weapon, keeping both halves of the word literal.","whyCN":"这个词从实验室化学延伸到「被武器化的生命化学」，两个字面成分都保持了原义。"},{"no":"08","title":"Molecular explanations","titleCN":"以生化机制解释的","definition":"explaining a biological effect by the underlying chemistry","definitionCN":"以生化机制解释的；用底层化学反应说明生物现象","example":"The team gave a biochemical explanation for how the bacterium resists the drug.","exampleCN":"该团队从生化机制上解释了这种细菌为何能抵抗该药物。","why":"When an effect is explained by reactions and molecules rather than by anatomy, the adjective labels the level of explanation rather than the thing explained.","whyCN":"当一个效应是用反应和分子、而不是用解剖结构来解释时，这个形容词标出的是解释的层次，而不是被解释的对象。"}],"etymology":{"intro":{"en":"Biochemical joins a Greek prefix for life to a word whose own origin is disputed, then adds a Latin adjective ending.","cn":"biochemical 把一个表示「生命」的希腊语前缀，接在一个本身来源尚有争议的词上，再加拉丁语形容词词尾。"},"items":[{"era":"GREEK BIOS","en":"The prefix bio- comes from Greek bios, 'life, course of life'. Scientific Latin made it a productive prefix in the late 18th and 19th centuries.","cn":"前缀 bio- 出自希腊语 bios「生命、生命历程」。科学拉丁语在 18 世纪末至 19 世纪把它变成了能产的构词成分。"},{"era":"GREEK KHEMEIA","en":"Chemical goes back through alchemy to Medieval Latin alchimia and Arabic al-kimiya, usually traced to Greek khemeia, the art of working metals. The further origin is disputed, sometimes linked to an Egyptian place name; this part is uncertain.","cn":"chemical 经 alchemy 上溯至中世纪拉丁语 alchimia 与阿拉伯语 al-kimiya，通常追溯到希腊语 khemeia「冶金术」。更早的来源有争议，有时被联系到埃及地名；这一层属于来源不确定。"},{"era":"EARLY NINETEENTH CENTURY","en":"The compound biochemical appears in scientific writing in the first half of the 19th century, when biology and chemistry were separating into distinct disciplines. The exact first use is not firmly established.","cn":"biochemical 这一复合词一般认为出现在 19 世纪上半叶的科学写作中，当时生物学与化学正分化为独立学科。确切的首见出处尚未定论。"},{"era":"CLINICAL LABORATORY","en":"In the 20th century the adjective became routine in hospitals, where a biochemical test means a panel of measurements on blood or urine.","cn":"进入 20 世纪，这个形容词在医院里成为常规用法，biochemical test 指对血液或尿液进行的一组测定。"},{"era":"ENVIRONMENTAL MEASURE","en":"The phrase biochemical oxygen demand was standardized in the early 20th century for measuring organic pollution in water.","cn":"biochemical oxygen demand 这一说法在 20 世纪初被标准化，用于衡量水中的有机污染。"},{"era":"MILITARY EXTENSION","en":"From the mid-20th century, biochemical was also attached to weapons and agents, broadening the word beyond the laboratory.","cn":"自 20 世纪中叶起，biochemical 又被用于武器与战剂，使这个词越出实验室的范围。"}]},"similar":{"note":{"en":"The first group holds look-alike words built on the same or neighbouring elements; the second holds words that overlap in meaning but differ in scope.","cn":"第一组是同用相近构词成分、容易看混的词；第二组是词义相交但范围不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"biological","ipa":"/ˌbaɪəˈlɒdʒɪkl/","tag":"adjective of life science","definition":"Relating to living things or to the science of life. It is broader than biochemical because it does not commit to chemistry.","definitionCN":"指与生物或生命科学有关的，范围比 biochemical 宽，因为它不限定在化学层面。"},{"word":"biochemistry","ipa":"/ˌbaɪəʊˈkemɪstri/","tag":"the noun, not the adjective","definition":"Names the discipline or the chemical processes themselves; biochemical is the form that modifies nouns such as test, pathway or weapon.","definitionCN":"是名词，指学科或化学过程本身；修饰 test、pathway、weapon 等名词时要用 biochemical。"},{"word":"biochemicals","ipa":"/ˌbaɪəʊˈkemɪklz/","tag":"plural noun","definition":"Names the chemical substances themselves, especially industrial products; the adjective biochemical has no plural.","definitionCN":"是复数名词，指化学物质本身，尤指工业制品；形容词 biochemical 没有复数形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"metabolic","ipa":"/məˈtæbəlɪk/","tag":"narrower: metabolism","definition":"Relating to metabolism, the sum of chemical changes in a body. It overlaps with biochemical but is tied specifically to metabolism.","definitionCN":"指与新陈代谢有关的，即体内化学变化的总和；与 biochemical 有交集，但专指代谢。"},{"word":"physiological","ipa":"/ˌfɪziəˈlɒdʒɪkl/","tag":"broader: body functions","definition":"Relating to the normal functions of organs and tissues, including but not limited to their chemistry.","definitionCN":"指器官与组织的正常功能，包含化学层面但并不限于化学层面。"},{"word":"molecular","ipa":"/məˈlekjələ(r)/","tag":"level of scale","definition":"Relating to molecules as such, in any context; biochemical adds that the molecules belong to living systems.","definitionCN":"指分子层面本身，可用于任何领域；biochemical 则补充说明这些分子属于生命系统。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"bio- 'life' + chemical: chemistry as it happens inside a living body.","cn":"bio-「生命」+ chemical「化学」：发生在活体内部的化学。"},{"en":"The family runs biochemistry, biochemist, biochemicals and biochemically.","cn":"同族词有 biochemistry、biochemist、biochemicals、biochemically。"},{"en":"Fixed phrases mark the technical senses: biochemical test, biochemical pathway, biochemical marker, biochemical oxygen demand.","cn":"固定搭配标出技术义项：生化检验、生化通路、生化标志物、生化需氧量。"},{"en":"Hospitals use a biochemical panel the way a mechanic uses a diagnostic scan.","cn":"医院用生化检查组套，就像修理工用诊断扫描。"},{"en":"The word keeps both halves visible: life on the left, chemistry on the right.","cn":"这个词把两半都摆在明面上：左边是生命，右边是化学。"}],"abstract":[{"en":"Think of a factory floor: the machines are chemical reactions, and the whole floor is alive.","cn":"想象一间车间：机器是化学反应，而整个车间是活的。"},{"en":"A biochemical marker is a smoke alarm for the body: it does not cause the fire, it reports it.","cn":"生化标志物像身体的烟雾报警器：它不制造火，只报告火。"},{"en":"Picture a river and a sewage plant: the microbes are workers, and their oxygen use is the bill they leave.","cn":"想象一条河与一座污水厂：微生物是工人，它们耗掉的氧就是留下的账单。"}]},"examples":[{"en":"Biochemical reactions in the liver break down most of the alcohol we drink.","cn":"肝脏中的生化反应分解了我们饮用的大部分酒精。"},{"en":"A biochemical test can detect damage before an imaging scan shows it.","cn":"生化检验可以在影像扫描显示之前发现损伤。"},{"en":"The researchers traced the insect's resistance to a biochemical change in its nerve cells.","cn":"研究者把这种昆虫的抗药性追溯到其神经细胞中的一处生化改变。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「bio（生命）+ chemical（化学）」→ 生命里的化学 → 生物化学的、生化检验的","word":"biochemical"},"root":"希腊语 bios「生命」+ 希腊语 khemeia「冶金术」（经阿拉伯语 al-kimiya 与中世纪拉丁语 alchimia 进入英语）→ chemical；再加形容词后缀 -al 构成 biochemical。","sensesIntro":{"en":"Eight senses follow one idea: chemistry happening inside life. The same adjective then moves from reactions to substances, to tests, to pathways, to markers, and finally to weapons and to explanations.","cn":"八个义项围绕一个想法展开：化学在生命内部发生。同一个形容词从反应移向物质，再移向检验、通路、标志物，最后延伸到武器与解释方式。"},"semanticMap":{"core":{"en":"CORE IMAGE: an invisible web of reactions turning matter inside a living cell.","cn":"核心意象：活细胞内部一张看不见的反应网在转化物质。"},"chain":["CHEMISTRY OF LIFE","REACTIONS IN CELLS","SUBSTANCES MEASURED","PATHWAYS TRACED","BODY DIAGNOSED","LIFE CHEMISTRY WEAPONISED"],"branches":[{"senses":"S1 · S8","en":"THE CORE: chemistry viewed inside a living body, whether as the subject of study or as the level of explanation.","cn":"核心：从活体内部看化学，既可以是被研究的对象，也可以是解释的层次。"},{"senses":"S2 · S3","en":"MATTER AND MEASUREMENT: the molecules involved, and the laboratory tests that read them.","cn":"物质与测量：参与其中的分子，以及读取这些分子的实验室检验。"},{"senses":"S4","en":"THE ROUTE: a pathway is the order in which the reactions run.","cn":"路线：通路就是这些反应运行的先后顺序。"},{"senses":"S5","en":"THE ENVIRONMENT: microbes doing the chemistry become a standard measure of water quality.","cn":"环境：由微生物完成的化学过程成为水质的标准量度。"},{"senses":"S6 · S7","en":"SIGNAL AND THREAT: the same chemistry can report disease or be turned into a weapon.","cn":"信号与威胁：同一套化学既能报告疾病，也能被做成武器。"}]},"affixes":{"intro":{"en":"The word is a transparent compound: a Greek prefix for life, an English word for chemistry, and a Latin adjective ending.","cn":"这个词的构造透明：一个表示生命的希腊语前缀，一个表示化学的英语词，以及一个拉丁语形容词词尾。"},"latinIntro":{"en":"The first element is Greek; the second reached English through Arabic and Medieval Latin. The Latin adjective ending -alis supplies -al.","cn":"第一个成分来自希腊语；第二个成分经阿拉伯语与中世纪拉丁语进入英语；形容词词尾 -al 来自拉丁语 -alis。"},"items":[{"word":"biochemical","structure":"bio- + chemical + -al","meaning":"relating to the chemistry of living things","meaningCN":"与生物化学有关的","example":"The biochemical pathway was mapped step by step.","exampleCN":"这条生化通路被逐步绘出。"},{"word":"biochemistry","structure":"bio- + chemistry","meaning":"the science of the chemistry of life","meaningCN":"研究生命化学的学科","example":"She teaches biochemistry to medical students.","exampleCN":"她给医学生讲授生物化学。"},{"word":"biochemist","structure":"biochemistry + -ist","meaning":"a person who studies the chemistry of life","meaningCN":"研究生命化学的人","example":"The biochemist purified the enzyme from liver tissue.","exampleCN":"这位生物化学家从肝组织中纯化了该酶。"},{"word":"biological","structure":"bio- + -logical","meaning":"relating to living things or to biology","meaningCN":"与生物或生物学有关的","example":"The lake supports a rich biological community.","exampleCN":"这座湖养育着丰富的生物群落。"},{"word":"biology","structure":"bio- + -logy","meaning":"the study of living things","meaningCN":"研究生物的学科","example":"Molecular biology grew out of biochemistry.","exampleCN":"分子生物学是从生物化学中发展出来的。"},{"word":"antibiotic","structure":"anti- (against) + bio- (life) + -ic","meaning":"a substance that works against bacteria","meaningCN":"对抗细菌的物质","example":"The doctor prescribed a course of antibiotics.","exampleCN":"医生开了一个疗程的抗生素。"},{"word":"chemical","structure":"chem- + -ical","meaning":"relating to chemistry or to substances used in it","meaningCN":"与化学或化学物质有关的","example":"The factory stores chemical waste in sealed tanks.","exampleCN":"工厂把化学废料存放在密封罐中。"},{"word":"chemist","structure":"chem- + -ist","meaning":"a person trained in chemistry","meaningCN":"受过化学训练的人","example":"The chemist tested the purity of the sample.","exampleCN":"化学家检测了样本的纯度。"},{"word":"alchemy","structure":"al- (Arabic definite article) + Greek khemeia","meaning":"the medieval art of transforming metals","meaningCN":"中世纪转化金属的技艺","example":"Alchemy preceded modern chemistry.","exampleCN":"炼金术先于现代化学出现。"},{"word":"biochemically","structure":"biochemical + -ly","meaning":"in terms of the chemistry of life","meaningCN":"从生物化学的角度","example":"The two tissues are biochemically distinct.","exampleCN":"这两种组织在生化上是有区别的。"}],"latinEntries":[{"word":"βίος","structure":"Greek noun, 'life, course of life'","meaning":"life; a way of living","meaningCN":"生命；生活方式"},{"word":"χημεία","structure":"Greek noun, 'art of working metals'","meaning":"metalworking; the art later called chemistry","meaningCN":"冶金术；后来称为化学的技艺"},{"word":"alchimia","structure":"Medieval Latin, from Arabic al-kimiya","meaning":"alchemy; the transmutation of metals","meaningCN":"炼金术；金属转化之术"}]}},{"word":"biochemistry","ipa_uk":"/ˌbaɪəʊˈkemɪstri/","ipa_us":"/ˌbaɪoʊˈkemɪstri/","definition_zh":"生物化学；生物体的化学过程与化学组成","definition_en":"the science of the chemical processes and substances of living organisms","core_image":"把一只活细胞拆成一张分子反应清单","scene":"Her biochemistry results showed low potassium after two weeks of illness.","sceneCN":"这里 biochemistry 指「生化检验结果」（第 8 个义项：一组血液化学指标）；句意：患病两周后，她的生化结果显示血钾偏低。","pos":[{"tag":"n.","zh":"生物化学；生物体的化学过程；生化检验指标（作不可数名词，指学科或过程时一般不加 -s）"}],"collocations":[{"phrase":"clinical biochemistry","zh":"临床生物化学"},{"phrase":"biochemistry department","zh":"生物化学系；生化科"},{"phrase":"the biochemistry of muscle","zh":"肌肉的生物化学"},{"phrase":"biochemistry textbook","zh":"生物化学教材"},{"phrase":"plant biochemistry","zh":"植物生物化学"},{"phrase":"metabolic biochemistry","zh":"代谢生物化学"}],"forms":[{"label":"复数（指多套生化指标）","form":"biochemistries（少见，多用于不同体系或不同检测结果）"},{"label":"学科用法","form":"biochemistry（作学科名时不可数）"},{"label":"从业者","form":"biochemist（生物化学家）"},{"label":"形容词","form":"biochemical（生物化学的）"}],"derivatives":[{"word":"biochemical","pos":"adj.","zh":"生物化学的"},{"word":"biochemist","pos":"n.","zh":"生物化学家"},{"word":"biochemically","pos":"adv.","zh":"从生物化学角度"},{"word":"biomolecule","pos":"n.","zh":"生物分子"},{"word":"metabolite","pos":"n.","zh":"代谢产物"}],"senses":[{"no":"01","title":"The discipline","titleCN":"生物化学（学科）","definition":"the branch of science that studies the chemical processes and substances of living organisms","definitionCN":"研究生物体内化学过程与化学物质的学科","example":"Biochemistry sits between biology and chemistry on the university campus.","exampleCN":"在大学里，生物化学处在生物学与化学之间。","why":"The suffix -istry names a field of study, so the compound first of all labels a discipline with two parent sciences.","whyCN":"后缀 -istry 表示研究领域，因此这个词首先命名一门由两门母科学交叉而成的学科。"},{"no":"02","title":"The processes in a body","titleCN":"生物体的化学过程","definition":"the chemical processes that take place in a living organism","definitionCN":"活生物体内发生的化学过程","example":"The biochemistry of the insect changes sharply when it enters hibernation.","exampleCN":"这种昆虫进入休眠时，其体内的化学过程会发生剧烈变化。","why":"The same noun can name not only the study but also its object, because a science and the processes it studies are habitually spoken of with one word.","whyCN":"同一个名词既可以是学科，也可以是研究对象，因为人们习惯用一个词同时指「学问」和「这门学问所研究的那些过程」。"},{"no":"03","title":"Chemical makeup","titleCN":"化学组成","definition":"the chemical composition of a tissue, organism or substance","definitionCN":"某组织、生物或物质的化学组成","example":"The biochemistry of the seed oil makes it suitable for cold climates.","exampleCN":"这种种子油的化学组成使它适合寒冷气候。","why":"If processes are the verbs of a cell, the substances are its nouns; the word extends naturally from what happens to what is there.","whyCN":"如果化学过程是细胞里的动词，那么化学物质就是名词；词义从「发生什么」自然延伸到「有什么」。"},{"no":"04","title":"A course or subject","titleCN":"生物化学课程","definition":"a course, textbook or examination subject dealing with the chemistry of life","definitionCN":"讲授生命化学的课程、教材或考试科目","example":"Biochemistry is a required course for medical students here.","exampleCN":"生物化学是这里医学生的必修课。","why":"Academic institutions name subjects after the discipline, so the word also labels the thing taught and examined.","whyCN":"学术机构用学科名来命名科目，于是这个词也指被讲授、被考试的那门课。"},{"no":"05","title":"Department or laboratory","titleCN":"生物化学系；生化实验室","definition":"an academic department or research unit devoted to the subject","definitionCN":"从事该学科的系或研究单位","example":"The biochemistry at this hospital runs the newborn screening programme.","exampleCN":"这家医院的生化科负责新生儿筛查项目。","why":"A metonymy turns the discipline into the place and the staff that practise it, a pattern common to names of departments.","whyCN":"这是一种转喻：用学科名指从事该学科的场所与人员，院系名称普遍采用这种说法。"},{"no":"06","title":"Clinical branch","titleCN":"临床生物化学","definition":"the branch that measures chemical substances in patients' samples to diagnose and monitor disease","definitionCN":"测定患者样本中的化学物质以诊断和监测疾病的分支","example":"Clinical biochemistry detected the salt imbalance before symptoms appeared.","exampleCN":"临床生物化学在症状出现前就检出了盐类失衡。","why":"Medicine split off a service-oriented branch, and the parent word now covers both the pure science and its hospital application.","whyCN":"医学分出一个面向服务的分支，母词于是同时涵盖纯科学与医院里的应用。"},{"no":"07","title":"Chemistry of a pathway","titleCN":"某条代谢通路的生化机制","definition":"the specific reactions and molecules of one metabolic route","definitionCN":"某一代谢通路的具体反应与分子","example":"The biochemistry of fat storage explains why the liver enlarges.","exampleCN":"脂肪储存的生化机制解释了肝脏为何增大。","why":"With of plus a named process, the noun narrows to the chemistry that belongs to that process alone.","whyCN":"当它与表示某个具体过程的词组成介词短语连用时，这个名词就收窄为「该过程专属的那套化学」。"},{"no":"08","title":"Laboratory results","titleCN":"生化检验结果","definition":"in clinical speech, the set of chemical measurements reported for a patient","definitionCN":"临床上指为患者报告的一组化学测定结果","example":"Her biochemistry was normal apart from a low bicarbonate level.","exampleCN":"除碳酸氢盐偏低外，她的生化指标都正常。","why":"Doctors compress 'the results of the biochemistry test' into the single word, another metonymy from discipline to output.","whyCN":"医生把「生化检验的结果」压缩成一个词，这是又一次转喻：从学科名转向它的产出。"},{"no":"09","title":"Figurative inner workings","titleCN":"引申：内在的化学机制","definition":"the hidden chemical or emotional workings of something, used figuratively","definitionCN":"比喻用法，指某事物隐藏的化学或情感机制","example":"Popular science writes about the biochemistry of attraction.","exampleCN":"科普写作会谈论吸引力的生化机制。","why":"Once the word means 'the chemistry behind a phenomenon', it can be borrowed for any hidden mechanism, especially in popular writing.","whyCN":"一旦这个词表示「现象背后的化学」，它就能被借去指任何隐藏机制，在通俗写作中尤其常见。"}],"etymology":{"intro":{"en":"Biochemistry is a 19th-century compound of a Greek prefix for life and an English noun for chemistry, coined as the two sciences converged.","cn":"biochemistry 是 19 世纪的复合词，由表示生命的希腊语前缀与表示化学的英语名词构成，诞生于两门科学交汇之时。"},"items":[{"era":"GREEK BIOS","en":"bio- comes from Greek bios, 'life, course of life'. It became a scientific prefix in the 19th century, first in biology and then in a swarm of compounds.","cn":"bio- 出自希腊语 bios「生命、生命历程」。它在 19 世纪成为科学前缀，先用于 biology，随后进入一大批复合词。"},{"era":"CHEMISTRY","en":"Chemistry reached English through alchemy, Medieval Latin alchimia and Arabic al-kimiya, usually traced to Greek khemeia. The earliest origin remains disputed, so the deeper etymology is uncertain.","cn":"chemistry 经 alchemy、中世纪拉丁语 alchimia、阿拉伯语 al-kimiya 进入英语，通常追溯到希腊语 khemeia。更早的来源仍有争议，深层词源属于来源不确定。"},{"era":"MID-NINETEENTH CENTURY","en":"The compound biochemistry is generally dated to the middle decades of the 19th century, when physiologists began to describe life in chemical terms. The exact coinage is not settled.","cn":"biochemistry 这一复合词一般认为出现在 19 世纪中叶，当时生理学家开始用化学语言描述生命。确切的首创者尚无定论。"},{"era":"PROTEIN AND ENZYME ERA","en":"Around 1900 the field acquired its modern shape as enzymes, proteins and metabolic pathways were worked out, and university chairs followed.","cn":"约 1900 年，随着酶、蛋白质与代谢通路被阐明，这门学科获得现代形态，大学教席也随之设立。"},{"era":"CLINICAL SERVICE","en":"In the 20th century hospitals created clinical biochemistry laboratories, adding the everyday sense of a set of test results.","cn":"20 世纪医院设立临床生化实验室，由此增加了「一组检验结果」这一日常义。"},{"era":"MOLECULAR TURN","en":"After the 1950s, biochemistry merged with molecular biology, and the word now covers both the classic chemistry of life and its molecular successor.","cn":"1950 年代以后，生物化学与分子生物学融合，这个词如今同时涵盖经典的生命化学与其分子层面的后继者。"}]},"similar":{"note":{"en":"The first group separates the noun from its adjective and from neighbouring life-science words; the second separates it from words for adjacent levels of study.","cn":"第一组把这个名词与它的形容词以及与相邻的生命科学词分开；第二组把它与邻近研究层次的词分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"biochemical","ipa":"/ˌbaɪəʊˈkemɪkl/","tag":"adjective","definition":"The adjective meaning 'of the chemistry of life'; it describes tests, pathways and substances, while biochemistry names the field or the processes.","definitionCN":"是形容词，意为「生命化学的」，用来修饰检验、通路、物质；biochemistry 则指学科或过程。"},{"word":"biology","ipa":"/baɪˈɒlədʒi/","tag":"sister discipline","definition":"The study of living things in general, including their structure, growth and behaviour; it is wider than biochemistry.","definitionCN":"泛指研究生物及其结构、生长与行为的学科，范围比生物化学更宽。"},{"word":"biochemist","ipa":"/ˌbaɪəʊˈkemɪst/","tag":"person, not field","definition":"The person who practises biochemistry; the field itself never takes the -ist ending.","definitionCN":"指从事生物化学的人；学科本身不能加 -ist 词尾。"}]},{"heading":"NEAR MEANING","entries":[{"word":"molecular biology","ipa":"/məˈlekjələ(r) baɪˈɒlədʒi/","tag":"successor field","definition":"The study of biological processes at the level of DNA, RNA and proteins; it overlaps heavily with biochemistry but centres on information flow.","definitionCN":"在 DNA、RNA 与蛋白质层面研究生命过程，与生物化学高度重叠，但更侧重信息传递。"},{"word":"physiology","ipa":"/ˌfɪziˈɒlədʒi/","tag":"function, not chemistry","definition":"The study of how organs and tissues function; it asks what a body does, while biochemistry asks what reactions make it possible.","definitionCN":"研究器官与组织如何运作，关心「身体做什么」；生物化学关心「哪些反应使之成为可能」。"},{"word":"chemistry","ipa":"/ˈkemɪstri/","tag":"parent science","definition":"The science of substances and their reactions in general; biochemistry is its living subset.","definitionCN":"研究物质及其反应的一般科学；生物化学是它在生命领域的子集。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"bio- 'life' + chemistry: the chemistry of life.","cn":"bio-「生命」+ chemistry「化学」：生命的化学。"},{"en":"The family runs biochemical, biochemist, biomolecule and metabolite.","cn":"同族词有 biochemical、biochemist、biomolecule、metabolite。"},{"en":"Fixed phrases: clinical biochemistry, biochemistry department, plant biochemistry.","cn":"固定搭配：临床生物化学、生物化学系、植物生物化学。"},{"en":"Hospitals say 'her biochemistry is normal' when they mean the lab panel.","cn":"医院说「她的生化正常」，指的是一组化验指标。"},{"en":"The word names both the field and the thing the field studies, like 'history' naming both a discipline and a past.","cn":"这个词既指学科，也指学科研究的对象，就像 history 既指历史学也指过去。"}],"abstract":[{"en":"Think of a city's traffic map: biochemistry is the map of every chemical route inside a cell.","cn":"想象一张城市交通图：生物化学就是细胞内每条化学反应路线的地图。"},{"en":"A biochemistry panel is a weather report for the body's internal climate.","cn":"一组生化指标就像身体内部气候的天气预报。"},{"en":"Picture a workshop where every tool is a molecule and every worker is an enzyme.","cn":"想象一间作坊：每件工具都是分子，每个工人都是酶。"}]},"examples":[{"en":"Biochemistry explains how cells extract energy from sugar.","cn":"生物化学解释了细胞如何从糖中获取能量。"},{"en":"She chose biochemistry because she wanted to understand life at the molecular level.","cn":"她选择生物化学，是因为想在分子层面理解生命。"},{"en":"The hospital's biochemistry laboratory reports results within an hour.","cn":"医院的生化实验室一小时内出结果。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「bio（生命）+ chemistry（化学）」→ 研究生命里的化学 → 生物化学","word":"biochemistry"},"root":"希腊语 bios「生命」+ chemistry（经阿拉伯语 al-kimiya、中世纪拉丁语 alchimia 上溯至希腊语 khemeia「冶金术」），19 世纪合成为 biochemistry。","sensesIntro":{"en":"Nine senses move from the discipline to its object, then to its composition, its teaching, its institutions, its clinical branch, its results and finally to figurative inner workings.","cn":"九个义项从学科移向研究对象，再到化学组成、课程、机构、临床分支、检验结果，最后落到比喻性的内在机制。"},"semanticMap":{"core":{"en":"CORE IMAGE: a list of molecular reactions extracted from a living cell.","cn":"核心意象：从一只活细胞里抽出来的一张分子反应清单。"},"chain":["SCIENCE OF LIFE CHEMISTRY","PROCESSES IN THE BODY","CHEMICAL MAKEUP","TAUGHT AS A SUBJECT","PRACTISED IN A DEPARTMENT","READ AS CLINICAL RESULTS"],"branches":[{"senses":"S1 · S2","en":"THE DISCIPLINE AND ITS OBJECT: the field itself, and the processes it studies.","cn":"学科与其对象：这门学问本身，以及它所研究的那些过程。"},{"senses":"S3","en":"SUBSTANCE: what the cell contains rather than what it does.","cn":"物质：细胞里有什么，而不是它做了什么。"},{"senses":"S4 · S5","en":"INSTITUTION: the subject as taught, and the department or laboratory that practises it.","cn":"机构：作为科目的课程，以及从事该学科的院系或实验室。"},{"senses":"S6 · S7","en":"SPECIALISED ROUTES: a clinical branch and the chemistry of one named pathway.","cn":"专门路线：一个临床分支，以及某条被点名的通路的化学。"},{"senses":"S8 · S9","en":"OUTPUT AND METAPHOR: the reported results, and the hidden chemistry of any phenomenon.","cn":"产出与比喻：报告出来的结果，以及任何现象背后隐藏的化学。"}]},"affixes":{"intro":{"en":"Biochemistry is a two-root compound with a Greek prefix and an English noun, plus the abstract suffix -istry.","cn":"biochemistry 是双词根复合词：希腊语前缀加英语名词，再带抽象名词后缀 -istry。"},"latinIntro":{"en":"Greek supplies the element for life; the chemistry element came through Arabic and Medieval Latin. The suffix -istry descends from Latin -ia and Greek -ia.","cn":"希腊语提供表示生命的成分；表示化学的成分经阿拉伯语与中世纪拉丁语传入；后缀 -istry 源自拉丁语 -ia 与希腊语 -ia。"},"items":[{"word":"biochemistry","structure":"bio- + chemistry","meaning":"the chemistry of living systems","meaningCN":"生命系统的化学","example":"Biochemistry became a separate degree in the twentieth century.","exampleCN":"生物化学在 20 世纪成为独立学位。"},{"word":"biochemical","structure":"bio- + chemical + -al","meaning":"relating to the chemistry of life","meaningCN":"与生命化学有关的","example":"The biochemical assay took two hours.","exampleCN":"这项生化测定用了两小时。"},{"word":"biochemist","structure":"biochemistry + -ist","meaning":"one who studies the chemistry of life","meaningCN":"研究生命化学的人","example":"The biochemist grew crystals of the enzyme.","exampleCN":"这位生物化学家培养了该酶的晶体。"},{"word":"biology","structure":"bio- + -logy","meaning":"the study of living things","meaningCN":"研究生物的学科","example":"Biology and biochemistry share their first element.","exampleCN":"生物学与生物化学共享第一个构词成分。"},{"word":"biomolecule","structure":"bio- + molecule","meaning":"a molecule produced by or belonging to life","meaningCN":"由生命产生或属于生命的分子","example":"Proteins are the most versatile biomolecules.","exampleCN":"蛋白质是最多才多艺的生物分子。"},{"word":"metabolite","structure":"metabol- (change) + -ite","meaning":"a product of metabolism","meaningCN":"代谢的产物","example":"The drug's main metabolite is inactive.","exampleCN":"该药物的主要代谢产物没有活性。"},{"word":"enzyme","structure":"Greek en- (in) + zyme (leaven)","meaning":"a protein that catalyses a reaction","meaningCN":"催化反应的蛋白质","example":"Each step of the pathway needs its own enzyme.","exampleCN":"通路的每一步都需要各自的酶。"},{"word":"chemistry","structure":"chem- + -istry","meaning":"the science of substances and reactions","meaningCN":"研究物质与反应的科学","example":"Chemistry provides the methods biochemistry uses.","exampleCN":"化学提供了生物化学所用的方法。"},{"word":"clinical","structure":"Greek klinē (bed) + -al","meaning":"relating to the treatment of patients","meaningCN":"与病人诊疗有关的","example":"Clinical biochemistry reports potassium levels.","exampleCN":"临床生物化学报告血钾水平。"}],"latinEntries":[{"word":"βίος","structure":"Greek noun, 'life'","meaning":"life; a lifetime","meaningCN":"生命；一生"},{"word":"χημεία","structure":"Greek noun, 'metalworking'","meaning":"the art of working metals","meaningCN":"冶金术"},{"word":"alchimia","structure":"Medieval Latin from Arabic","meaning":"alchemy","meaningCN":"炼金术"}]}},{"word":"bioengineering","ipa_uk":"/ˌbaɪəʊendʒɪˈnɪərɪŋ/","ipa_us":"/ˌbaɪoʊendʒɪˈnɪrɪŋ/","definition_zh":"生物工程；把工程原理用于生物系统与医学","definition_en":"the application of engineering principles and methods to biological systems and medicine","core_image":"工程师的图纸上画着细胞、血管与人造关节","scene":"Bioengineering students built a scaffold on which new skin could grow.","sceneCN":"这里 bioengineering 指「组织工程」（第 2 个义项：用工程支架让活组织再生）；句意：生物工程专业的学生搭建了一个能让新皮肤生长的支架。","pos":[{"tag":"n.","zh":"生物工程；生物工程学；生物医学工程（不可数）"}],"collocations":[{"phrase":"bioengineering department","zh":"生物工程系"},{"phrase":"tissue bioengineering","zh":"组织生物工程"},{"phrase":"bioengineering approach","zh":"生物工程方法"},{"phrase":"bioengineering research","zh":"生物工程研究"},{"phrase":"plant bioengineering","zh":"植物生物工程"},{"phrase":"bioengineering company","zh":"生物工程公司"}],"forms":[{"label":"不可数用法","form":"bioengineering（作学科名时不加 -s）"},{"label":"从业者","form":"bioengineer（生物工程师）"},{"label":"动词","form":"bioengineer（用生物工程手段改造）"},{"label":"形容词","form":"bioengineered（经生物工程改造的）"}],"derivatives":[{"word":"bioengineer","pos":"n./v.","zh":"生物工程师；用生物工程改造"},{"word":"bioengineered","pos":"adj.","zh":"经生物工程改造的"},{"word":"biomedical engineering","pos":"n.","zh":"生物医学工程"},{"word":"bioreactor","pos":"n.","zh":"生物反应器"},{"word":"scaffold","pos":"n.","zh":"组织工程支架"}],"senses":[{"no":"01","title":"Engineering for living systems","titleCN":"面向生命系统的工程学","definition":"the application of engineering principles to biological systems and to medicine","definitionCN":"把工程原理应用于生物系统与医学","example":"Bioengineering combines mechanics, materials and cell biology.","exampleCN":"生物工程把力学、材料学与细胞生物学结合起来。","why":"The word simply joins engineering to life: the methods are those of the engineer, and the object is a living system.","whyCN":"这个词把工程学与生命直接拼在一起：方法来自工程师，对象是生命系统。"},{"no":"02","title":"Tissue and organ engineering","titleCN":"组织与器官工程","definition":"the branch that builds scaffolds and living substitutes for damaged tissue or organs","definitionCN":"构建支架与活体替代物、修复受损组织或器官的分支","example":"Bioengineering has produced lab-grown cartilage for knee repair.","exampleCN":"生物工程已经造出用于膝关节修复的实验室培育软骨。","why":"Rebuilding a body part requires both a design and living cells, so this branch is the clearest meeting point of the two halves of the word.","whyCN":"重建身体部件既需要设计，也需要活细胞，因此这一分支是「工程」与「生命」两半最直接的汇合处。"},{"no":"03","title":"Genetic engineering","titleCN":"基因工程","definition":"the deliberate modification of an organism's genetic material","definitionCN":"有目的地改造生物体的遗传物质","example":"Bioengineering of the yeast let it produce a new medicine.","exampleCN":"对酵母的基因工程改造使它能够生产一种新药。","why":"At the molecular scale, engineering becomes the rewriting of DNA, and popular usage often treats bioengineering and genetic engineering as interchangeable.","whyCN":"在分子尺度上，工程就变成改写 DNA，因此通俗用法常把生物工程与基因工程当作同义词。"},{"no":"04","title":"Medical devices and prosthetics","titleCN":"医疗器械与假体","definition":"the design of implants, prostheses and machines that work with the body","definitionCN":"设计与身体配合的植入物、假体与机器","example":"Bioengineering developed the artificial heart valve used in the trial.","exampleCN":"生物工程研制了试验中使用的人工心脏瓣膜。","why":"An engineer who builds a device for a body must respect biological constraints, which is exactly what the compound promises.","whyCN":"为身体制造装置的工程师必须服从生物约束，这正是这个复合词所承诺的内容。"},{"no":"05","title":"Agricultural engineering","titleCN":"农业生物工程","definition":"the engineering of crops and farm animals for yield, resistance or quality","definitionCN":"为提高产量、抗性或品质而对作物与畜禽进行的工程改造","example":"Bioengineering gave the rice a gene for salt tolerance.","exampleCN":"生物工程赋予这种水稻一个耐盐基因。","why":"Farming has always shaped living things; modern tools turn that shaping into a branch of engineering.","whyCN":"农业一直在塑造生物；现代工具把这种塑造变成了工程学的一个分支。"},{"no":"06","title":"Environmental engineering","titleCN":"环境生物工程","definition":"the use of engineered organisms or systems to clean up pollution","definitionCN":"利用经改造的生物或系统治理污染","example":"Bioengineering produced bacteria that digest oil spills.","exampleCN":"生物工程造出了能分解泄漏石油的细菌。","why":"The same design logic is pointed at waste and pollution, so the word gains an environmental application.","whyCN":"同一套设计逻辑被指向废物与污染，于是这个词获得了环境方面的应用义。"},{"no":"07","title":"The field or department","titleCN":"学科；院系","definition":"the academic discipline or the department that teaches and researches it","definitionCN":"教授与研究该方向的学科或院系","example":"The bioengineering department shares a building with the medical school.","exampleCN":"生物工程系与医学院共用一栋楼。","why":"As with every discipline name, the word stands for the institution and the people who practise it.","whyCN":"和所有学科名一样，这个词也代指机构与从事它的人。"},{"no":"08","title":"Designing biological parts","titleCN":"生物部件设计","definition":"the design of biological parts or systems that do not exist in nature","definitionCN":"设计自然界并不存在的生物部件或系统","example":"Bioengineering now writes circuits into bacterial DNA.","exampleCN":"生物工程如今把逻辑回路写进细菌的 DNA。","why":"Once living parts are treated as components, the engineer's verb 'design' applies to biology itself, the sense closest to synthetic biology.","whyCN":"一旦生命的部件被当作零件，工程师的动词「设计」就能用于生物学本身，这是最接近合成生物学的义项。"}],"etymology":{"intro":{"en":"Bioengineering is a 20th-century compound: a Greek prefix for life attached to an English noun whose roots reach Latin and French.","cn":"bioengineering 是 20 世纪的复合词：表示生命的希腊语前缀，加上一个词源可追溯至拉丁语与法语的英语名词。"},"items":[{"era":"GREEK BIOS","en":"bio- comes from Greek bios, 'life'. It became a standard scientific prefix in the 19th century.","cn":"bio- 出自希腊语 bios「生命」，在 19 世纪成为标准的科学前缀。"},{"era":"LATIN INGENIUM","en":"Engineering goes back to engine, from Old French engin and Latin ingenium, 'native talent, clever device'. The modern sense of designing machines is 18th and 19th century.","cn":"engineering 经古法语 engin 上溯至拉丁语 ingenium「天赋、巧妙的装置」。设计机器的现代义形成于 18 至 19 世纪。"},{"era":"MID-TWENTIETH CENTURY","en":"The compound bioengineering is generally dated to the mid-20th century, when engineering methods were first applied systematically to medicine and living tissue. The exact first use is uncertain.","cn":"bioengineering 这一复合词一般认为出现于 20 世纪中叶，当时工程方法开始被系统地用于医学与活组织。确切的首见出处不确定。"},{"era":"MEDICAL ENGINEERING","en":"In the 1960s and 1970s the term became institutional, with departments, journals and degree programmes.","cn":"1960 至 1970 年代，这个词逐渐制度化，出现了系所、期刊与学位项目。"},{"era":"GENETIC AND SYNTHETIC TURN","en":"After the 1970s, recombinant DNA widened bioengineering to mean genetic modification, and later synthetic biology.","cn":"1970 年代以后，重组 DNA 使 bioengineering 扩展到基因改造，后来又延伸到合成生物学。"}]},"similar":{"note":{"en":"The first group separates neighbouring compounds built on bio-; the second separates engineering from the sciences it borrows from.","cn":"第一组区分以 bio- 构成的邻近复合词；第二组把工程学与它所借用的科学区分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"biotechnology","ipa":"/ˌbaɪəʊtekˈnɒlədʒi/","tag":"products, not design","definition":"The use of living systems to make products; it overlaps with bioengineering but stresses production rather than engineering design.","definitionCN":"指利用生命系统制造产品，与生物工程重叠，但更强调生产而不是工程设计。"},{"word":"biomedical engineering","ipa":"/ˌbaɪəʊˈmedɪkl endʒɪˈnɪərɪŋ/","tag":"medical subset","definition":"The part of bioengineering concerned with medicine and health care; it is narrower than the general term.","definitionCN":"生物工程中面向医学与医疗保健的部分，比总称更窄。"},{"word":"genetic engineering","ipa":"/dʒeˈnetɪk endʒɪˈnɪərɪŋ/","tag":"one branch","definition":"The direct alteration of DNA; it is one branch of bioengineering, not a synonym for the whole field.","definitionCN":"指直接改造 DNA，是生物工程的一个分支，并不等同于整个领域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"engineering","ipa":"/endʒɪˈnɪərɪŋ/","tag":"general field","definition":"The design and building of machines, structures and systems; bioengineering is its living and medical application.","definitionCN":"泛指机器、结构与系统的设计与建造；生物工程是它在生命与医学领域的应用。"},{"word":"biophysics","ipa":"/ˌbaɪəʊˈfɪzɪks/","tag":"measurement, not design","definition":"The study of biological systems with physics methods; it explains how life obeys physical laws rather than designing new parts.","definitionCN":"用物理学方法研究生物系统，解释生命如何服从物理规律，而不是设计新部件。"},{"word":"synthetic biology","ipa":"/sɪnˈθetɪk baɪˈɒlədʒi/","tag":"newer sibling","definition":"The design and construction of new biological parts and systems, often seen as the engineering wing of biology.","definitionCN":"设计与构建新的生物部件与系统，常被视为生物学的工程分支。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"bio- 'life' + engineering: engineering aimed at living systems.","cn":"bio-「生命」+ engineering「工程」：对准生命系统的工程。"},{"en":"The family runs bioengineer, bioengineered, bioreactor and biomedical engineering.","cn":"同族词有 bioengineer、bioengineered、bioreactor、biomedical engineering。"},{"en":"Fixed phrases: tissue bioengineering, plant bioengineering, bioengineering department.","cn":"固定搭配：组织生物工程、植物生物工程、生物工程系。"},{"en":"The two halves are visible: life on the left, design on the right.","cn":"两半都看得见：左边是生命，右边是设计。"},{"en":"A bioreactor is the factory floor where engineered cells do their work.","cn":"生物反应器就是经改造的细胞干活的车间。"}],"abstract":[{"en":"Picture a bridge made of cells: the engineer draws it, the biologist grows it.","cn":"想象一座用细胞搭成的桥：工程师画图，生物学家把它长出来。"},{"en":"A scaffold for tissue is a trellis for a climbing plant, except the plant is human skin.","cn":"组织支架就像给攀援植物搭的棚架，只不过这株植物是人的皮肤。"},{"en":"Genetic engineering is editing a recipe that writes itself.","cn":"基因工程就是修改一份会自己书写的食谱。"}]},"examples":[{"en":"Bioengineering combines materials science with cell biology.","cn":"生物工程把材料科学与细胞生物学结合起来。"},{"en":"The lab uses bioengineering to grow replacement blood vessels.","cn":"该实验室用生物工程培育替代血管。"},{"en":"Critics argue that bioengineering of crops should be labelled clearly.","cn":"批评者认为，对作物进行生物工程改造应当明确标注。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「bio（生命）+ engineering（工程）」→ 给生命做工程 → 生物工程","word":"bioengineering"},"root":"希腊语 bios「生命」+ engineering（经古法语 engin 上溯至拉丁语 ingenium「天赋、巧妙的装置」），20 世纪合成。","sensesIntro":{"en":"Eight senses extend engineering into life: from the general field to tissue, genes, devices, farms, pollution, institutions, and finally the design of entirely new biological parts.","cn":"八个义项把工程学伸进生命：从总领域到组织、基因、器械、农业、污染治理、院系，最后到设计全新的生物部件。"},"semanticMap":{"core":{"en":"CORE IMAGE: an engineer's drawing in which the parts are cells, vessels and joints.","cn":"核心意象：一张工程师的图纸，上面的零件是细胞、血管与关节。"},"chain":["ENGINEERING MEETS LIFE","REBUILD TISSUE","REWRITE GENES","FIT THE BODY","ENGINEER CROPS AND MICROBES","DESIGN NEW PARTS"],"branches":[{"senses":"S1","en":"THE GENERAL FIELD: engineering methods applied to any living system.","cn":"总领域：工程方法用于任何生命系统。"},{"senses":"S2 · S4","en":"REPAIR: scaffolds and implants that restore or replace body parts.","cn":"修复：恢复或替代身体部件的支架与植入物。"},{"senses":"S3","en":"REWRITE: genetic engineering works at the level of DNA.","cn":"改写：基因工程在 DNA 层面操作。"},{"senses":"S5 · S6","en":"BEYOND MEDICINE: crops and microbes are engineered for food and for cleanup.","cn":"医学之外：作物与微生物被改造用于粮食与污染治理。"},{"senses":"S7 · S8","en":"INSTITUTION AND INVENTION: the department that practises it, and the design of parts nature never made.","cn":"机构与发明：从事它的院系，以及设计自然界从未有过的部件。"}]},"affixes":{"intro":{"en":"Bioengineering joins a Greek prefix for life to an English verbal noun; the suffix -ing turns the engineer's work into a field.","cn":"bioengineering 把表示生命的希腊语前缀接到一个英语动名词上；后缀 -ing 把工程师的工作变成一个领域。"},"latinIntro":{"en":"Greek bios supplies bio-. Latin ingenium, through Old French engin, supplies the engineering element; the -ing suffix is English.","cn":"bio- 来自希腊语 bios；engineering 的成分来自拉丁语 ingenium，经古法语 engin 进入英语；-ing 是英语后缀。"},"items":[{"word":"bioengineering","structure":"bio- + engineering","meaning":"engineering applied to living systems","meaningCN":"应用于生命系统的工程学","example":"Bioengineering offers a route to lab-grown organs.","exampleCN":"生物工程为实验室培育器官提供了一条路径。"},{"word":"bioengineer","structure":"bio- + engineer","meaning":"a person who engineers living systems","meaningCN":"对生命系统进行工程改造的人","example":"The bioengineer adjusted the scaffold's stiffness.","exampleCN":"生物工程师调整了支架的硬度。"},{"word":"bioengineered","structure":"bio- + engineered","meaning":"modified by biological engineering","meaningCN":"经生物工程改造的","example":"The supermarket sells bioengineered salmon.","exampleCN":"这家超市出售经生物工程改造的三文鱼。"},{"word":"bioreactor","structure":"bio- + reactor","meaning":"a vessel in which living cells make a product","meaningCN":"活细胞在其中生产产品的容器","example":"The bioreactor produced antibodies for a year.","exampleCN":"这个生物反应器生产了一年抗体。"},{"word":"biomedical","structure":"bio- + medical","meaning":"relating to biology and medicine together","meaningCN":"同时涉及生物学与医学的","example":"Biomedical engineers design artificial joints.","exampleCN":"生物医学工程师设计人工关节。"},{"word":"engineering","structure":"engineer + -ing","meaning":"the design and building of machines and systems","meaningCN":"机器与系统的设计与建造","example":"Engineering turned the idea into a working device.","exampleCN":"工程学把这个想法变成了可用的装置。"},{"word":"engineer","structure":"Old French engin + -eer","meaning":"a person who designs machines or systems","meaningCN":"设计机器或系统的人","example":"The engineer checked the load on the implant.","exampleCN":"工程师检查了植入物承受的载荷。"},{"word":"genetic","structure":"Greek genesis + -ic","meaning":"relating to genes or inheritance","meaningCN":"与基因或遗传有关的","example":"Genetic engineering edits the instructions of a cell.","exampleCN":"基因工程编辑细胞的指令。"},{"word":"scaffold","structure":"Middle English scaffald","meaning":"a temporary frame that supports growth","meaningCN":"支撑生长的临时框架","example":"Cells colonise the scaffold within days.","exampleCN":"细胞在几天内就占领了支架。"}],"latinEntries":[{"word":"βίος","structure":"Greek noun, 'life'","meaning":"life; a lifetime","meaningCN":"生命；一生"},{"word":"ingenium","structure":"Latin noun, 'native talent, clever device'","meaning":"inborn ability; an ingenious invention","meaningCN":"天赋；巧妙的发明"},{"word":"ingeniare","structure":"Latin verb from ingenium","meaning":"to devise, to contrive","meaningCN":"设计；谋划"}]}},{"word":"biotechnology","ipa_uk":"/ˌbaɪəʊtekˈnɒlədʒi/","ipa_us":"/ˌbaɪoʊtekˈnɑːlədʒi/","definition_zh":"生物技术；利用生物系统制造产品或提供服务","definition_en":"the use of living organisms or biological systems to make products or perform services","core_image":"发酵罐、培养皿与基因序列并排放在同一条生产线上","scene":"The company uses biotechnology to turn corn starch into a biodegradable plastic.","sceneCN":"这里 biotechnology 指「工业生物技术」（第 2 个义项：用微生物或酶进行工业转化）；句意：这家公司用生物技术把玉米淀粉变成可降解塑料。","pos":[{"tag":"n.","zh":"生物技术；生物工艺学；生物技术产业（指产业或公司时可作可数名词 a biotech）"}],"collocations":[{"phrase":"modern biotechnology","zh":"现代生物技术"},{"phrase":"agricultural biotechnology","zh":"农业生物技术"},{"phrase":"medical biotechnology","zh":"医药生物技术"},{"phrase":"biotechnology company","zh":"生物技术公司"},{"phrase":"biotechnology industry","zh":"生物技术产业"},{"phrase":"biotechnology products","zh":"生物技术产品"}],"forms":[{"label":"不可数用法","form":"biotechnology（指领域或技术总体时不可数）"},{"label":"可数缩略形式","form":"biotech（一家生物技术公司；生物技术）"},{"label":"复数（指多家公司）","form":"biotechs（生物技术公司，口语）"},{"label":"形容词","form":"biotechnological（生物技术的）"},{"label":"从业者","form":"biotechnologist（生物技术专家）"}],"derivatives":[{"word":"biotech","pos":"n./adj.","zh":"生物技术；生物技术公司（口语缩略）"},{"word":"biotechnological","pos":"adj.","zh":"生物技术的"},{"word":"biotechnologist","pos":"n.","zh":"生物技术专家"},{"word":"fermentation","pos":"n.","zh":"发酵"},{"word":"bioprocess","pos":"n.","zh":"生物工艺；生物过程"}],"senses":[{"no":"01","title":"Living systems as tools","titleCN":"把生命系统当作工具","definition":"the use of living organisms or their parts to make useful products","definitionCN":"利用活生物或其部件制造有用产品","example":"Biotechnology uses yeast to turn sugar into fuel.","exampleCN":"生物技术利用酵母把糖变成燃料。","why":"The word joins a Greek word for life to a Greek word for skilled craft, so its core claim is that life itself is the technique.","whyCN":"这个词把表示生命的希腊语词与表示技艺的希腊语词连在一起，核心主张就是：生命本身就是那门技艺。"},{"no":"02","title":"Industrial fermentation","titleCN":"工业发酵","definition":"the industrial use of microbes or enzymes to transform raw materials","definitionCN":"工业上利用微生物或酶转化原料","example":"Biotechnology in the brewery predates the word by centuries.","exampleCN":"啤酒厂里的生物技术比这个词本身早了几个世纪。","why":"Long before the name existed, brewing and cheesemaking already used living organisms, so the old crafts fall inside the new term.","whyCN":"在这个名字出现之前很久，酿酒与制酪已经在利用活生物，因此这些古老手艺也落在这个新词的范围里。"},{"no":"03","title":"Medical biotechnology","titleCN":"医药生物技术","definition":"the branch that makes drugs, vaccines and diagnostic tools from living systems","definitionCN":"用生命系统制造药物、疫苗与诊断工具的分支","example":"Medical biotechnology produced insulin from engineered bacteria.","exampleCN":"医药生物技术用经改造的细菌生产胰岛素。","why":"Medicine is the most visible market for the field, so the general word often means pharmaceutical production in practice.","whyCN":"医学是该领域最显眼的市场，因此在实践中这个总称常被用来指制药生产。"},{"no":"04","title":"Agricultural biotechnology","titleCN":"农业生物技术","definition":"the branch that improves crops and livestock through biological tools","definitionCN":"用生物工具改良作物与畜禽的分支","example":"Agricultural biotechnology created a rice that survives flooding.","exampleCN":"农业生物技术培育出一种耐涝水稻。","why":"Farming is where living systems are managed at scale, making it a natural home for the technology.","whyCN":"农业是大规模管理生命系统的场所，因此自然成为这项技术的主要落点。"},{"no":"05","title":"The industry","titleCN":"生物技术产业","definition":"the sector of companies and institutions that commercialise biological products","definitionCN":"把生物产品商业化的公司与机构构成的产业","example":"Biotechnology is one of the fastest-growing sectors in the region.","exampleCN":"生物技术是该地区增长最快的产业之一。","why":"A technology practised at scale becomes an industry, and the abstract noun then names the whole economic sector.","whyCN":"一项技术一旦大规模实践就成为产业，这个抽象名词于是指整个经济部门。"},{"no":"06","title":"A biotech company","titleCN":"生物技术公司","definition":"in financial and colloquial use, a company working in the sector","definitionCN":"财经与口语用法中指该领域的公司","example":"The biotech raised money for a gene therapy trial.","exampleCN":"这家生物技术公司为基因治疗试验筹集了资金。","why":"Industry names are routinely shortened to one countable noun, and biotech is the clipped form that does this work.","whyCN":"产业名常被缩短成可数名词，biotech 就是承担这一功能的缩略形式。"},{"no":"07","title":"The discipline","titleCN":"生物技术学（学科）","definition":"the academic subject that teaches biological production methods","definitionCN":"教授生物生产方法的学科","example":"She took a degree in biotechnology before moving into policy.","exampleCN":"她先取得生物技术学位，之后转入政策领域。","why":"Like any technology, it becomes a taught subject, and the same noun covers both the practice and the curriculum.","whyCN":"和任何技术一样，它也会成为被教授的科目，同一个名词因此既指实践，也指课程。"},{"no":"08","title":"Environmental biotechnology","titleCN":"环境生物技术","definition":"the branch that uses organisms to treat waste, clean pollution or produce energy","definitionCN":"用生物处理废物、治理污染或生产能源的分支","example":"Environmental biotechnology treats sewage with bacteria instead of chemicals.","exampleCN":"环境生物技术用细菌而不是化学品处理污水。","why":"Waste treatment is biological engineering in reverse: instead of making a product, the organisms remove a problem.","whyCN":"废物处理是反向的生物工程：生物体不是在制造产品，而是在消除问题。"},{"no":"09","title":"The 1919 coinage","titleCN":"1919 年的原始定义","definition":"the original sense proposed by Karl Ereky: the production of goods from raw materials with the help of living organisms","definitionCN":"Karl Ereky 提出的原义：借助活生物把原料转化为产品","example":"Ereky's biotechnology described pig farming as much as fermentation.","exampleCN":"Ereky 的 biotechnology 既指发酵，也指养猪。","why":"The coinage was about agricultural production, not genes; the historical sense explains why the word is broader than genetic engineering.","whyCN":"这个新造词原本针对农业生产，而不是基因；了解这一历史义，就能明白为什么这个词比基因工程更宽。"}],"etymology":{"intro":{"en":"Biotechnology is two Greek elements joined in the 20th century, with the second element meaning 'craft' rather than 'machine'.","cn":"biotechnology 是 20 世纪拼合的两个希腊语成分，第二个成分的意思是「技艺」，而不是「机器」。"},"items":[{"era":"GREEK BIOS","en":"bio- comes from Greek bios, 'life'. It became a productive scientific prefix in the 19th century.","cn":"bio- 出自希腊语 bios「生命」，在 19 世纪成为能产的科学前缀。"},{"era":"GREEK TECHNE","en":"technology comes from Greek tekhnē, 'craft, skill, art', plus -logia, 'study or discourse'. In Greek it meant systematic knowledge of an art, not hardware.","cn":"technology 出自希腊语 tekhnē「技艺、技能」加 -logia「研究、论述」。在希腊语里它指对一门技艺的系统知识，而不是硬件。"},{"era":"1919 COINAGE","en":"The compound biotechnology is generally attributed to Karl Ereky, a Hungarian agricultural engineer, who used it in 1919 for the production of goods from raw materials with living organisms. The attribution is widely accepted.","cn":"biotechnology 一般认为由匈牙利农业工程师 Karl Ereky 于 1919 年提出，用来指借助活生物把原料转化为产品。这一归属被广泛接受。"},{"era":"MOLECULAR REDEFINITION","en":"After the discovery of recombinant DNA in the 1970s, biotechnology shifted toward genetic engineering and the pharmaceutical industry.","cn":"1970 年代重组 DNA 技术出现后，生物技术转向基因工程与制药产业。"},{"era":"SECTOR AND CLIP","en":"In the 1980s and 1990s the word named an investment sector, and the clipped form biotech became everyday usage.","cn":"1980 至 1990 年代，这个词指一个投资板块，缩略形式 biotech 成为日常说法。"}]},"similar":{"note":{"en":"The first group separates compounds that share the bio- prefix; the second separates production technology from the sciences that support it.","cn":"第一组区分共享 bio- 前缀的复合词；第二组把生产技术与其支撑科学区分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bioengineering","ipa":"/ˌbaɪəʊendʒɪˈnɪərɪŋ/","tag":"design emphasis","definition":"Engineering applied to living systems, especially tissue and devices; biotechnology stresses making products, while bioengineering stresses design.","definitionCN":"把工程用于生命系统，尤其是组织与器械；生物技术强调制造产品，生物工程强调设计。"},{"word":"biochemistry","ipa":"/ˌbaɪəʊˈkemɪstri/","tag":"science, not production","definition":"The study of the chemistry of life; it supplies methods but does not itself mean industrial production.","definitionCN":"研究生命化学的学科，提供方法，但本身不指工业生产。"},{"word":"biotech","ipa":"/ˈbaɪəʊtek/","tag":"clipped form","definition":"The short form of biotechnology, and in finance a countable noun for a company in the sector.","definitionCN":"biotechnology 的缩略形式，在财经语境中是可数名词，指该领域的公司。"}]},{"heading":"NEAR MEANING","entries":[{"word":"genetic engineering","ipa":"/dʒeˈnetɪk endʒɪˈnɪərɪŋ/","tag":"one technique","definition":"The deliberate alteration of DNA; it is a flagship technique within biotechnology, not the whole of it.","definitionCN":"指有目的地改造 DNA，是生物技术中的旗舰技术，而不是全部。"},{"word":"biomanufacturing","ipa":"/ˌbaɪəʊmænjuˈfæktʃərɪŋ/","tag":"production only","definition":"The manufacturing side of biotechnology: using cells to make products at industrial scale.","definitionCN":"生物技术的生产侧：用细胞在工业规模上制造产品。"},{"word":"technology","ipa":"/tekˈnɒlədʒi/","tag":"general term","definition":"The application of scientific knowledge for practical purposes; biotechnology is its life-science branch.","definitionCN":"把科学知识用于实际目的的总称；生物技术是它在生命科学中的分支。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"bio- 'life' + technology 'craft knowledge': using life as a craft.","cn":"bio-「生命」+ technology「技艺知识」：把生命当作一门手艺来用。"},{"en":"The family runs biotech, biotechnological, biotechnologist and bioprocess.","cn":"同族词有 biotech、biotechnological、biotechnologist、bioprocess。"},{"en":"Fixed phrases: agricultural biotechnology, medical biotechnology, biotechnology industry.","cn":"固定搭配：农业生物技术、医药生物技术、生物技术产业。"},{"en":"Beer and cheese are biotechnology without the laboratory.","cn":"啤酒与奶酪就是没有实验室的生物技术。"},{"en":"The 1919 sense was about farming, not genes.","cn":"1919 年的原义讲的是农业，而不是基因。"}],"abstract":[{"en":"Think of a brewery as a factory whose machines are alive.","cn":"把啤酒厂想象成一座机器是活的工厂。"},{"en":"A gene is an instruction card that biotechnology can copy, cut or paste.","cn":"基因是一张指令卡，生物技术可以复制、剪接或粘贴它。"},{"en":"The biotech sector is a greenhouse: small firms grow on investment until they flower or fail.","cn":"生物技术产业像一间温室：小公司靠投资生长，直到开花或枯萎。"}]},"examples":[{"en":"Biotechnology has turned bacteria into factories for insulin.","cn":"生物技术已经把细菌变成生产胰岛素的工厂。"},{"en":"The country invests heavily in agricultural biotechnology.","cn":"该国在农业生物技术上投入很大。"},{"en":"Regulators require safety tests before a biotechnology product reaches the market.","cn":"监管机构要求生物技术产品上市前完成安全检测。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「bio（生命）+ technology（技术）」→ 用生命做技术 → 生物技术","word":"biotechnology"},"root":"希腊语 bios「生命」+ 希腊语 tekhnē「技艺」与 -logia「研究」→ technology；20 世纪合成为 biotechnology（一般认为由 Karl Ereky 于 1919 年提出）。","sensesIntro":{"en":"Nine senses run from the core idea of life as a technique through fermentation, medicine, agriculture, industry, companies, teaching, environmental use, and back to the word's original 1919 meaning.","cn":"九个义项从「把生命当作技艺」这一核心出发，经过发酵、医药、农业、产业、公司、教学、环境应用，最后回到 1919 年的原始含义。"},"semanticMap":{"core":{"en":"CORE IMAGE: fermentation tanks, petri dishes and gene sequences standing on one production line.","cn":"核心意象：发酵罐、培养皿与基因序列并排站在同一条生产线上。"},"chain":["LIFE AS TECHNIQUE","FERMENT AND TRANSFORM","MAKE MEDICINES","IMPROVE CROPS","BUILD AN INDUSTRY","SELL AND REGULATE"],"branches":[{"senses":"S1 · S9","en":"THE CORE AND ITS ORIGIN: life used as a craft, first defined for agriculture in 1919.","cn":"核心与起源：把生命当作技艺，最早在 1919 年为农业定义。"},{"senses":"S2","en":"FERMENTATION: the oldest practice, now run at industrial scale.","cn":"发酵：最古老的做法，如今在工业规模上运行。"},{"senses":"S3 · S4","en":"PRODUCTS: medicines from cells, and crops improved by biological tools.","cn":"产品：由细胞制成的药物，以及用生物工具改良的作物。"},{"senses":"S5 · S6","en":"ECONOMY: the sector as a whole and the single company within it.","cn":"经济：整个产业部门，以及其中的单家公司。"},{"senses":"S7 · S8","en":"INSTITUTION AND ENVIRONMENT: the taught discipline, and organisms put to work on waste.","cn":"机构与环境：被教授的学科，以及被派去处理废物的生物。"}]},"affixes":{"intro":{"en":"Biotechnology is a Greek-Greek compound; both elements still carry their original senses of life and craft.","cn":"biotechnology 是希腊语与希腊语的复合词，两个成分仍保留「生命」与「技艺」的原义。"},"latinIntro":{"en":"Both elements are Greek: bios for life, tekhnē for craft, with -logia for systematic study. No Latin root is involved, though the word reached English through scientific Latin and French.","cn":"两个成分都来自希腊语：bios 表示生命，tekhnē 表示技艺，-logia 表示系统研究。其中没有拉丁词根，但这个词经科学拉丁语与法语进入英语。"},"items":[{"word":"biotechnology","structure":"bio- + technology","meaning":"the craft of using living systems","meaningCN":"利用生命系统的技艺","example":"Biotechnology is governed by both science and patent law.","exampleCN":"生物技术同时受科学与专利法约束。"},{"word":"biotech","structure":"clipped from biotechnology","meaning":"the field, or a company in it","meaningCN":"该领域，或该领域的一家公司","example":"The biotech opened its new laboratory in spring.","exampleCN":"这家生物技术公司在春季启用了新实验室。"},{"word":"biotechnological","structure":"biotechnology + -ical","meaning":"relating to biotechnology","meaningCN":"与生物技术有关的","example":"The biotechnological process replaced a chemical one.","exampleCN":"这一生物技术工艺取代了化学工艺。"},{"word":"biotechnologist","structure":"biotechnology + -ist","meaning":"a person who practises biotechnology","meaningCN":"从事生物技术的人","example":"The biotechnologist scaled up the fermentation.","exampleCN":"这位生物技术专家放大了发酵规模。"},{"word":"biology","structure":"bio- + -logy","meaning":"the study of life","meaningCN":"研究生命的学科","example":"Biology supplies the facts biotechnology uses.","exampleCN":"生物学提供生物技术所用的事实。"},{"word":"technology","structure":"tekhnē + -logia","meaning":"systematic knowledge of a craft","meaningCN":"关于一门技艺的系统知识","example":"Technology changes faster than the laws that govern it.","exampleCN":"技术变化得比管辖它的法律更快。"},{"word":"fermentation","structure":"Latin fervere (to boil) + -ation","meaning":"the conversion of sugar by microbes","meaningCN":"微生物对糖的转化","example":"Fermentation turns grape juice into wine.","exampleCN":"发酵把葡萄汁变成葡萄酒。"},{"word":"bioprocess","structure":"bio- + process","meaning":"an industrial process using living cells","meaningCN":"利用活细胞的工业过程","example":"The bioprocess runs at thirty degrees Celsius.","exampleCN":"该生物工艺在摄氏三十度下运行。"},{"word":"bioreactor","structure":"bio- + reactor","meaning":"a vessel for growing cells or producing their products","meaningCN":"培养细胞或生产其产物的容器","example":"The bioreactor holds two thousand litres.","exampleCN":"这个生物反应器容量为两千升。"}],"latinEntries":[{"word":"βίος","structure":"Greek noun, 'life'","meaning":"life; a lifetime","meaningCN":"生命；一生"},{"word":"τέχνη","structure":"Greek noun, 'craft, skill'","meaning":"an art or skilled practice","meaningCN":"技艺；技能"},{"word":"-λογία","structure":"Greek suffix, 'study, discourse'","meaning":"a field of systematic knowledge","meaningCN":"系统知识的领域"}]}},{"word":"cellular","ipa_uk":"/ˈseljələ(r)/","ipa_us":"/ˈseljələr/","definition_zh":"细胞的；由细胞组成的；蜂窝式的","definition_en":"relating to cells, made of cells, or organised in a honeycomb pattern","core_image":"一排小房间彼此相邻，每个房间里都有一套完整的生命装置","scene":"The new phone network divides the city into small cellular areas.","sceneCN":"这里 cellular 指「蜂窝式的」（第 4 个义项：把覆盖区分成许多小格来复用频率）；句意：新的电话网络把城市划分成许多蜂窝式小区。","pos":[{"tag":"adj.","zh":"细胞的；由细胞组成的；蜂窝式的；（电信）蜂窝网络的"}],"collocations":[{"phrase":"cellular structure","zh":"细胞结构"},{"phrase":"cellular biology","zh":"细胞生物学"},{"phrase":"cellular network","zh":"蜂窝网络"},{"phrase":"cellular phone","zh":"蜂窝电话；手机"},{"phrase":"cellular immunity","zh":"细胞免疫"},{"phrase":"cellular material","zh":"蜂窝材料"}],"forms":[{"label":"比较级","form":"more cellular"},{"label":"最高级","form":"most cellular"},{"label":"名词形式","form":"cellularity（细胞构成；细胞数量）"},{"label":"副词形式","form":"cellularly（在细胞层面；蜂窝状地）"}],"derivatives":[{"word":"cell","pos":"n.","zh":"细胞；小室；电池"},{"word":"cellularity","pos":"n.","zh":"细胞构成；细胞密度"},{"word":"cellulose","pos":"n.","zh":"纤维素"},{"word":"cellulite","pos":"n.","zh":"脂肪团（美容用语）"},{"word":"unicellular","pos":"adj.","zh":"单细胞的"}],"senses":[{"no":"01","title":"Made of cells","titleCN":"由细胞组成的","definition":"consisting of or built from biological cells","definitionCN":"由生物细胞构成或组成的","example":"Muscle is a cellular tissue with many nuclei per fibre.","exampleCN":"肌肉是一种多核的细胞组织。","why":"The adjective form of cell simply says that something is made of the units biology calls cells.","whyCN":"cell 的形容词形式最直接的意思就是：某物由生物学称为「细胞」的那些单元构成。"},{"no":"02","title":"Of cell biology","titleCN":"细胞层面的；细胞生物学的","definition":"relating to the study or level of cells","definitionCN":"与细胞研究或细胞层面有关的","example":"Cellular biology examines how organelles cooperate.","exampleCN":"细胞生物学考察各种细胞器如何协作。","why":"Once cells are a level of organisation, the adjective labels the science and the scale that studies that level.","whyCN":"一旦细胞成为一个组织层次，这个形容词就用来标记研究该层次的科学与尺度。"},{"no":"03","title":"Inside a cell","titleCN":"细胞内的","definition":"happening or located inside a cell","definitionCN":"发生在细胞内或位于细胞内的","example":"Cellular responses to stress begin within minutes.","exampleCN":"细胞对压力的反应在几分钟内就开始。","why":"A response that occurs inside the cell belongs to the cell, so the adjective shifts from composition to location and process.","whyCN":"发生在细胞内部的反应属于细胞，于是这个形容词从「由什么构成」转向「在哪里发生」。"},{"no":"04","title":"Honeycomb network","titleCN":"蜂窝式网络","definition":"describing a radio network that divides an area into small overlapping cells","definitionCN":"指把一片区域划分为许多相互重叠的小区的无线电网络","example":"Cellular coverage in the valley improved after two new towers went up.","exampleCN":"两座新塔建成后，山谷里的蜂窝网络覆盖改善了。","why":"Radio engineers borrowed the honeycomb image because each base station covers a small cell and neighbouring cells reuse frequencies.","whyCN":"无线电工程师借用了蜂巢的意象，因为每个基站覆盖一个小格，相邻小格可以重复使用频率。"},{"no":"05","title":"Cellular phone","titleCN":"蜂窝电话；手机","definition":"relating to a mobile telephone system that uses cellular cells","definitionCN":"指使用蜂窝小区的移动电话系统","example":"He called from a cellular phone while crossing the desert.","exampleCN":"他穿越沙漠时用蜂窝电话打来。","why":"The phone is named after the network that makes it work, so cellular became an everyday word for mobile.","whyCN":"这种电话因支撑它的网络而得名，因此 cellular 在日常英语里就成了「移动的」之意。"},{"no":"06","title":"Cell-mediated immunity","titleCN":"细胞免疫的","definition":"describing immunity carried out by living cells rather than by antibodies alone","definitionCN":"指由活细胞而不是仅由抗体执行的免疫","example":"Cellular immunity keeps the virus from spreading between cells.","exampleCN":"细胞免疫阻止病毒在细胞之间扩散。","why":"Immunology contrasts cell-based defence with antibody-based defence, and the adjective marks the cell side of that contrast.","whyCN":"免疫学把以细胞为主的防御与以抗体为主的防御相对照，这个形容词标出对照中的细胞一侧。"},{"no":"07","title":"Porous structure","titleCN":"蜂窝状的；多孔的","definition":"describing a material or structure full of small open compartments","definitionCN":"指充满小空腔的材料或结构","example":"Cellular concrete is light because air fills its pores.","exampleCN":"蜂窝混凝土很轻，因为空气填满了它的孔隙。","why":"The honeycomb image, once borrowed by engineers, also describes foams, concrete and packaging with many small cells.","whyCN":"蜂巢意象一旦被工程师借用，也能描述泡沫、混凝土与包装材料里那许多小格。"},{"no":"08","title":"Cellular automaton","titleCN":"元胞自动机的","definition":"in computing, describing a grid of simple units whose states update by fixed rules","definitionCN":"计算领域指由简单单元组成的网格，按固定规则更新状态","example":"The model is a cellular automaton that simulates traffic flow.","exampleCN":"该模型是一个模拟交通流的元胞自动机。","why":"Each grid square acts like a tiny cell, so mathematicians reused the biological word for a lattice of rule-following units.","whyCN":"每个网格方块像一个小细胞，因此数学家把生物学词汇借用来指一张按规则运行的格点。"},{"no":"09","title":"Solitary confinement","titleCN":"单人牢房式的","definition":"in penal history, describing confinement of one prisoner to one cell","definitionCN":"刑罚史中指把一名囚犯单独关在一间牢房里","example":"The prison abolished cellular confinement for long sentences.","exampleCN":"该监狱废除了对长期刑犯使用单人牢房的做法。","why":"The oldest sense of cell is a small room, and cellular keeps that history alive in the language of prisons.","whyCN":"cell 最古老的意义就是小房间，cellular 在监狱用语中保留了这段历史。"}],"etymology":{"intro":{"en":"Cellular is a Latin diminutive turned adjective: a small room becomes a biological unit, and then a honeycomb pattern in engineering.","cn":"cellular 是拉丁语指小词变来的形容词：小房间先变成生物学单元，再变成工程里的蜂窝结构。"},"items":[{"era":"LATIN CELLA","en":"Latin cella meant a small room, a storeroom or a shrine. It is related to cellarium, a storehouse, and to the English words cellar and cell.","cn":"拉丁语 cella 指小房间、储藏室或神龛。它与 cellarium「仓库」同源，也衍生出英语 cellar 与 cell。"},{"era":"LATIN CELLULA","en":"The diminutive cellula, 'little room', supplied the base for the adjective. The suffix -aris became English -ar, meaning 'relating to'.","cn":"指小形式 cellula「小房间」提供了形容词的词基；后缀 -aris 变成英语 -ar，表示「与……有关的」。"},{"era":"1665 MICROSCOPE","en":"Robert Hooke described the small compartments of cork as cells in 1665, because they looked like the rooms of a monastery. The biological sense spread from that image.","cn":"1665 年，Robert Hooke 把软木中的小隔间称为 cell，因为它们看起来像修道院的小房间。生物学的义项就从这幅图像扩散开来。"},{"era":"NINETEENTH-CENTURY BIOLOGY","en":"As cell theory matured in the 19th century, cellular became the standard adjective for 'of cells'. The first uses are not precisely dated.","cn":"随着 19 世纪细胞学说成熟，cellular 成为表示「细胞的」的标准形容词。最早用例的年份并不精确。"},{"era":"TWENTIETH-CENTURY RADIO","en":"Radio engineers in the 1940s and 1950s divided coverage into cells and called the system cellular; the telephone sense followed.","cn":"20 世纪 40 至 50 年代，无线电工程师把覆盖区分成一个个小区，称该系统为 cellular；电话义随后出现。"}]},"similar":{"note":{"en":"The first group separates words that look like cellular or share its root; the second separates 'of cells' from other levels and from the radio sense.","cn":"第一组区分看起来像 cellular 或共享词根的词；第二组把「细胞的」与其它层次以及无线电义分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cell","ipa":"/sel/","tag":"noun, not adjective","definition":"The unit itself, or a small room or battery; cellular is the adjective that describes things made of or belonging to cells.","definitionCN":"指单元本身，也可指小房间或电池；cellular 是描述「由细胞构成或属于细胞」的形容词。"},{"word":"cellar","ipa":"/ˈselə(r)/","tag":"same Latin root, different word","definition":"A storage room below ground, from the same Latin cella but with a different vowel and meaning; it has nothing to do with biology.","definitionCN":"指地下储藏室，与拉丁语 cella 同源，但元音与词义都不同，与生物学无关。"},{"word":"cellulose","ipa":"/ˈseljuləʊs/","tag":"material, not adjective","definition":"The fibrous substance in plant cell walls; it is named from cellula but is a noun for a material, not a general adjective.","definitionCN":"指植物细胞壁中的纤维物质，得名于 cellula，但是表示材料的可数名词，不是一般形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mobile","ipa":"/ˈməʊbaɪl/","tag":"everyday synonym of the phone sense","definition":"In everyday British English, the ordinary word for a phone that moves with its user; cellular is the technical name of the network behind it.","definitionCN":"在英式日常英语里指随身携带的电话；cellular 是支撑它的网络的技术名称。"},{"word":"biological","ipa":"/ˌbaɪəˈlɒdʒɪkl/","tag":"broader level","definition":"Relating to life in general; cellular is narrower because it names one level of biological organisation.","definitionCN":"泛指与生命有关；cellular 更窄，因为它只指生物组织的一个层次。"},{"word":"porous","ipa":"/ˈpɔːrəs/","tag":"property, not pattern","definition":"Full of holes that let fluid through; cellular describes a honeycomb pattern of compartments, which may or may not be open.","definitionCN":"指布满可让流体通过的孔；cellular 描述蜂巢式的隔间格局，这些隔间未必相通。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"cell + -ular: belonging to cells, as a small room belongs to a building.","cn":"cell + -ular：属于细胞的，就像小房间属于一栋楼。"},{"en":"The family runs cell, cellularity, cellulose, cellulite and unicellular.","cn":"同族词有 cell、cellularity、cellulose、cellulite、unicellular。"},{"en":"Fixed phrases: cellular structure, cellular network, cellular immunity, cellular phone.","cn":"固定搭配：细胞结构、蜂窝网络、细胞免疫、蜂窝电话。"},{"en":"The honeycomb sense is the same image as cork under Hooke's microscope.","cn":"蜂窝义与 Hooke 显微镜下软木的图像是同一幅图。"},{"en":"The phone sense is technical history hiding inside an everyday word.","cn":"手机义是一个日常词里藏着的技术史。"}],"abstract":[{"en":"Think of a apartment block: each room is a cell, and the whole building is cellular.","cn":"想象一栋公寓楼：每个房间是一个细胞，整栋楼就是 cellular。"},{"en":"A cellular network is a honeycomb laid over a city, each hexagon a small listening post.","cn":"蜂窝网络就是铺在城市上的一张蜂巢，每个六边形都是一个小监听站。"},{"en":"A cellular automaton is a crowd where each person follows only the neighbours.","cn":"元胞自动机就像一群人，每个人只跟着邻居行动。"}]},"examples":[{"en":"Cellular structure differs sharply between plant and animal tissue.","cn":"植物组织与动物组织的细胞结构差别很大。"},{"en":"The company upgraded its cellular network in rural districts.","cn":"该公司升级了农村地区的蜂窝网络。"},{"en":"Cellular immunity depends on T cells rather than on antibodies alone.","cn":"细胞免疫依赖 T 细胞，而不只是抗体。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cell（小房间/细胞）+ -ular」→ 像小房间一样一格一格的 → 细胞的、蜂窝式的","word":"cellular"},"root":"拉丁语 cella「小房间、储藏室」→ 指小形式 cellula「小房间」→ 形容词 cellula + -aris；英语 cellular。","sensesIntro":{"en":"Nine senses start from the small room inside the Latin word: cells as units, as a level of study, as a location, as a honeycomb network, a phone, an immune mode, a porous material, a computing grid, and at last a prison cell.","cn":"九个义项都从拉丁词里那间「小房间」出发：细胞作为单元、作为研究层次、作为位置、作为蜂窝网络、作为电话、作为免疫方式、作为多孔材料、作为计算网格，最后回到牢房。"},"semanticMap":{"core":{"en":"CORE IMAGE: a row of small rooms side by side, each holding a complete living kit.","cn":"核心意象：一排彼此相邻的小房间，每间都装着一套完整的生命装置。"},"chain":["SMALL ROOM","UNIT OF LIFE","LEVEL OF STUDY","INSIDE THE UNIT","HONEYCOMB PATTERN","NETWORK AND GRID"],"branches":[{"senses":"S1 · S9","en":"THE SMALL ROOM: the oldest image links biological cells and prison cells.","cn":"小房间：最古老的意象把生物细胞与牢房连在一起。"},{"senses":"S2 · S3","en":"THE BIOLOGICAL LEVEL: the science of cells, and processes located inside them.","cn":"生物学层次：研究细胞的科学，以及发生在细胞内部的过程。"},{"senses":"S4 · S5","en":"THE HONEYCOMB NETWORK: radio cells and the phone named after them.","cn":"蜂窝网络：无线电小区以及因之得名的电话。"},{"senses":"S6","en":"CELL-BASED DEFENCE: immunity carried out by living cells.","cn":"以细胞为主的防御：由活细胞执行的免疫。"},{"senses":"S7 · S8","en":"PATTERN AND RULE: porous materials and computing grids reuse the compartment image.","cn":"格局与规则：多孔材料与计算网格重复使用「隔间」的意象。"}]},"affixes":{"intro":{"en":"Cellular is a noun plus a Latin adjective ending: cell, from a diminutive of 'room', takes -ular.","cn":"cellular 是名词加拉丁形容词词尾：cell 来自「房间」的指小形式，再加 -ular。"},"latinIntro":{"en":"Latin cella and its diminutive cellula underlie cell, cellar, cellular, cellulose and cellulite; -aris supplies the English ending -ar.","cn":"拉丁语 cella 及其指小形式 cellula 支撑了 cell、cellar、cellular、cellulose、cellulite；-aris 提供英语词尾 -ar。"},"items":[{"word":"cellular","structure":"cellula + -aris → cell + -ular","meaning":"relating to cells; made of small compartments","meaningCN":"与细胞有关的；由小隔间构成的","example":"The tissue has a cellular architecture.","exampleCN":"该组织具有细胞结构。"},{"word":"cell","structure":"Latin cella, 'small room'","meaning":"the basic unit of life; a small room","meaningCN":"生命的基本单元；小房间","example":"Every cell carries the same DNA.","exampleCN":"每个细胞都携带相同的 DNA。"},{"word":"cellar","structure":"Latin cellarium, 'storehouse'","meaning":"an underground storage room","meaningCN":"地下储藏室","example":"The wine is kept in a cool cellar.","exampleCN":"葡萄酒存放在阴凉的地窖里。"},{"word":"cellulose","structure":"cellula + -ose","meaning":"the fibre of plant cell walls","meaningCN":"植物细胞壁的纤维","example":"Paper is mostly cellulose.","exampleCN":"纸的主要成分是纤维素。"},{"word":"cellulite","structure":"cellula + -ite","meaning":"dimpled fat under the skin","meaningCN":"皮下凹凸不平的脂肪","example":"Creams cannot remove cellulite.","exampleCN":"乳霜无法去除脂肪团。"},{"word":"unicellular","structure":"uni- (one) + cellular","meaning":"made of a single cell","meaningCN":"由单个细胞构成的","example":"Bacteria are unicellular organisms.","exampleCN":"细菌是单细胞生物。"},{"word":"multicellular","structure":"multi- (many) + cellular","meaning":"made of many cells","meaningCN":"由许多细胞构成的","example":"Multicellular life appeared late in Earth's history.","exampleCN":"多细胞生命在地球历史上出现较晚。"},{"word":"intracellular","structure":"intra- (within) + cellular","meaning":"inside a cell","meaningCN":"细胞内部的","example":"The parasite hides in an intracellular niche.","exampleCN":"这种寄生生物藏在细胞内的一个生态位里。"},{"word":"extracellular","structure":"extra- (outside) + cellular","meaning":"outside the cell","meaningCN":"细胞外的","example":"Collagen forms an extracellular network.","exampleCN":"胶原蛋白构成一张细胞外网络。"}],"latinEntries":[{"word":"cella","structure":"Latin noun, 'small room, storeroom'","meaning":"a chamber; a store room","meaningCN":"小室；储藏室"},{"word":"cellula","structure":"Latin diminutive of cella","meaning":"a little room","meaningCN":"小房间"},{"word":"cellarium","structure":"Latin noun from cella","meaning":"a storehouse","meaningCN":"仓库；储藏处"}]}},{"word":"cell","ipa_uk":"/sel/","ipa_us":"/sel/","definition_zh":"细胞；小室；牢房；电池","definition_en":"the basic unit of living things, or a small enclosed room, or a device that stores electric charge","core_image":"一间有墙的小屋，里面装着维持生命的一整套机器","scene":"Each cell in the body carries the same set of genes but reads only some of them.","sceneCN":"这里 cell 指「细胞」（第 1 个义项：生物体的基本单元）；句意：体内每个细胞都携带同一套基因，但只读取其中一部分。","pos":[{"tag":"n.","zh":"细胞；小室；（监狱的）单人牢房；电池；蜂房的巢室；（组织中的）小隔间"}],"collocations":[{"phrase":"cell membrane","zh":"细胞膜"},{"phrase":"stem cell","zh":"干细胞"},{"phrase":"cell division","zh":"细胞分裂"},{"phrase":"prison cell","zh":"牢房"},{"phrase":"solar cell","zh":"太阳能电池"},{"phrase":"fuel cell","zh":"燃料电池"},{"phrase":"blood cell","zh":"血细胞"}],"forms":[{"label":"复数","form":"cells"},{"label":"形容词","form":"cellular（细胞的；蜂窝式的）"},{"label":"指小名词","form":"cellule（小细胞，解剖学用语）"},{"label":"复合成分","form":"cell-（用于 cell wall、cell line 等复合词）"}],"derivatives":[{"word":"cellular","pos":"adj.","zh":"细胞的；蜂窝式的"},{"word":"cellulose","pos":"n.","zh":"纤维素"},{"word":"cellar","pos":"n.","zh":"地窖；酒窖"},{"word":"cellmate","pos":"n.","zh":"同牢房的囚犯"},{"word":"unicellular","pos":"adj.","zh":"单细胞的"},{"word":"cellule","pos":"n.","zh":"小细胞（解剖学术语）"}],"senses":[{"no":"01","title":"Unit of life","titleCN":"细胞（生命的基本单元）","definition":"the smallest structural and functional unit of a living organism","definitionCN":"生物体结构与功能的最小单位","example":"A human body contains trillions of cells.","exampleCN":"人体含有数万亿个细胞。","why":"Hooke's microscope showed cork divided into little rooms, and the word for a room became the name of life's smallest compartment.","whyCN":"Hooke 的显微镜显示软木被分成许多小房间，于是表示「房间」的词成了生命最小隔间的名字。"},{"no":"02","title":"A small room","titleCN":"小室；单间","definition":"a small room, especially one in a prison or a monastery","definitionCN":"小房间，尤指牢房或修道院的单间","example":"The monk returned to his cell before dawn.","exampleCN":"修士天亮前回到自己的小室。","why":"This is the original sense: cella in Latin was a small room or storeroom, and the religious and penal senses preserve it.","whyCN":"这是本义：拉丁语 cella 就是小房间或储藏室，宗教与监狱义都保留了它。"},{"no":"03","title":"Prison cell","titleCN":"牢房","definition":"a room in a prison where a prisoner is confined","definitionCN":"监狱中关押囚犯的房间","example":"The prisoner was locked in a cell for twenty hours a day.","exampleCN":"这名囚犯每天被锁在牢房里二十小时。","why":"A prison room is a small closed compartment, so the oldest sense of the word narrowed into the language of punishment.","whyCN":"牢房就是一个小而封闭的隔间，于是这个词最古老的意义收窄成了刑罚用语。"},{"no":"04","title":"Battery cell","titleCN":"电池（单体）","definition":"a single unit that converts chemical energy into electricity","definitionCN":"把化学能转化为电能的单个单元","example":"One faulty cell can drain the whole battery pack.","exampleCN":"一个坏掉的电池单体就能耗尽整组电池。","why":"A battery is a container of separate compartments, and each compartment holding a reaction was called a cell after the same room image.","whyCN":"电池是一组独立隔间的容器，每个装着反应的隔间也按同一个「房间」意象被称为 cell。"},{"no":"05","title":"Honeycomb chamber","titleCN":"蜂房的巢室","definition":"one of the six-sided compartments of a honeycomb","definitionCN":"蜂巢中一个六边形的巢室","example":"Each cell of the comb holds a single larva.","exampleCN":"蜂巢的每个巢室装着一只幼虫。","why":"The hexagonal chambers of a comb are literally small rooms, so beekeepers use the word without any metaphor.","whyCN":"蜂巢的六边形格子字面上就是小房间，因此养蜂人用这个词并不带比喻。"},{"no":"06","title":"Small group of people","titleCN":"小组；支部","definition":"a small group of people working together, especially a secret political group","definitionCN":"一起工作的一小群人，尤指秘密政治小组","example":"The movement began as a handful of cells in three cities.","exampleCN":"这场运动最初只是三座城市里的几个小组。","why":"An organisation split into small self-contained units borrows the compartment image, so a cell is both a room and a team inside one.","whyCN":"被分成小型自足单元的组织借用了隔间意象，于是 cell 既是房间，也是房间里的一小队人。"},{"no":"07","title":"Table cell","titleCN":"表格单元格","definition":"a single box in a table or spreadsheet where rows and columns meet","definitionCN":"表格或电子表格中行列相交的单个方格","example":"Type the total into the last cell of the row.","exampleCN":"把合计输入这一行的最后一个单元格。","why":"A table is a grid of little rooms, and computing kept the room metaphor for the smallest addressable box.","whyCN":"表格就是一张小房间的网格，计算机领域保留了这个房间比喻，用来指最小的可寻址方格。"},{"no":"08","title":"Cell in a network","titleCN":"网络小区","definition":"a small geographic area served by one radio base station","definitionCN":"由一个无线电基站服务的一小片地理区域","example":"The phone hands over to the next cell as you drive north.","exampleCN":"你向北行驶时，手机切换到了下一个小区。","why":"Engineers divided coverage into honeycomb compartments, and each one inherited the name of the comb's chamber.","whyCN":"工程师把覆盖区分成蜂巢式的格子，每一格都继承了蜂巢巢室的名字。"},{"no":"09","title":"Cell in a spreadsheet formula","titleCN":"单元格引用","definition":"in software, a single position identified by column and row, such as A1","definitionCN":"软件中由列与行标识的单个位置，如 A1","example":"The formula in cell B2 adds the two cells to its left.","exampleCN":"B2 单元格中的公式把左边两个单元格相加。","why":"Once a table box is a cell, formulas need to name positions, and the addressable box becomes the unit of reference.","whyCN":"一旦表格方格被称为 cell，公式就需要指名位置，这个可寻址的方格就成了引用单位。"}],"etymology":{"intro":{"en":"Cell is Latin cella, a small room, which passed through a diminutive into English and then into biology, prisons, batteries and radio.","cn":"cell 来自拉丁语 cella「小房间」，经指小形式进入英语，随后进入生物学、监狱、电池与无线电等领域。"},"items":[{"era":"LATIN CELLA","en":"Latin cella meant a small room, a storeroom or a shrine chamber. Its diminutive cellula, 'little room', is the source of the adjective cellular.","cn":"拉丁语 cella 指小房间、储藏室或神龛内室。其指小形式 cellula「小房间」是形容词 cellular 的来源。"},{"era":"OLD ENGLISH CELL","en":"English took cell from Old French celle and directly from Latin, first in the sense of a monastic cell or a small dwelling.","cn":"英语经古法语 celle 并直接从拉丁语借入 cell，最初指修道院单间或小居所。"},{"era":"1665 HOOKE","en":"Robert Hooke's Micrographia (1665) described the compartments of cork as cells. The biological sense is generally credited to this use, though the word already meant 'small room'.","cn":"Robert Hooke 的《显微图谱》（1665）把软木的小隔间称为 cells。生物学的义项一般认为由此而来，尽管这个词本已表示「小房间」。"},{"era":"EIGHTEENTH-CENTURY PRISONS","en":"The penal sense of a confined room is recorded from the 18th century, when prison reform created separate cells.","cn":"指囚禁房间的刑罚义见于 18 世纪，当时监狱改革设立了单人牢房。"},{"era":"NINETEENTH-CENTURY BATTERIES","en":"Volta's pile and later batteries were built of separate compartments, and each was called a cell by the mid-19th century.","cn":"伏打电堆及其后的电池由独立隔间构成，到 19 世纪中叶每个隔间都称为一个 cell。"},{"era":"TWENTIETH-CENTURY RADIO","en":"Radio engineers in the 1940s and 1950s reused the honeycomb image, giving cell its network sense.","cn":"20 世纪 40 至 50 年代的无线电工程师重复使用蜂巢意象，使 cell 获得了网络义。"}]},"similar":{"note":{"en":"The first group holds words that look like cell or share its Latin root; the second holds words for the same objects under other names.","cn":"第一组是看起来像 cell 或与它共享拉丁词根的词；第二组是用别的名字指同一类事物的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cellar","ipa":"/ˈselə(r)/","tag":"room below ground","definition":"A storage room under a house, from Latin cellarium; it shares the root but is never a biological unit.","definitionCN":"指房屋下方的储藏室，来自拉丁语 cellarium；同源，但从不指生物单元。"},{"word":"cellular","ipa":"/ˈseljələ(r)/","tag":"the adjective","definition":"The adjective meaning 'of cells' or 'honeycomb-like'; cell is the countable noun, cellular describes.","definitionCN":"是形容词，意为「细胞的」或「蜂窝状的」；cell 是可数名词，cellular 用于描述。"},{"word":"cellule","ipa":"/ˈseljuːl/","tag":"technical diminutive","definition":"A rare anatomical noun for a small cell or chamber; it is a specialist term, not a general synonym of cell.","definitionCN":"解剖学中少见的指小名词，指小细胞或小腔；属于专门术语，不是 cell 的通用同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"chamber","ipa":"/ˈtʃeɪmbə(r)/","tag":"room, not unit of life","definition":"A room or enclosed space, often a technical one such as a combustion chamber; it never means a biological cell.","definitionCN":"指房间或封闭空间，常为技术性腔室，如燃烧室；从不指生物细胞。"},{"word":"compartment","ipa":"/kəmˈpɑːtmənt/","tag":"division, not unit","definition":"One of the parts into which a space is divided; it describes the shape that cell originally named.","definitionCN":"指空间被划分出的某一部分，描述的正是 cell 最初命名的那种形态。"},{"word":"battery","ipa":"/ˈbætri/","tag":"whole, not part","definition":"The complete set of connected cells; a cell is one unit inside a battery, so the two are not interchangeable.","definitionCN":"指整组相连的电池；cell 是电池组里的单个单元，两者不能互换。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin cella 'small room': one word for a monk's room, a prisoner's room, a bee's chamber and a body's unit.","cn":"拉丁语 cella「小房间」：一个词同时用于修士的房间、囚犯的房间、蜜蜂的巢室和身体的单元。"},{"en":"The family runs cellular, cellulose, cellar, cellmate and unicellular.","cn":"同族词有 cellular、cellulose、cellar、cellmate、unicellular。"},{"en":"Fixed phrases: stem cell, blood cell, prison cell, solar cell, fuel cell.","cn":"固定搭配：干细胞、血细胞、牢房、太阳能电池、燃料电池。"},{"en":"Hooke saw cork under a microscope and thought of monastery rooms.","cn":"Hooke 在显微镜下看到软木，想到的是修道院的房间。"},{"en":"Every sense is a compartment: room, battery unit, comb chamber, table box, radio area.","cn":"每个义项都是隔间：房间、电池单元、巢室、表格方格、无线小区。"}],"abstract":[{"en":"A cell is a room with walls, and the membrane is the door policy.","cn":"细胞是一间有墙的房间，而细胞膜就是门禁规定。"},{"en":"A battery is a row of locked rooms, each holding a chemical prisoner.","cn":"电池像一排上锁的房间，每间都关着一个化学囚徒。"},{"en":"A spreadsheet is a honeycomb drawn on paper: each cell waits for a number.","cn":"电子表格像画在纸上的蜂巢：每个单元格都在等一个数字。"}]},"examples":[{"en":"Every cell in the body carries the same DNA but reads only part of it.","cn":"体内每个细胞都携带相同的 DNA，但只读取其中一部分。"},{"en":"The guard walked past the cell every half hour.","cn":"看守每半小时走过一次牢房。"},{"en":"One solar cell produces only a few watts, so panels connect many of them.","cn":"一片太阳能电池只产生几瓦电，所以电池板要连接许多片。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cell 听起来像『小室』」→ 一间一间的小室 → 细胞、牢房、电池、单元格","word":"cell"},"root":"拉丁语 cella「小房间、储藏室」→ 古法语 celle → 英语 cell；指小形式 cellula 衍生 cellular、cellulose。","sensesIntro":{"en":"Nine senses all rest on one shape: a small enclosed compartment. Biology, prisons, batteries, honeycombs, politics, spreadsheets and radio each named their own compartment with the same Latin room.","cn":"九个义项都基于同一种形状：小而封闭的隔间。生物学、监狱、电池、蜂巢、政治组织、电子表格与无线电，各自用这同一个拉丁语「房间」来命名自己的隔间。"},"semanticMap":{"core":{"en":"CORE IMAGE: a small room with walls, holding a complete set of working parts.","cn":"核心意象：一间有墙的小屋，里面装着整套运转的部件。"},"chain":["SMALL ROOM","WALLED COMPARTMENT","UNIT OF LIFE","UNIT OF STORAGE","UNIT OF PEOPLE","UNIT OF A GRID"],"branches":[{"senses":"S1 · S2","en":"LIFE AND THE ROOM: the biological unit and the literal small room from which it came.","cn":"生命与房间：生物单元，以及它由之而来的字面小房间。"},{"senses":"S3","en":"CONFINEMENT: the prison sense keeps the walled room most literally.","cn":"禁闭：牢房义最字面地保留了「有墙的房间」。"},{"senses":"S4 · S5","en":"CONTAINERS: a battery compartment and a honeycomb chamber are both boxes holding something.","cn":"容器：电池隔间与蜂巢巢室都是装着东西的盒子。"},{"senses":"S6","en":"PEOPLE: a political cell is a small closed group, a room full of people.","cn":"人：政治小组是一个小而封闭的群体，也就是装满人的房间。"},{"senses":"S7 · S8 · S9","en":"GRIDS: table boxes, radio areas and addressable positions all draw the honeycomb.","cn":"网格：表格方格、无线小区与可寻址位置都在画同一张蜂巢。"}]},"affixes":{"intro":{"en":"Cell is a bare Latin noun with no affixes, but it has grown a large family through diminutives and prefixes.","cn":"cell 是不带词缀的纯拉丁名词，但它通过指小形式与前缀长出了一个大家族。"},"latinIntro":{"en":"Latin cella and cellula supply the root; prefixes such as uni-, multi-, intra- and extra- build the scientific vocabulary around it.","cn":"拉丁语 cella 与 cellula 提供词根；uni-、multi-、intra-、extra- 等前缀在它周围构建科学词汇。"},"items":[{"word":"cell","structure":"Latin cella (noun, no affix)","meaning":"a small room; the unit of life","meaningCN":"小房间；生命的单元","example":"The cell divides every twenty minutes.","exampleCN":"这个细胞每二十分钟分裂一次。"},{"word":"cellular","structure":"cellula + -aris","meaning":"relating to cells","meaningCN":"与细胞有关的","example":"Cellular damage accumulates with age.","exampleCN":"细胞损伤随年龄累积。"},{"word":"cellulose","structure":"cellula + -ose","meaning":"the fibre of plant cell walls","meaningCN":"植物细胞壁的纤维","example":"Cotton is nearly pure cellulose.","exampleCN":"棉花几乎是纯纤维素。"},{"word":"cellar","structure":"Latin cellarium","meaning":"an underground store room","meaningCN":"地下储藏室","example":"The cellar stays cool all summer.","exampleCN":"这个地窖整个夏天都很凉爽。"},{"word":"cellmate","structure":"cell + mate","meaning":"a person sharing one's prison cell","meaningCN":"同牢房的狱友","example":"His cellmate taught him to read.","exampleCN":"他的狱友教他识字。"},{"word":"unicellular","structure":"uni- (one) + cellular","meaning":"consisting of one cell","meaningCN":"由单个细胞构成的","example":"Yeast is unicellular.","exampleCN":"酵母是单细胞生物。"},{"word":"multicellular","structure":"multi- (many) + cellular","meaning":"consisting of many cells","meaningCN":"由许多细胞构成的","example":"Multicellular organisms need cell signalling.","exampleCN":"多细胞生物需要细胞信号传导。"},{"word":"intracellular","structure":"intra- (within) + cellular","meaning":"inside a cell","meaningCN":"细胞内的","example":"The virus replicates in an intracellular space.","exampleCN":"病毒在细胞内的空间中复制。"},{"word":"extracellular","structure":"extra- (outside) + cellular","meaning":"outside a cell","meaningCN":"细胞外的","example":"The matrix is extracellular.","exampleCN":"该基质位于细胞外。"},{"word":"cellule","structure":"Latin cellula","meaning":"a small cell or chamber (technical)","meaningCN":"小细胞或小腔（术语）","example":"The cellule opens into a duct.","exampleCN":"这个小腔通向一条导管。"}],"latinEntries":[{"word":"cella","structure":"Latin noun, first declension","meaning":"small room; storeroom; shrine","meaningCN":"小房间；储藏室；神龛"},{"word":"cellula","structure":"Latin diminutive of cella","meaning":"a little room","meaningCN":"小房间"},{"word":"cellarium","structure":"Latin noun from cella","meaning":"storehouse; cellar","meaningCN":"仓库；地窖"}]}},{"word":"cell division","ipa_uk":"/sel dɪˈvɪʒn/","ipa_us":"/sel dɪˈvɪʒn/","definition_zh":"细胞分裂；一个细胞分成两个的过程","definition_en":"the process by which one cell splits into two or more daughter cells","core_image":"一个圆从中间收窄，最后变成两个同样大小的圆","scene":"Uncontrolled cell division is one of the hallmarks of cancer.","sceneCN":"这里 cell division 指「细胞分裂」（第 1 个义项：一个细胞分成两个的基本过程）；句意：不受控制的细胞分裂是癌症的标志之一。","pos":[{"tag":"n.","zh":"细胞分裂（作不可数名词指过程，作可数名词指一次分裂）"}],"collocations":[{"phrase":"cell division cycle","zh":"细胞分裂周期"},{"phrase":"asymmetric cell division","zh":"不对称细胞分裂"},{"phrase":"cell division rate","zh":"细胞分裂速率"},{"phrase":"arrest cell division","zh":"阻止细胞分裂"},{"phrase":"cell division and growth","zh":"细胞分裂与生长"},{"phrase":"errors in cell division","zh":"细胞分裂中的错误"}],"forms":[{"label":"复数（多次分裂）","form":"cell divisions"},{"label":"动词短语","form":"divide（分裂）"},{"label":"相关过程","form":"mitosis（有丝分裂）"},{"label":"相关过程","form":"meiosis（减数分裂）"}],"derivatives":[{"word":"divide","pos":"v.","zh":"分开；分裂；除"},{"word":"division","pos":"n.","zh":"分开；分裂；部门；除法"},{"word":"divisive","pos":"adj.","zh":"造成分裂的"},{"word":"mitosis","pos":"n.","zh":"有丝分裂"},{"word":"meiosis","pos":"n.","zh":"减数分裂"}],"senses":[{"no":"01","title":"The basic process","titleCN":"细胞分裂（基本过程）","definition":"the process in which a cell divides to form two daughter cells","definitionCN":"一个细胞分裂形成两个子细胞的过程","example":"Cell division replaces worn-out skin within weeks.","exampleCN":"细胞分裂在数周内替换掉磨损的皮肤。","why":"Division is the act of splitting one whole into parts, and here the whole is a living cell.","whyCN":"division 是把一个整体分成部分的动作，而这里的整体是一个活细胞。"},{"no":"02","title":"Mitosis","titleCN":"有丝分裂","definition":"the ordinary division that produces two genetically identical cells","definitionCN":"产生两个遗传上相同的细胞的普通分裂","example":"Mitosis is the cell division that keeps chromosome number constant.","exampleCN":"有丝分裂是使染色体数目保持不变的细胞分裂。","why":"In body tissues the default is an identical copy, so the general phrase most often names mitosis in practice.","whyCN":"在身体组织里，默认是复制出一个完全相同的副本，因此这个总称在实践中常指有丝分裂。"},{"no":"03","title":"Meiosis","titleCN":"减数分裂","definition":"the reduction division that halves the chromosome number to make gametes","definitionCN":"使染色体数目减半、形成配子的减数分裂","example":"Meiosis is a special cell division confined to reproductive organs.","exampleCN":"减数分裂是一种只发生在生殖器官的特殊细胞分裂。","why":"One special case halves the count instead of copying it, and the phrase covers it because the shape of the event is still a split.","whyCN":"有一个特例不是复制而是减半，这个短语仍涵盖它，因为事件形态仍是「一分为二」。"},{"no":"04","title":"Growth of tissue","titleCN":"组织生长中的分裂","definition":"the multiplication of cells that increases the size of a tissue or organism","definitionCN":"细胞增殖使组织或生物体体积增大的过程","example":"Growth in the seedling comes mainly from cell division at the tips.","exampleCN":"幼苗的生长主要来自顶端的分裂。","why":"Growth by multiplication is division seen as an increase in number rather than as a replacement of parts.","whyCN":"以增殖实现的生长，是把分裂看作数量的增加，而不是部件的替换。"},{"no":"05","title":"Repair and replacement","titleCN":"修复与替换","definition":"division that replaces damaged or lost cells","definitionCN":"替换受损或缺失细胞的增殖","example":"Wound healing depends on rapid cell division at the edges.","exampleCN":"伤口愈合依赖边缘处的快速细胞分裂。","why":"Repair uses the same machinery as growth, aimed at a gap instead of at a bigger body.","whyCN":"修复用的是与生长相同的机制，只是目标从「更大的身体」变成「填上一个缺口」。"},{"no":"06","title":"Runaway division","titleCN":"失控的分裂","definition":"division that escapes normal control, a hallmark of tumours","definitionCN":"摆脱正常控制的分裂，是肿瘤的标志","example":"The drug blocks cell division in the tumour.","exampleCN":"该药物阻断肿瘤中的细胞分裂。","why":"When the brake fails, the same process becomes a threat, and medicine names the disease by naming the process.","whyCN":"当刹车失灵，同一个过程就成了威胁，医学通过命名这个过程来命名疾病。"},{"no":"07","title":"In a laboratory dish","titleCN":"培养皿中的分裂","definition":"the multiplication of cells in culture, used as an experimental measure","definitionCN":"培养条件下细胞的增殖，常作为实验指标","example":"The team measured cell division by counting nuclei.","exampleCN":"该团队通过计数细胞核来测定细胞分裂。","why":"In a dish, division becomes a number to count, so the phrase turns into a measurable variable.","whyCN":"在培养皿里，分裂变成了一个可数的数字，于是这个短语变成可测量的变量。"},{"no":"08","title":"Errors in division","titleCN":"分裂错误","definition":"mistakes in chromosome distribution during division","definitionCN":"分裂过程中染色体分配的错误","example":"An error in cell division can leave one daughter with an extra chromosome.","exampleCN":"细胞分裂中的一处错误可能使一个子细胞多出一条染色体。","why":"Because chromosomes must be shared exactly, any slip in the split produces a cell with the wrong inventory.","whyCN":"因为染色体必须精确分配，分裂中任何失误都会产生一个「清单不对」的细胞。"}],"etymology":{"intro":{"en":"Cell division joins a Latin room with a Latin act of splitting; the phrase became standard only once cell theory made cells the units of life.","cn":"cell division 把拉丁语的「房间」与拉丁语的「分开」连在一起；直到细胞学说把细胞确立为生命单元，这个说法才成为标准。"},"items":[{"era":"LATIN CELLA","en":"Cell comes from Latin cella, 'small room'. Hooke applied it to cork compartments in 1665.","cn":"cell 出自拉丁语 cella「小房间」。Hooke 在 1665 年用它指软木的小隔间。"},{"era":"LATIN DIVIDERE","en":"Division comes from Latin divisio, from dividere, 'to force apart, to separate'. The verb is dis- 'apart' plus a root related to vidua, 'separate'.","cn":"division 出自拉丁语 divisio，源自动词 dividere「使分开、分离」。该动词由 dis-「分开」加一个与 vidua「分离的」相关的词根构成。"},{"era":"NINETEENTH-CENTURY CELL THEORY","en":"Once Schleiden and Schwann argued that all living things are made of cells, the splitting of cells became a central fact, and the phrase cell division entered textbooks. The first exact use is not fixed.","cn":"Schleiden 与 Schwann 论证一切生物都由细胞构成之后，细胞的分裂成为核心事实，cell division 这一说法进入教科书。确切的首见用例并不固定。"},{"era":"MITOSIS NAMED","en":"Walther Flemming described and named mitosis in the 1880s, giving the ordinary division its own term beside the general phrase.","cn":"Walther Flemming 在 1880 年代描述并命名了有丝分裂，使普通分裂在总称之外有了自己的术语。"},{"era":"TWENTIETH-CENTURY CELL CYCLE","en":"In the second half of the 20th century the cell cycle was mapped, and cell division became a target of cancer drugs.","cn":"20 世纪下半叶，细胞周期被绘制出来，细胞分裂成为抗癌药物的靶点。"}]},"similar":{"note":{"en":"The first group separates division from its named varieties and from neighbouring terms; the second separates it from processes that are not splits.","cn":"第一组把「分裂」与它有名字的各个类型以及邻近术语分开；第二组把它与并非分裂的过程分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mitosis","ipa":"/maɪˈtəʊsɪs/","tag":"one type","definition":"The division that produces two identical cells; it is the commonest kind of cell division, not the whole category.","definitionCN":"指产生两个相同细胞的分裂，是细胞分裂中最常见的一类，而不是整个类别。"},{"word":"meiosis","ipa":"/maɪˈəʊsɪs/","tag":"the other type","definition":"The reduction division that halves chromosome number; it is a special case of cell division in gamete formation.","definitionCN":"指使染色体数目减半的减数分裂，是细胞分裂在配子形成中的特例。"},{"word":"cell cycle","ipa":"/sel ˈsaɪkl/","tag":"the whole loop","definition":"The full sequence from one division to the next, including growth and copying; division is only one phase of it.","definitionCN":"指从一次分裂到下一次分裂的完整序列，包含生长与复制；分裂只是其中一个阶段。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cell growth","ipa":"/sel ɡrəʊθ/","tag":"size, not number","definition":"An increase in cell mass or volume; it is distinct from division, which increases cell number.","definitionCN":"指细胞质量或体积的增加，与增加细胞数量的分裂不同。"},{"word":"proliferation","ipa":"/prəˌlɪfəˈreɪʃn/","tag":"rapid multiplication","definition":"Rapid increase in numbers by division, often used of cells growing too fast; it stresses speed and quantity.","definitionCN":"指通过分裂快速增多，常用于细胞增长过快的情形，强调速度与数量。"},{"word":"replication","ipa":"/ˌreplɪˈkeɪʃn/","tag":"copying molecules","definition":"The copying of DNA or other molecules, not the splitting of the cell itself.","definitionCN":"指 DNA 等分子的复制，而不是细胞本身的分裂。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"cell + division: a room splitting into two rooms.","cn":"cell + division：一间房分成两间房。"},{"en":"The family runs divide, division, divisive, mitosis and meiosis.","cn":"同族词有 divide、division、divisive、mitosis、meiosis。"},{"en":"Fixed phrases: cell division rate, asymmetric cell division, arrest cell division.","cn":"固定搭配：细胞分裂速率、不对称细胞分裂、阻止细胞分裂。"},{"en":"Growth, repair and tumours all use the same split, only the brake differs.","cn":"生长、修复与肿瘤用的是同一种分裂，区别只在刹车。"},{"en":"Mitosis copies; meiosis halves.","cn":"有丝分裂是复制，减数分裂是减半。"}],"abstract":[{"en":"Think of a photocopier that produces two identical pages and then hands each a share of the original pages.","cn":"想象一台复印机印出两页相同的纸，然后把原件的一页页分给每一份。"},{"en":"A wound is a hole that the body fills by repeating the same split, like a queue that keeps splitting.","cn":"伤口是一个洞，身体用不断重复的分裂把它填满，就像一条不断对半分开的队伍。"},{"en":"Cancer is a car whose brake line has been cut: the engine of division still runs perfectly.","cn":"癌症像一辆刹车线被剪断的车：分裂这台发动机仍在完美运转。"}]},"examples":[{"en":"Cell division in the root tip produces the new cells that lengthen the plant.","cn":"根尖的细胞分裂产生使植物伸长的新细胞。"},{"en":"Chemotherapy works by slowing cell division in fast-growing tissue.","cn":"化疗通过减缓快速生长组织中的细胞分裂起作用。"},{"en":"An error in cell division can give a daughter cell the wrong number of chromosomes.","cn":"细胞分裂中的错误可能使子细胞获得错误数量的染色体。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cell（细胞）+ division（分开）」→ 一个细胞分成两个 → 细胞分裂","word":"cell division"},"root":"拉丁语 cella「小房间」→ cell；拉丁语 dividere「使分开」→ divisio → division；两者合为 cell division。","sensesIntro":{"en":"Eight senses follow one event: a cell splitting. The same split is then read as mitosis, as meiosis, as growth, as repair, as disease, as a lab measurement and as a source of error.","cn":"八个义项围绕一个事件展开：细胞一分为二。同一次分裂随后被读成有丝分裂、减数分裂、生长、修复、疾病、实验测量与错误来源。"},"semanticMap":{"core":{"en":"CORE IMAGE: one circle narrowing in the middle until two equal circles stand apart.","cn":"核心意象：一个圆从中间收窄，最后变成两个同样大小的圆彼此分开。"},"chain":["ONE CELL","SPLIT IN TWO","COPY OR HALVE","MAKE MORE CELLS","REPLACE LOST CELLS","LOSE CONTROL"],"branches":[{"senses":"S1 · S2","en":"THE DEFAULT: the general split and its commonest form, which copies the cell exactly.","cn":"默认情形：一般分裂及其最常见形式，即精确复制细胞。"},{"senses":"S3","en":"THE EXCEPTION: meiosis halves the chromosomes for reproduction.","cn":"例外：减数分裂为生殖把染色体减半。"},{"senses":"S4 · S5","en":"PURPOSE: growth by multiplication and repair by replacement.","cn":"目的：以增殖实现生长，以替换实现修复。"},{"senses":"S6","en":"FAILURE: division without control becomes a tumour.","cn":"失控：不受控制的分裂成为肿瘤。"},{"senses":"S7 · S8","en":"MEASUREMENT AND MISTAKE: counted in a dish, and watched for errors in chromosome sharing.","cn":"测量与失误：在培养皿里被计数，也要警惕染色体分配的错误。"}]},"affixes":{"intro":{"en":"The phrase is two Latin-derived nouns; division carries the prefix dis- and the suffix -ion.","cn":"这个短语由两个源自拉丁语的名词构成；division 带前缀 dis- 与后缀 -ion。"},"latinIntro":{"en":"Latin cella gives the first word; Latin dividere, through divisio, gives the second, with dis- 'apart' and -io forming a noun of action.","cn":"第一个词来自拉丁语 cella；第二个词来自拉丁语 dividere，经 divisio 而来，其中 dis- 表示「分开」，-io 构成动作名词。"},"items":[{"word":"cell division","structure":"cell + division","meaning":"the splitting of a cell","meaningCN":"细胞的分裂","example":"Cell division slows in old tissue.","exampleCN":"老旧组织中的细胞分裂会减慢。"},{"word":"divide","structure":"Latin dividere","meaning":"to separate into parts","meaningCN":"分成若干部分","example":"The zygote divides within a day.","exampleCN":"受精卵在一天内就分裂。"},{"word":"division","structure":"divisio + -ion","meaning":"the act of separating; a part of an organisation","meaningCN":"分开的动作；组织中的一个部门","example":"Division of labour speeds up the work.","exampleCN":"分工加快了工作。"},{"word":"divisive","structure":"divis- + -ive","meaning":"causing disagreement","meaningCN":"引起分歧的","example":"The proposal proved divisive.","exampleCN":"这项提议被证明会造成分歧。"},{"word":"mitosis","structure":"Greek mitos (thread) + -osis","meaning":"division with thread-like chromosomes","meaningCN":"染色体呈丝状的普通分裂","example":"Mitosis keeps the chromosome number constant.","exampleCN":"有丝分裂使染色体数目保持不变。"},{"word":"meiosis","structure":"Greek meiosis (lessening) ","meaning":"reduction division","meaningCN":"减数分裂","example":"Meiosis produces four gametes.","exampleCN":"减数分裂产生四个配子。"},{"word":"proliferation","structure":"prolifer + -ation","meaning":"rapid multiplication","meaningCN":"快速增殖","example":"Proliferation of the lining cells thickens the tissue.","exampleCN":"内衬细胞的增殖使组织变厚。"},{"word":"cytokinesis","structure":"cyto- (cell) + Greek kinesis (movement)","meaning":"the physical splitting of the cytoplasm","meaningCN":"细胞质的物理性分裂","example":"Cytokinesis follows the separation of chromosomes.","exampleCN":"胞质分裂发生在染色体分开之后。"},{"word":"asymmetric","structure":"a- (not) + symmetric","meaning":"not mirror-image","meaningCN":"不对称的","example":"Asymmetric division gives two different daughters.","exampleCN":"不对称分裂产生两个不同的子细胞。"}],"latinEntries":[{"word":"cella","structure":"Latin noun, 'small room'","meaning":"a small room or chamber","meaningCN":"小房间；小室"},{"word":"dividere","structure":"Latin verb, dis- + -videre","meaning":"to force apart, separate","meaningCN":"使分开；分离"},{"word":"divisio","structure":"Latin noun of action from dividere","meaning":"a division, a separation","meaningCN":"分开；划分"}]}},{"word":"chromosome","ipa_uk":"/ˈkrəʊməsəʊm/","ipa_us":"/ˈkroʊməsoʊm/","definition_zh":"染色体；细胞中承载基因的线状结构","definition_en":"a thread-like structure of DNA and protein in the cell nucleus that carries genes","core_image":"一团细线被压缩成一对可以辨形的棒状物","scene":"Down syndrome results from an extra copy of chromosome 21.","sceneCN":"这里 chromosome 指「染色体」（第 1 个义项：细胞核中承载基因的线状结构）；句意：唐氏综合征由第 21 号染色体多出一份引起。","pos":[{"tag":"n.","zh":"染色体；（细菌的）环状染色体"}],"collocations":[{"phrase":"chromosome pair","zh":"染色体对"},{"phrase":"sex chromosome","zh":"性染色体"},{"phrase":"chromosome abnormality","zh":"染色体异常"},{"phrase":"X chromosome","zh":"X 染色体"},{"phrase":"chromosome number","zh":"染色体数目"},{"phrase":"extra chromosome","zh":"多余的染色体"}],"forms":[{"label":"复数","form":"chromosomes"},{"label":"形容词","form":"chromosomal（染色体的）"},{"label":"非正式缩略","form":"chromo（染色体，口语，少用）"}],"derivatives":[{"word":"chromosomal","pos":"adj.","zh":"染色体的"},{"word":"chromosome mapping","pos":"n.","zh":"染色体定位"},{"word":"chromatin","pos":"n.","zh":"染色质"},{"word":"chromatid","pos":"n.","zh":"染色单体"},{"word":"chromosome-level","pos":"adj.","zh":"染色体级别的"}],"senses":[{"no":"01","title":"Gene carrier","titleCN":"承载基因的染色体","definition":"a structure of DNA and protein that carries the genes of a cell","definitionCN":"由 DNA 与蛋白质构成、承载细胞基因的结构","example":"Humans have forty-six chromosomes in most body cells.","exampleCN":"人类大多数体细胞有四十六条染色体。","why":"Chroma named the colour seen under early dyes and soma named the body; the compound literally means a coloured body, which is what a stained chromosome looks like.","whyCN":"chroma 指早期染料下看到的颜色，soma 指身体；复合词字面就是「有色的物体」，这正是染色后染色体的样子。"},{"no":"02","title":"Visible during division","titleCN":"分裂期可见的染色体","definition":"the condensed form of chromatin that becomes visible when a cell divides","definitionCN":"染色质在细胞分裂时凝缩而成的可见形态","example":"Chromosomes line up along the middle of the cell before separating.","exampleCN":"染色体在分开之前沿细胞中央排成一行。","why":"Only during division does the material condense enough to be seen as distinct bodies, so the word names that visible stage.","whyCN":"只有在分裂时，这些物质才凝缩到能被看成独立小体的程度，因此这个词命名的是那个可见阶段。"},{"no":"03","title":"Carrier of heredity","titleCN":"遗传载体","definition":"the physical vehicle by which genes pass from parents to offspring","definitionCN":"基因由亲代传给子代的物理载体","example":"Each parent contributes one chromosome of every pair.","exampleCN":"每一对染色体中，父母各贡献一条。","why":"Once genes were located on these bodies, the chromosome became the vehicle of inheritance rather than only a stained object.","whyCN":"基因被定位到这些小体上之后，染色体就从「被染色的物体」变成了遗传的载体。"},{"no":"04","title":"Sex chromosomes","titleCN":"性染色体","definition":"the pair, X and Y, that determines biological sex in many animals","definitionCN":"在许多动物中决定生物学性别的 X 与 Y 这一对","example":"A single chromosome decides whether the embryo develops testes.","exampleCN":"一条染色体就决定了胚胎是否发育出睾丸。","why":"One pair carries the sex-determining genes, so the word is used in the singular when the identity of that chromosome matters.","whyCN":"有一对染色体携带决定性别的基因，因此当重要的是那一条的身份时，这个词会用单数。"},{"no":"05","title":"Chromosome number","titleCN":"染色体数目","definition":"the characteristic count of chromosomes in a species","definitionCN":"一个物种特有的染色体条数","example":"The chromosome number of a species is usually constant.","exampleCN":"一个物种的染色体数目通常是恒定的。","why":"Because the count is species-typical, the word participates in a standard measurement rather than in a physical description.","whyCN":"由于这个数目是物种的典型特征，这个词参与的是一项标准测量，而不是物理描述。"},{"no":"06","title":"Chromosome abnormality","titleCN":"染色体异常","definition":"a change in chromosome number or structure that affects development","definitionCN":"染色体数目或结构的改变，影响发育","example":"The test looks for a chromosome abnormality in the fetus.","exampleCN":"这项检查寻找胎儿的染色体异常。","why":"Since chromosomes hold the instructions, a change in their number or shape is a change in the instructions.","whyCN":"既然染色体保存着指令，那么数目或形状的改变就是指令的改变。"},{"no":"07","title":"Bacterial chromosome","titleCN":"细菌染色体","definition":"the usually circular DNA molecule of a bacterium","definitionCN":"细菌通常呈环状的 DNA 分子","example":"The bacterial chromosome replicates before the cell divides.","exampleCN":"细菌染色体在细胞分裂之前复制。","why":"Bacteria keep their DNA in one loop without a nucleus, and the word is stretched to cover this simpler arrangement.","whyCN":"细菌把 DNA 放在一个没有细胞核的环里，这个词被延伸来涵盖这种更简单的安排。"},{"no":"08","title":"Chromosome in a karyotype","titleCN":"核型中的染色体","definition":"a single chromosome as displayed, counted and identified in a karyotype","definitionCN":"在核型图中被展示、计数并识别的一条染色体","example":"The karyotype showed one chromosome with an unusual banding pattern.","exampleCN":"核型图显示有一条染色体的带型异常。","why":"Once chromosomes are photographed and arranged in pairs, each one becomes an identifiable item in a standard display, and the word names that item.","whyCN":"当染色体被拍摄并按对排列后，每一条都成为标准展示中的可识别项，这个词就命名那个项。"}],"etymology":{"intro":{"en":"Chromosome is a Greek compound coined in 19th-century German microscopy: colour plus body.","cn":"chromosome 是 19 世纪德国显微学造出的希腊语复合词：颜色加身体。"},"items":[{"era":"GREEK CHROMA","en":"Greek chroma meant colour, and chrōma was also used for the skin or surface colour. The element chrom- later gave words like chromium and monochrome.","cn":"希腊语 chroma 指颜色，chrōma 也用于皮肤或表面颜色。成分 chrom- 后来衍生出 chromium、monochrome 等词。"},{"era":"GREEK SOMA","en":"Greek sōma meant body, as opposed to soul or to a part. It survives in somatic, psychosomatic and chromosome.","cn":"希腊语 sōma 指身体，与灵魂或局部相对。它保留在 somatic、psychosomatic、chromosome 中。"},{"era":"1888 WALDEYER","en":"The German anatomist Wilhelm von Waldeyer-Hartz is generally credited with the term Chromosom in 1888, naming the bodies that take up dye during division. The attribution is widely accepted but the exact first printed use is debated.","cn":"德国解剖学家 Wilhelm von Waldeyer-Hartz 一般认为在 1888 年创造了 Chromosom 一词，用来指分裂时能吸收染料的那些小体。归属被广泛接受，但确切的首见印刷用例仍有争议。"},{"era":"EARLY TWENTIETH CENTURY","en":"Once chromosomes were tied to Mendelian inheritance, the word moved from cytology to genetics.","cn":"染色体与孟德尔遗传规律联系起来之后，这个词从细胞学进入遗传学。"},{"era":"1956 HUMAN COUNT","en":"The human chromosome number was established as 46 in 1956, correcting an earlier figure of 48.","cn":"人类染色体数目在 1956 年被确定为 46 条，纠正了此前 48 条的结论。"}]},"similar":{"note":{"en":"The first group separates chromosome from the materials and structures inside it; the second separates it from the units that carry genes at a different scale.","cn":"第一组把 chromosome 与它内部的物质和结构分开；第二组把它与在别的尺度上承载基因的单元分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"chromatin","ipa":"/ˈkrəʊmətɪn/","tag":"the material, not the body","definition":"The complex of DNA and protein as it exists between divisions; when it condenses into visible bodies, those bodies are chromosomes.","definitionCN":"指分裂间期 DNA 与蛋白质的复合物；当它凝缩成可见小体时，那些小体才是染色体。"},{"word":"chromatid","ipa":"/ˈkrəʊmətɪd/","tag":"half of a duplicated chromosome","definition":"One of the two identical strands of a chromosome after copying; the two chromatids together make one chromosome.","definitionCN":"指复制后染色体中两条相同丝状物之一；两条染色单体合起来才算一条染色体。"},{"word":"chromosomal","ipa":"/ˌkrəʊməˈsəʊməl/","tag":"the adjective","definition":"The adjective for 'of chromosomes'; it modifies abnormality, location or mapping, while chromosome is the countable noun.","definitionCN":"是形容词，意为「染色体的」，修饰 abnormality、location、mapping 等；chromosome 是可数名词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"gene","ipa":"/dʒiːn/","tag":"part, not whole","definition":"A segment of DNA that codes for a product; a chromosome is a long molecule carrying many genes.","definitionCN":"指编码产物的 DNA 片段；一条染色体是携带许多基因的长分子。"},{"word":"genome","ipa":"/ˈdʒiːnəʊm/","tag":"the whole set","definition":"The complete set of genetic material of an organism; chromosomes are the physical packages in which it is stored.","definitionCN":"指一个生物的全部遗传物质；染色体是储存这些物质的物理包装。"},{"word":"plasmid","ipa":"/ˈplæzmɪd/","tag":"extra loop in bacteria","definition":"A small circular DNA molecule separate from the bacterial chromosome, often carrying drug-resistance genes.","definitionCN":"指细菌中独立于染色体的小型环状 DNA 分子，常携带抗药基因。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"chroma 'colour' + soma 'body': the coloured body seen under the microscope.","cn":"chroma「颜色」+ soma「身体」：显微镜下那个被染上颜色的小体。"},{"en":"The family runs chromosomal, chromatin, chromatid and chromosome mapping.","cn":"同族词有 chromosomal、chromatin、chromatid、chromosome mapping。"},{"en":"Fixed phrases: sex chromosome, X chromosome, chromosome number, extra chromosome.","cn":"固定搭配：性染色体、X 染色体、染色体数目、多余染色体。"},{"en":"Humans have 46 chromosomes in 23 pairs.","cn":"人类有 46 条染色体，共 23 对。"},{"en":"A chromosome is a library shelf; a gene is one book on it.","cn":"染色体像一排书架，基因是架上的一本书。"}],"abstract":[{"en":"Picture a very long thread wound tight until it looks like a short thick rod.","cn":"想象一根很长的线被紧紧缠绕，直到看起来像一根短粗的棒。"},{"en":"A stained chromosome is a suspect lit up under a lamp: the dye reveals what was invisible.","cn":"染色后的染色体像灯下被照亮的嫌疑人：染料让原本看不见的东西显形。"},{"en":"An extra chromosome is one duplicate page bound into a manual.","cn":"多出一条染色体，就像手册里多装订了一页副本。"}]},"examples":[{"en":"Each human cell usually contains 23 pairs of chromosomes.","cn":"每个人类细胞通常含有 23 对染色体。"},{"en":"The extra chromosome 21 is the cause of Down syndrome.","cn":"多出的第 21 号染色体是唐氏综合征的成因。"},{"en":"Chromosomes must be copied and separated precisely before a cell divides.","cn":"细胞分裂前，染色体必须被精确复制并分开。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「chromo（颜色）+ some（体）」→ 染色后显形的「有色小体」→ 染色体","word":"chromosome"},"root":"希腊语 chroma「颜色」+ sōma「身体」→ 德语 Chromosom（1888 年 Waldeyer 提出）→ 英语 chromosome。","sensesIntro":{"en":"Eight senses move from the gene-carrying body to its visible form, its role in heredity, the sex pair, the species count, the abnormality, the bacterial loop, and finally the single chromosome as it is displayed and identified in a karyotype.","cn":"八个义项从「承载基因的小体」出发，经过它可见的形态、遗传作用、性染色体、物种数目、异常、细菌环状 DNA，最后到核型图中被展示并识别的那一条染色体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long thread folded into a compact rod that takes up dye.","cn":"核心意象：一根长线折叠成能吸收染料的紧凑短棒。"},"chain":["COLOURED BODY","THREAD OF DNA","PACKAGE OF GENES","COPIED AND SPLIT","COUNTED BY SPECIES","MISCOUNTED IN DISEASE"],"branches":[{"senses":"S1 · S2","en":"THE OBJECT: the gene carrier as a structure, and the condensed form in which it becomes visible.","cn":"对象：作为结构的基因载体，以及使它变得可见的凝缩形态。"},{"senses":"S3 · S4","en":"INHERITANCE: the vehicle from parents to offspring, including the pair that sets sex.","cn":"遗传：从亲代到子代的载体，包括决定性别的那一对。"},{"senses":"S5","en":"COUNT: the species-typical number becomes a measurable property.","cn":"数目：物种特有的条数成为可测量的属性。"},{"senses":"S6","en":"ERROR: an abnormal count or shape changes the instructions.","cn":"错误：数目或形状异常会改变指令。"},{"senses":"S7 · S8","en":"SIMPLER FORMS: the bacterial loop and the single chromosome as it appears in a karyotype.","cn":"更简单的形态：细菌的环状 DNA，以及核型图中出现的那一条染色体。"}]},"affixes":{"intro":{"en":"Chromosome is a Greek-Greek compound with no English affix; its parts are still transparent in scientific vocabulary.","cn":"chromosome 是希腊语与希腊语的复合词，不含英语词缀；它的成分在科学词汇中仍然透明。"},"latinIntro":{"en":"Both elements are Greek: chroma for colour and sōma for body. Latin plays no part, though the word was coined in German scientific Latin and reached English through it.","cn":"两个成分都来自希腊语：chroma 表颜色，sōma 表身体。拉丁语没有参与构词，但这个词是在德语科学拉丁语环境中造出，再经其进入英语。"},"items":[{"word":"chromosome","structure":"chromo- + -some","meaning":"a coloured body carrying genes","meaningCN":"携带基因的有色小体","example":"The chromosome carries hundreds of genes.","exampleCN":"这条染色体携带数百个基因。"},{"word":"chromosomal","structure":"chromosome + -al","meaning":"relating to chromosomes","meaningCN":"与染色体有关的","example":"Chromosomal DNA is stored in the nucleus.","exampleCN":"染色体 DNA 储存在细胞核中。"},{"word":"chromatin","structure":"chromat- + -in","meaning":"the DNA-protein material of chromosomes","meaningCN":"构成染色体的 DNA 与蛋白质物质","example":"Chromatin loosens in the active regions.","exampleCN":"染色质在活跃区域会变得松散。"},{"word":"chromatid","structure":"chromat- + -id","meaning":"one strand of a copied chromosome","meaningCN":"复制后染色体的一条丝","example":"Each chromatid is pulled to a pole.","exampleCN":"每条染色单体被拉向一极。"},{"word":"chromatography","structure":"chromato- + -graphy","meaning":"separation of substances by colour bands","meaningCN":"按色带分离物质的方法","example":"Chromatography separated the pigments.","exampleCN":"层析法把色素分离开来。"},{"word":"somatic","structure":"soma + -tic","meaning":"relating to the body","meaningCN":"与身体有关的","example":"Somatic cells do not form gametes.","exampleCN":"体细胞不形成配子。"},{"word":"autosome","structure":"auto- (self) + -some","meaning":"a chromosome other than a sex chromosome","meaningCN":"除性染色体之外的染色体","example":"Humans have 22 pairs of autosomes.","exampleCN":"人类有 22 对常染色体。"},{"word":"genome","structure":"gene + -ome","meaning":"the whole set of genes","meaningCN":"全部基因的集合","example":"The genome is split across chromosomes.","exampleCN":"基因组分布在多条染色体上。"},{"word":"telomere","structure":"telo- (end) + Greek meros (part)","meaning":"the protective end of a chromosome","meaningCN":"染色体末端的保护结构","example":"Telomeres shorten with each division.","exampleCN":"端粒随着每次分裂而缩短。"}],"latinEntries":[{"word":"χρῶμα","structure":"Greek noun, 'colour'","meaning":"colour; skin colour","meaningCN":"颜色；肤色"},{"word":"σῶμα","structure":"Greek noun, 'body'","meaning":"a body, as opposed to a soul or part","meaningCN":"身体（相对于灵魂或局部）"},{"word":"-σωμα","structure":"Greek combining element from sōma","meaning":"used in compounds for a body or particle","meaningCN":"用于复合词，表示身体或小体"}]}},{"word":"chromosomal","ipa_uk":"/ˌkrəʊməˈsəʊməl/","ipa_us":"/ˌkroʊməˈsoʊməl/","definition_zh":"染色体的；与染色体有关的","definition_en":"relating to chromosomes or occurring on a chromosome","core_image":"显微镜下一排编号的短棒，旁边标着它们的缺陷位置","scene":"Chromosomal abnormalities account for a small share of early miscarriages.","sceneCN":"这里 chromosomal 指「染色体的」（第 1 个义项：与染色体有关的异常）；句意：染色体异常只占早期流产的一小部分。","pos":[{"tag":"adj.","zh":"染色体的；染色体上的；由染色体引起的"}],"collocations":[{"phrase":"chromosomal abnormality","zh":"染色体异常"},{"phrase":"chromosomal DNA","zh":"染色体 DNA"},{"phrase":"chromosomal rearrangement","zh":"染色体重排"},{"phrase":"chromosomal disorder","zh":"染色体疾病"},{"phrase":"chromosomal location","zh":"染色体位置"},{"phrase":"chromosomal mutation","zh":"染色体突变"}],"forms":[{"label":"比较级","form":"more chromosomal"},{"label":"最高级","form":"most chromosomal"},{"label":"名词形式","form":"chromosome（染色体）"},{"label":"副词形式","form":"chromosomally（在染色体层面）"}],"derivatives":[{"word":"chromosome","pos":"n.","zh":"染色体"},{"word":"chromosomally","pos":"adv.","zh":"在染色体层面"},{"word":"chromosomal-level","pos":"adj.","zh":"染色体层面的"},{"word":"chromatin","pos":"n.","zh":"染色质"},{"word":"chromosome mapping","pos":"n.","zh":"染色体定位"}],"senses":[{"no":"01","title":"Of chromosomes in general","titleCN":"与染色体有关的","definition":"relating to chromosomes as structures","definitionCN":"与染色体这一结构有关的","example":"Chromosomal DNA is packed with histone proteins.","exampleCN":"染色体 DNA 与组蛋白紧密包装在一起。","why":"The adjective simply turns the noun into a modifier, so any statement about chromosomes as objects can use it.","whyCN":"这个形容词只是把名词变成修饰语，因此任何关于染色体这一对象的陈述都可以用它。"},{"no":"02","title":"Located on a chromosome","titleCN":"位于染色体上的","definition":"situated at a particular place on a chromosome","definitionCN":"位于染色体某一特定位置的","example":"The gene's chromosomal location was narrowed to a small region.","exampleCN":"该基因的染色体位置被缩小到一个很小的区域。","why":"Once genes are known to sit on chromosomes, the adjective marks the address rather than the whole structure.","whyCN":"既然已知基因位于染色体上，这个形容词标出的就是「地址」，而不是整个结构。"},{"no":"03","title":"Abnormalities","titleCN":"染色体异常的","definition":"describing a change in chromosome number or structure","definitionCN":"指染色体数目或结构的改变","example":"Chromosomal abnormalities can be detected before birth.","exampleCN":"染色体异常可以在出生前被检出。","why":"Medicine needed a compact modifier for defects whose cause is a chromosome, and the adjective supplies it.","whyCN":"医学需要一个简短的修饰语来指病因在染色体上的缺陷，这个形容词正好承担这一功能。"},{"no":"04","title":"Inheritance patterns","titleCN":"染色体遗传方式的","definition":"describing traits whose transmission follows chromosome behaviour","definitionCN":"指传递方式随染色体行为而定的性状","example":"The trait shows a chromosomal pattern of inheritance.","exampleCN":"该性状表现出染色体式的遗传规律。","why":"Because chromosomes are copied and sorted predictably, traits they carry inherit in patterns the adjective can label.","whyCN":"由于染色体按可预测的方式复制与分配，它们携带的性状就以这个形容词可以命名的规律遗传。"},{"no":"05","title":"Sex determination","titleCN":"染色体决定性的","definition":"describing sex determination by chromosome composition","definitionCN":"指由染色体组成决定性别的方式","example":"Birds use a chromosomal system opposite to that of mammals.","exampleCN":"鸟类使用的染色体性别系统与哺乳动物相反。","why":"Where sex follows from which chromosomes are present, the adjective marks the mechanism rather than the outcome.","whyCN":"当性别取决于存在哪些染色体时，这个形容词标出的是机制，而不是结果。"},{"no":"06","title":"Laboratory technique","titleCN":"染色体检测的","definition":"describing tests that examine chromosomes directly","definitionCN":"指直接检查染色体的检测","example":"Chromosomal analysis requires cells that are actively dividing.","exampleCN":"染色体分析需要处于活跃分裂状态的细胞。","why":"A test aimed at chromosomes is named by the adjective plus a noun such as analysis or test.","whyCN":"针对染色体的检测，就用这个形容词加 analysis（分析）或 test（检测）之类的名词来命名。"},{"no":"07","title":"In evolution and species","titleCN":"染色体层面的演化","definition":"describing differences between species that lie in chromosome number or arrangement","definitionCN":"指物种间在染色体数目或排列上的差异","example":"Chromosomal differences help distinguish the two species.","exampleCN":"染色体层面的差异有助于区分这两个物种。","why":"Speciation often involves rearrangements that the adjective marks as the level at which the difference exists.","whyCN":"物种形成常涉及重排，这个形容词标出的正是差异所在的层次。"},{"no":"08","title":"Of chromosome behaviour in division","titleCN":"分裂中染色体行为的","definition":"describing how chromosomes move, pair or separate during division","definitionCN":"指分裂过程中染色体如何移动、配对或分开","example":"Chromosomal pairing fails when the spindle is disturbed.","exampleCN":"纺锤体受到干扰时，染色体的配对会失败。","why":"During division chromosomes behave as physical objects, and the adjective names that behavioural level.","whyCN":"在分裂过程中，染色体表现为物理对象，这个形容词命名的就是这一行为层面。"}],"etymology":{"intro":{"en":"Chromosomal is the English adjective of chromosome, formed by adding -al to the German-coined Greek compound.","cn":"chromosomal 是 chromosome 的英语形容词，在德语造出的希腊语复合词后加 -al 构成。"},"items":[{"era":"GREEK CHROMA","en":"Greek chroma, 'colour', supplies the first element. It named the dye uptake that made the bodies visible.","cn":"希腊语 chroma「颜色」提供第一个成分，指使这些小体可见的染料吸收。"},{"era":"GREEK SOMA","en":"Greek sōma, 'body', supplies the second element, so chromosome is literally a coloured body.","cn":"希腊语 sōma「身体」提供第二个成分，因此 chromosome 字面就是「有色的物体」。"},{"era":"1888 GERMAN COINAGE","en":"Chromosom was coined in German in 1888, generally attributed to Waldeyer-Hartz. The English form chromosome followed soon after.","cn":"Chromosom 于 1888 年在德语中造出，一般认为出自 Waldeyer-Hartz。英语形式 chromosome 随后出现。"},{"era":"ADJECTIVAL FORMATION","en":"The adjective chromosomal was built in English with -al, on the model of other scientific adjectives. Its first printed use is not firmly dated.","cn":"形容词 chromosomal 是英语加 -al 构成的，模仿其他科学形容词的模式。确切的首见印刷用例没有定论。"},{"era":"TWENTIETH-CENTURY GENETICS","en":"As cytogenetics grew, chromosomal became routine in names of disorders, analyses and rearrangements.","cn":"随着细胞遗传学发展，chromosomal 在疾病、分析与重排的名称中成为常规用法。"}]},"similar":{"note":{"en":"The first group separates the adjective from the noun and from its adverbial form; the second separates chromosomal from modifiers of other genetic scales.","cn":"第一组把这个形容词与名词及其副词形式分开；第二组把它与其它遗传尺度的修饰语分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"chromosome","ipa":"/ˈkrəʊməsəʊm/","tag":"the noun","definition":"The countable object itself; chromosomal is the form used before nouns such as abnormality, DNA or analysis.","definitionCN":"是可数名词，指对象本身；chromosomal 用在 abnormality、DNA、analysis 等名词之前。"},{"word":"chromosomally","ipa":"/ˌkrəʊməˈsəʊməli/","tag":"the adverb","definition":"The adverb, meaning 'at the level of chromosomes'; it modifies verbs such as determined or normal.","definitionCN":"是副词，意为「在染色体层面」，修饰 determined、normal 之类的词。"},{"word":"chromatin","ipa":"/ˈkrəʊmətɪn/","tag":"material, not modifier","definition":"The DNA-protein material itself; chromatin is not an adjective and cannot modify abnormality.","definitionCN":"指 DNA 与蛋白质构成的物质本身；chromatin 不是形容词，不能修饰 abnormality。"}]},{"heading":"NEAR MEANING","entries":[{"word":"genetic","ipa":"/dʒeˈnetɪk/","tag":"gene level","definition":"Relating to genes and heredity; a genetic disorder may involve one gene, while a chromosomal one involves a whole chromosome.","definitionCN":"指与基因和遗传有关的；遗传病可能只涉及一个基因，而染色体病涉及整条染色体。"},{"word":"genomic","ipa":"/dʒiːˈnəʊmɪk/","tag":"whole-set level","definition":"Relating to the entire genome; it is broader than chromosomal, which concerns individual chromosomes.","definitionCN":"指与整个基因组有关，比 chromosomal 更宽，后者只涉及单条染色体。"},{"word":"cytogenetic","ipa":"/ˌsaɪtəʊdʒeˈnetɪk/","tag":"method-oriented","definition":"Relating to the study of chromosomes under the microscope; it names the technique as much as the object.","definitionCN":"指在显微镜下研究染色体的学科，既指对象也指方法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"chromosome + -al: the adjective that stands before abnormality, DNA and analysis.","cn":"chromosome + -al：站在 abnormality、DNA、analysis 前面的那个形容词。"},{"en":"The family runs chromosome, chromosomally, chromatin and chromosome mapping.","cn":"同族词有 chromosome、chromosomally、chromatin、chromosome mapping。"},{"en":"Fixed phrases: chromosomal abnormality, chromosomal rearrangement, chromosomal disorder.","cn":"固定搭配：染色体异常、染色体重排、染色体疾病。"},{"en":"If the defect is in a whole chromosome, the modifier is chromosomal, not genetic.","cn":"如果缺陷在整条染色体上，修饰语就是 chromosomal，而不是 genetic。"},{"en":"The adjective almost always appears in medical and cytological writing.","cn":"这个形容词几乎只出现在医学与细胞学写作中。"}],"abstract":[{"en":"Think of a library where a whole shelf has been misplaced, not just one book: that is chromosomal, not genetic.","cn":"想象一座图书馆里整排书架被放错了位置，而不只是一本书：这就是 chromosomal，而不是 genetic。"},{"en":"A chromosomal map is a street plan where each gene has an address.","cn":"染色体图谱就是一张街道图，每个基因都有一个门牌号。"},{"en":"A chromosomal rearrangement is a deck of cards cut and reshuffled.","cn":"染色体重排就像一副牌被切开又重洗。"}]},"examples":[{"en":"Chromosomal analysis is offered to women at higher risk.","cn":"染色体分析提供给风险较高的女性。"},{"en":"The chromosomal location of the gene was confirmed by two labs.","cn":"该基因的染色体位置由两个实验室确认。"},{"en":"Chromosomal rearrangements can silence a gene without changing its sequence.","cn":"染色体重排可以在不改变序列的情况下使一个基因沉默。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「chromosome + -al」→ 染色体那一类的 → 染色体的、染色体上的","word":"chromosomal"},"root":"希腊语 chroma「颜色」+ sōma「身体」→ chromosome；英语加形容词后缀 -al 构成 chromosomal。","sensesIntro":{"en":"Eight senses show the adjective spreading across levels: the structure itself, its addresses, its defects, its inheritance patterns, sex determination, tests, species differences and behaviour during division.","cn":"八个义项显示这个形容词如何铺开到各层面：结构本身、基因位置、缺陷、遗传规律、性别决定、检测、物种差异与分裂中的行为。"},"semanticMap":{"core":{"en":"CORE IMAGE: numbered rods under a microscope with defects marked on them.","cn":"核心意象：显微镜下一排编了号的短棒，上面标着缺陷位置。"},"chain":["OF A CHROMOSOME","ON A CHROMOSOME","WRONG IN NUMBER","INHERITED TOGETHER","DECIDING SEX","EXAMINED IN A LAB"],"branches":[{"senses":"S1 · S8","en":"THE OBJECT AND ITS BEHAVIOUR: the structure itself, and how it moves during division.","cn":"对象与行为：结构本身，以及它在分裂中如何移动。"},{"senses":"S2","en":"ADDRESS: a gene's position on a chromosome.","cn":"地址：基因在染色体上的位置。"},{"senses":"S3 · S5","en":"DEFECT AND DETERMINATION: abnormal counts, and the pair that sets sex.","cn":"缺陷与决定：异常的数目，以及决定性别的那个配对。"},{"senses":"S4 · S7","en":"INHERITANCE AND SPECIES: patterns that follow chromosomes, and differences between species.","cn":"遗传与物种：随染色体而定的规律，以及物种间的差异。"},{"senses":"S6","en":"METHOD: the laboratory analysis that reads chromosomes directly.","cn":"方法：直接读取染色体的实验室分析。"}]},"affixes":{"intro":{"en":"The adjective adds -al to a Greek compound; the affixes in its family belong to cytology and genetics.","cn":"这个形容词在希腊语复合词后加 -al；其词族的词缀都属于细胞学与遗传学。"},"latinIntro":{"en":"Greek chroma and sōma build the base; the English suffix -al comes from Latin -alis. The adverbial -ly is English.","cn":"希腊语 chroma 与 sōma 构成词基；英语后缀 -al 源自拉丁语 -alis；副词词尾 -ly 是英语的。"},"items":[{"word":"chromosomal","structure":"chromosome + -al","meaning":"relating to chromosomes","meaningCN":"与染色体有关的","example":"The chromosomal defect was inherited from the mother.","exampleCN":"该染色体缺陷遗传自母亲。"},{"word":"chromosome","structure":"chromo- + -some","meaning":"the coloured gene-carrying body","meaningCN":"携带基因的有色小体","example":"The chromosome was first seen in dividing cells.","exampleCN":"染色体最早是在分裂的细胞中被看到的。"},{"word":"chromosomally","structure":"chromosomal + -ly","meaning":"at the level of chromosomes","meaningCN":"在染色体层面","example":"The two populations are chromosomally distinct.","exampleCN":"这两个群体在染色体层面有区别。"},{"word":"chromatin","structure":"chromat- + -in","meaning":"the material of chromosomes","meaningCN":"构成染色体的物质","example":"Chromatin condenses before division.","exampleCN":"染色质在分裂前凝缩。"},{"word":"autosomal","structure":"auto- + somal","meaning":"relating to non-sex chromosomes","meaningCN":"与非性染色体有关的","example":"Autosomal traits appear in both sexes.","exampleCN":"常染色体性状在两性中都出现。"},{"word":"cytogenetic","structure":"cyto- + genetic","meaning":"relating to chromosome study","meaningCN":"与染色体研究有关的","example":"Cytogenetic testing found the deletion.","exampleCN":"细胞遗传学检测发现了这段缺失。"},{"word":"polyploid","structure":"poly- (many) + -ploid","meaning":"having extra sets of chromosomes","meaningCN":"具有额外染色体组的","example":"Polyploid plants often grow larger.","exampleCN":"多倍体植物往往长得更大。"},{"word":"karyotype","structure":"karyo- (nucleus) + -type","meaning":"the chromosome complement of a cell","meaningCN":"一个细胞的染色体组成","example":"The karyotype showed an extra chromosome.","exampleCN":"核型显示多出一条染色体。"},{"word":"translocation","structure":"trans- (across) + locatio (placing)","meaning":"a piece of chromosome moved elsewhere","meaningCN":"染色体片段移到别处","example":"A translocation joined two chromosomes.","exampleCN":"一次易位把两条染色体接在一起。"}],"latinEntries":[{"word":"χρῶμα","structure":"Greek noun, 'colour'","meaning":"colour; dye colour","meaningCN":"颜色；染料色"},{"word":"σῶμα","structure":"Greek noun, 'body'","meaning":"a body","meaningCN":"身体；物体"},{"word":"sōma","structure":"Greek combining form used in scientific compounds","meaning":"body, particle","meaningCN":"身体；小体"}]}},{"word":"chromosome mapping","ipa_uk":"/ˈkrəʊməsəʊm ˈmæpɪŋ/","ipa_us":"/ˈkroʊməsoʊm ˈmæpɪŋ/","definition_zh":"染色体定位；确定基因在染色体上的位置","definition_en":"the process of determining the positions of genes or markers along a chromosome","core_image":"一条长尺上标出一个个基因的刻度位置","scene":"Chromosome mapping placed the resistance gene near the end of the long arm.","sceneCN":"这里 chromosome mapping 指「染色体定位」（第 1 个义项：确定基因在染色体上的位置）；句意：染色体定位把这个抗性基因放在长臂末端附近。","pos":[{"tag":"n.","zh":"染色体定位；基因定位（不可数，指方法或过程；作可数时可指一次定位工作）"}],"collocations":[{"phrase":"chromosome mapping project","zh":"染色体定位计划"},{"phrase":"high-resolution chromosome mapping","zh":"高分辨率染色体定位"},{"phrase":"chromosome mapping techniques","zh":"染色体定位技术"},{"phrase":"linkage mapping","zh":"连锁定位"},{"phrase":"physical mapping","zh":"物理定位"},{"phrase":"genetic mapping","zh":"遗传定位"}],"forms":[{"label":"不可数用法","form":"chromosome mapping（指方法或领域）"},{"label":"复数（多次定位工作）","form":"chromosome mappings（少见）"},{"label":"定语用法","form":"chromosome mapping data（染色体定位数据）"},{"label":"从业表述","form":"map the genome（绘制基因组图谱）"}],"derivatives":[{"word":"map","pos":"n./v.","zh":"地图；绘制图谱；定位"},{"word":"mapping","pos":"n.","zh":"定位；绘图"},{"word":"genetic map","pos":"n.","zh":"遗传图谱"},{"word":"physical map","pos":"n.","zh":"物理图谱"},{"word":"linkage map","pos":"n.","zh":"连锁图谱"}],"senses":[{"no":"01","title":"Locating genes","titleCN":"确定基因的位置","definition":"the determination of where genes or DNA markers lie on a chromosome","definitionCN":"确定基因或 DNA 标记在染色体上的位置","example":"Chromosome mapping located the gene between two known markers.","exampleCN":"染色体定位把这个基因落在两个已知标记之间。","why":"A map turns unknown territory into named positions, and here the territory is the length of a chromosome.","whyCN":"地图把未知地域变成有名字的位置，而这里的地域就是一条染色体的长度。"},{"no":"02","title":"Linkage mapping","titleCN":"连锁定位","definition":"mapping by measuring how often traits are inherited together","definitionCN":"通过测量性状共同遗传的频率来定位","example":"Linkage mapping gave a rough position before sequencing was cheap.","exampleCN":"在测序还昂贵的时候，连锁定位给出了粗略的位置。","why":"Genes near each other tend to travel together, so co-inheritance frequencies become a ruler.","whyCN":"相邻的基因倾向于一起传递，因此共同遗传的频率就成了一把尺。"},{"no":"03","title":"Physical mapping","titleCN":"物理定位","definition":"mapping by measuring actual distances in DNA base pairs","definitionCN":"以 DNA 碱基对的实际距离来定位","example":"Physical mapping reports distances in millions of base pairs.","exampleCN":"物理定位以百万碱基对为单位报告距离。","why":"When the molecule itself can be measured, the ruler stops being statistical and becomes literal.","whyCN":"当分子本身可以被测量时，这把尺就从统计性的变成字面意义上的。"},{"no":"04","title":"Ordering markers","titleCN":"排列标记的顺序","definition":"the ordering of known DNA sequences along a chromosome","definitionCN":"把已知 DNA 序列按其在染色体上的顺序排列","example":"Chromosome mapping ordered the clones into a single contig.","exampleCN":"染色体定位把这些克隆排成一个连续片段。","why":"A map is also a list in order, so mapping can mean putting fragments into their true sequence.","whyCN":"地图也是一份有顺序的清单，因此定位也可以指把片段放回真实次序。"},{"no":"05","title":"A whole-genome project","titleCN":"全基因组定位计划","definition":"a large organised effort to map all chromosomes of a species","definitionCN":"为定位一个物种全部染色体而组织的大型计划","example":"The chromosome mapping project published its first draft in the 1990s.","exampleCN":"这项染色体定位计划在 1990 年代公布了初稿。","why":"Science turns a method into an institution when it organises a project around it, and the phrase then names the effort.","whyCN":"当科学围绕一种方法组织起计划时，方法就变成了建制，这个短语于是指那项工作本身。"},{"no":"06","title":"Comparing species","titleCN":"物种间比较定位","definition":"mapping used to compare chromosome arrangement across species","definitionCN":"用于比较不同物种染色体排列的定位","example":"Chromosome mapping showed that whole blocks had been rearranged.","exampleCN":"染色体定位显示整块片段发生了重排。","why":"If maps of two species can be laid side by side, mapping becomes a tool of evolutionary comparison.","whyCN":"如果两个物种的图谱可以并排放置，定位就成了演化比较的工具。"},{"no":"07","title":"Clinical use","titleCN":"临床定位","definition":"mapping to find the position of a disease gene for diagnosis","definitionCN":"为诊断而定位疾病基因的位置","example":"Chromosome mapping narrowed the disease gene to a small interval.","exampleCN":"染色体定位把疾病基因缩小到一个很小的区间。","why":"Once a disease gene has an address, a test can be designed for it, so mapping serves diagnosis.","whyCN":"一旦疾病基因有了地址，就能为它设计检测，因此定位服务于诊断。"},{"no":"08","title":"The resulting map","titleCN":"定位所得的图谱","definition":"the map produced by such work, showing positions and distances","definitionCN":"由此得到的图谱，标出位置与距离","example":"The chromosome mapping is now available as a public database.","exampleCN":"这份染色体图谱现在作为公共数据库开放。","why":"The activity and its product share one name, a common pattern for work that leaves a document behind.","whyCN":"活动与其产物共用一个名字，这是「留下文件的工作」常见的命名方式。"}],"etymology":{"intro":{"en":"Chromosome mapping joins a Greek compound for the gene carrier to an English word for a drawn plan of the land.","cn":"chromosome mapping 把表示基因载体的希腊语复合词，接到一个表示绘制地形的英语词上。"},"items":[{"era":"GREEK CHROMA AND SOMA","en":"Chromosome is chroma, 'colour', plus sōma, 'body', coined in German in 1888 for the dye-taking bodies seen during division.","cn":"chromosome 是 chroma「颜色」加 sōma「身体」，1888 年在德语中造出，指分裂时吸收染料的那些小体。"},{"era":"LATIN MAPPA","en":"Map comes from Latin mappa, 'cloth, napkin'. A mappa mundi was a cloth on which the world was drawn, and English map shortened that phrase.","cn":"map 出自拉丁语 mappa「布、餐巾」。mappa mundi 指画着世界的那块布，英语 map 就是这一短语的缩略。"},{"era":"EARLY TWENTIETH CENTURY","en":"The idea of arranging genes in a linear order on chromosomes took shape in the work of Morgan's school around 1913, where linkage maps were drawn. The phrase chromosome mapping itself is later.","cn":"把基因按线性顺序排在染色体上的想法，在 1913 年前后 Morgan 学派的工作中成形，当时绘制了连锁图。chromosome mapping 这一短语本身出现得更晚。"},{"era":"HUMAN GENOME ERA","en":"In the 1980s and 1990s chromosome mapping became an organised project with physical maps measured in base pairs.","cn":"1980 至 1990 年代，染色体定位成为有组织的计划，物理图谱以碱基对为单位测量。"},{"era":"SEQUENCING AGE","en":"After whole-genome sequencing, mapping became largely computational, though the phrase remains standard for assigning positions.","cn":"全基因组测序之后，定位主要变成计算工作，但这个短语仍是「指定位置」的标准说法。"}]},"similar":{"note":{"en":"The first group separates mapping from the maps it produces and from other chromosome techniques; the second separates it from sequencing and from broader genome work.","cn":"第一组把定位与它产出的图谱以及其它染色体技术分开；第二组把它与测序以及更广的基因组工作分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"genetic map","ipa":"/dʒeˈnetɪk mæp/","tag":"the product","definition":"The chart of gene positions produced by mapping; mapping is the activity, the map is the document.","definitionCN":"指定位工作产出的基因位置图；mapping 是活动，map 是文件。"},{"word":"gene mapping","ipa":"/dʒiːn ˈmæpɪŋ/","tag":"near-synonym","definition":"Often used interchangeably, though it stresses genes rather than the chromosome as the object being placed.","definitionCN":"常可互换使用，但它强调的是基因本身，而不是承载它们的染色体。"},{"word":"karyotyping","ipa":"/ˈkæriətaɪpɪŋ/","tag":"whole-set picture","definition":"Photographing and sorting a cell's full chromosome set; it shows number and shape, not the position of individual genes.","definitionCN":"指拍摄并排列一个细胞的全套染色体，显示数目与形态，而不是单个基因的位置。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sequencing","ipa":"/ˈsiːkwənsɪŋ/","tag":"reading, not placing","definition":"Determining the exact order of bases in DNA; it produces the letters that mapping then places on a chromosome.","definitionCN":"指测定 DNA 碱基的确切顺序，产出字母序列，再由定位放回染色体。"},{"word":"genome mapping","ipa":"/ˈdʒiːnəʊm ˈmæpɪŋ/","tag":"all chromosomes","definition":"The same work extended to every chromosome of an organism at once.","definitionCN":"把同样的工作一次性扩展到该生物的全部染色体。"},{"word":"positional cloning","ipa":"/pəˈzɪʃənl ˈklɒnɪŋ/","tag":"next step","definition":"Using a mapped position to isolate the actual gene; mapping finds the address, cloning retrieves the text.","definitionCN":"利用已定位的位置把真正的基因分离出来；定位找地址，克隆取正文。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"chromosome + mapping: drawing a map along a chromosome.","cn":"chromosome + mapping：沿一条染色体画地图。"},{"en":"The family runs map, mapping, genetic map, physical map and linkage map.","cn":"同族词有 map、mapping、genetic map、physical map、linkage map。"},{"en":"Fixed phrases: linkage mapping, physical mapping, chromosome mapping project.","cn":"固定搭配：连锁定位、物理定位、染色体定位计划。"},{"en":"Linkage mapping measures co-inheritance; physical mapping measures base pairs.","cn":"连锁定位测量共同遗传，物理定位测量碱基对。"},{"en":"Mapping finds the address; sequencing reads the text.","cn":"定位找地址，测序读正文。"}],"abstract":[{"en":"Think of an old cloth map: the chromosome is the coastline, and each gene is a marked harbour.","cn":"想象一块旧布地图：染色体是海岸线，每个基因是一个标出的港口。"},{"en":"Linkage mapping is guessing distances from which travellers arrive together.","cn":"连锁定位就像靠「哪些旅人总是一起到」来推测距离。"},{"en":"A mapping project is a survey crew walking the whole length of a country.","cn":"定位计划就像一支测量队走遍一个国家的全长。"}]},"examples":[{"en":"Chromosome mapping placed the mutation within a region of two million base pairs.","cn":"染色体定位把该突变落在两百万碱基对的一个区域内。"},{"en":"Linkage mapping was the main tool before sequencing became affordable.","cn":"在测序变得廉价之前，连锁定位是主要工具。"},{"en":"The chromosome mapping data are shared through a public database.","cn":"染色体定位数据通过公共数据库共享。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「chromosome（染色体）+ mapping（画地图）」→ 给染色体画地图 → 染色体定位","word":"chromosome mapping"},"root":"希腊语 chroma「颜色」+ sōma「身体」→ chromosome；拉丁语 mappa「布」→ map + -ing → mapping。","sensesIntro":{"en":"Eight senses run from the act of locating a gene, through the linkage and physical methods, the ordering of markers, the organised project, species comparison, clinical use, and finally the map itself.","cn":"八个义项从「给基因定位」这个动作出发，经过连锁法与物理法、标记排序、有组织的计划、物种比较、临床用途，最后落到图谱本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long ruler with a gene marked at each graduation.","cn":"核心意象：一把长尺，每个刻度上都标着一个基因。"},"chain":["DRAW A MAP","FIND THE POSITION","MEASURE BY INHERITANCE","MEASURE IN BASE PAIRS","ORDER THE PIECES","PUBLISH THE MAP"],"branches":[{"senses":"S1 · S8","en":"ACT AND PRODUCT: locating genes, and the map that results.","cn":"活动与产物：给基因定位，以及由此得到的图谱。"},{"senses":"S2 · S3","en":"TWO RULERS: inheritance frequencies and literal base-pair distances.","cn":"两把尺：遗传频率与字面上的碱基对距离。"},{"senses":"S4","en":"ORDER: putting known fragments into their true sequence.","cn":"顺序：把已知片段放回真实次序。"},{"senses":"S5 · S7","en":"INSTITUTION AND CLINIC: the organised project, and the diagnostic use of a found address.","cn":"建制与临床：有组织的计划，以及用找到的地址做诊断。"},{"senses":"S6","en":"COMPARISON: laying two species' maps side by side.","cn":"比较：把两个物种的图谱并排放置。"}]},"affixes":{"intro":{"en":"The phrase joins a Greek compound noun to an English gerund; mapping carries the agent suffix -ing on a Latin borrowing.","cn":"这个短语把希腊语复合名词接到一个英语动名词上；mapping 在拉丁语借词后带 -ing。"},"latinIntro":{"en":"Greek chroma and sōma build chromosome; Latin mappa, 'cloth', gives map, and English -ing makes the activity noun.","cn":"希腊语 chroma 与 sōma 构成 chromosome；拉丁语 mappa「布」给出 map，英语 -ing 构成表示活动的名词。"},"items":[{"word":"chromosome mapping","structure":"chromosome + mapping","meaning":"locating genes along a chromosome","meaningCN":"沿染色体给基因定位","example":"Chromosome mapping took years of collaborative work.","exampleCN":"染色体定位耗费了多年的协作。"},{"word":"map","structure":"Latin mappa (cloth)","meaning":"a drawing of positions; to locate","meaningCN":"标出位置的图；定位","example":"They mapped the gene to the short arm.","exampleCN":"他们把这个基因定位到短臂上。"},{"word":"mapping","structure":"map + -ing","meaning":"the activity of making a map","meaningCN":"绘制图谱的活动","example":"Mapping continued after the first draft.","exampleCN":"初稿完成后定位工作仍在继续。"},{"word":"linkage","structure":"link + -age","meaning":"the tendency of genes to be inherited together","meaningCN":"基因共同遗传的倾向","example":"Linkage analysis placed the gene near the centromere.","exampleCN":"连锁分析把该基因定位在着丝粒附近。"},{"word":"marker","structure":"mark + -er","meaning":"a known DNA site used as a reference point","meaningCN":"用作参照点的已知 DNA 位点","example":"Two markers bracketed the region.","exampleCN":"两个标记夹住了这个区域。"},{"word":"contig","structure":"contiguous + clipped -ous","meaning":"an unbroken stretch of assembled DNA","meaningCN":"拼接成连续不断的一段 DNA","example":"The contig spans the whole arm.","exampleCN":"这个连续片段覆盖整条臂。"},{"word":"karyotype","structure":"karyo- (nucleus) + -type","meaning":"the chromosome set of a cell","meaningCN":"一个细胞的染色体组成","example":"The karyotype is normal.","exampleCN":"核型正常。"},{"word":"sequencing","structure":"sequence + -ing","meaning":"reading the order of bases","meaningCN":"读取碱基顺序","example":"Sequencing confirmed the mapped position.","exampleCN":"测序确认了定位的位置。"},{"word":"positional","structure":"position + -al","meaning":"relating to a mapped location","meaningCN":"与已定位的位置有关的","example":"Positional cloning began from the mapped interval.","exampleCN":"定位克隆从已定位的区间开始。"}],"latinEntries":[{"word":"mappa","structure":"Latin noun, 'cloth, napkin'","meaning":"a cloth; the cloth on which a map was drawn","meaningCN":"布；绘制地图所用的布"},{"word":"mappa mundi","structure":"Latin phrase, 'cloth of the world'","meaning":"a medieval world map","meaningCN":"中世纪的世界地图"},{"word":"chroma","structure":"Greek noun, 'colour' (via German Chromosom)","meaning":"colour","meaningCN":"颜色"}]}},{"word":"cytoplasm","ipa_uk":"/ˈsaɪtəplæzəm/","ipa_us":"/ˈsaɪtəplæzəm/","definition_zh":"细胞质；细胞膜以内、细胞核以外的物质","definition_en":"the material inside a cell, outside the nucleus, including the cytosol and organelles","core_image":"一间屋子里的果冻状填充物，里面浮着各种小机器","scene":"The virus replicates in the cytoplasm before entering the nucleus.","sceneCN":"这里 cytoplasm 指「细胞质」（第 1 个义项：细胞膜内、细胞核外的物质）；句意：病毒先进入细胞质复制，再进入细胞核。","pos":[{"tag":"n.","zh":"细胞质（通常不可数）"}],"collocations":[{"phrase":"cytoplasm of the cell","zh":"细胞的细胞质"},{"phrase":"cytoplasm and nucleus","zh":"细胞质与细胞核"},{"phrase":"cytoplasm streaming","zh":"细胞质流动"},{"phrase":"cytoplasm of the egg","zh":"卵细胞的细胞质"},{"phrase":"cytoplasm layer","zh":"细胞质层"},{"phrase":"cytoplasm volume","zh":"细胞质体积"}],"forms":[{"label":"不可数用法","form":"cytoplasm（通常不加 -s）"},{"label":"形容词","form":"cytoplasmic（细胞质的）"},{"label":"复数（少见，指不同细胞的细胞质）","form":"cytoplasms"},{"label":"相关名词","form":"cytosol（细胞质基质）"}],"derivatives":[{"word":"cytoplasmic","pos":"adj.","zh":"细胞质的"},{"word":"cytosol","pos":"n.","zh":"细胞质基质"},{"word":"cytokinesis","pos":"n.","zh":"胞质分裂"},{"word":"cytoskeleton","pos":"n.","zh":"细胞骨架"},{"word":"organelle","pos":"n.","zh":"细胞器"}],"senses":[{"no":"01","title":"Material outside the nucleus","titleCN":"细胞核以外的细胞物质","definition":"the material of a cell lying outside the nucleus but inside the membrane","definitionCN":"位于细胞核以外、细胞膜以内的细胞物质","example":"The cytoplasm of a muscle fibre is crowded with mitochondria.","exampleCN":"肌纤维的细胞质里挤满了线粒体。","why":"cyto- names the cell and -plasm names a moulded substance, so the compound means the substance of the cell as opposed to its nucleus.","whyCN":"cyto- 指细胞，-plasm 指被塑造出的物质，因此复合词的意思是「细胞里的物质」，与细胞核相对。"},{"no":"02","title":"Including organelles","titleCN":"含细胞器的细胞质","definition":"the cytosol together with the organelles suspended in it","definitionCN":"细胞质基质以及悬浮其中的细胞器","example":"Fixation preserves the cytoplasm and its organelles together.","exampleCN":"固定液把细胞质与其中的细胞器一起保存下来。","why":"In ordinary use the word covers not only the fluid but everything floating in it, so organelles count as part of the cytoplasm.","whyCN":"在日常用法里，这个词不只指液体，也指浮在其中的一切，因此细胞器也算作细胞质的一部分。"},{"no":"03","title":"The cytosol alone","titleCN":"仅指细胞质基质","definition":"in stricter usage, the gel-like fluid excluding the organelles","definitionCN":"更严格的用法中，指不含细胞器的胶状液体","example":"Enzymes of glycolysis float free in the cytoplasm.","exampleCN":"糖酵解的酶游离在细胞质中。","why":"Biochemists need to distinguish the fluid from the structures inside it, and the word is sometimes narrowed to the fluid.","whyCN":"生物化学家需要把液体与其中的结构区分开，于是这个词有时被收窄到只指液体。"},{"no":"04","title":"A place where things happen","titleCN":"反应发生的场所","definition":"the compartment in which many metabolic reactions occur","definitionCN":"许多代谢反应发生的空间","example":"Protein synthesis begins in the cytoplasm.","exampleCN":"蛋白质合成始于细胞质。","why":"Once named, the substance becomes a location, and the word then answers the question 'where' rather than 'what'.","whyCN":"一旦被命名，这种物质就成了一个地点，于是这个词回答的是「在哪里」，而不是「是什么」。"},{"no":"05","title":"Movement and streaming","titleCN":"细胞质流动","definition":"the flowing movement of cytoplasm that shifts organelles within a cell","definitionCN":"细胞质的流动，使细胞器在细胞内移动","example":"Cytoplasm streaming carries chloroplasts toward the light.","exampleCN":"细胞质流动把叶绿体带向光照方向。","why":"Because the material moves, the word appears in names for that motion rather than only in descriptions of composition.","whyCN":"由于这种物质会流动，这个词出现在描述该运动的名称里，而不只是描述组成。"},{"no":"06","title":"Inherited cytoplasm","titleCN":"母体传来的细胞质","definition":"the cytoplasm contributed by the egg, which carries mitochondria and other maternal factors","definitionCN":"卵细胞提供的细胞质，携带线粒体等母源因子","example":"Mitochondrial DNA is inherited through the egg's cytoplasm.","exampleCN":"线粒体 DNA 通过卵细胞的细胞质遗传。","why":"Since the egg supplies almost all the cytoplasm of a zygote, the word marks the maternal contribution to inheritance.","whyCN":"由于受精卵的细胞质几乎全部来自卵细胞，这个词标出的是母方对遗传的贡献。"},{"no":"07","title":"In plant cells","titleCN":"植物细胞的细胞质","definition":"the cytoplasm of a plant cell, often compressed by a large vacuole","definitionCN":"植物细胞的细胞质，常被大液泡挤压","example":"In a mature plant cell the cytoplasm forms a thin layer.","exampleCN":"在成熟植物细胞中，细胞质只形成薄薄一层。","why":"A large vacuole pushes the material to the edge, and the same word describes a very differently shaped compartment.","whyCN":"大液泡把这种物质挤到边缘，同一个词描述的是一个形状很不同的隔间。"},{"no":"08","title":"Textbook and classroom sense","titleCN":"教学中的细胞质","definition":"the simplified schoolroom notion of the jelly filling a cell","definitionCN":"课堂上简化的说法：填满细胞的果冻状物质","example":"The diagram labels the cytoplasm as the jelly around the nucleus.","exampleCN":"这幅图把细胞质标注为细胞核周围的果冻状物质。","why":"Teaching needs a simple image, and the word is often used in that loose sense even where it is technically imprecise.","whyCN":"教学需要简单图像，因此即便在技术上不够精确，这个词也常被这样宽松地使用。"}],"etymology":{"intro":{"en":"Cytoplasm is a 19th-century compound of two Greek elements: a hollow or cell, and something moulded.","cn":"cytoplasm 是 19 世纪由两个希腊语成分构成的复合词：一个表示「空腔、细胞」，一个表示「被塑形之物」。"},"items":[{"era":"GREEK KYTOS","en":"Greek kytos meant a hollow vessel, a container or a cell of a honeycomb. In scientific compounds cyto- came to mean 'cell'.","cn":"希腊语 kytos 指中空的容器、器皿或蜂房的巢室。在科学复合词中，cyto- 逐渐表示「细胞」。"},{"era":"GREEK PLASMA","en":"Greek plasma meant something moulded or shaped, from plassein, 'to mould'. In medicine it named the fluid part of blood, and in biology it named the substance of a cell.","cn":"希腊语 plasma 指被塑造之物，源自动词 plassein「塑造」。医学中它指血液的液体部分，生物学中指细胞的物质。"},{"era":"MID-NINETEENTH CENTURY","en":"The compound cytoplasm is generally dated to the mid-19th century, when cytology separated the nucleus from the rest of the cell. The exact coinage is disputed.","cn":"cytoplasm 这一复合词一般认为出现于 19 世纪中叶，当时细胞学把细胞核与细胞的其余部分区分开来。确切的创造者尚有争议。"},{"era":"CYTOLOGY MATURES","en":"As cell theory matured, cytoplasm became the standard word for everything inside the membrane but outside the nucleus.","cn":"随着细胞学说成熟，cytoplasm 成为「膜内、核外一切物质」的标准说法。"},{"era":"MOLECULAR REFINEMENT","en":"In the 20th century the fluid alone was renamed cytosol, leaving cytoplasm as the broader term.","cn":"20 世纪，单指液体的部分被另名为 cytosol，cytoplasm 则保留为更宽的总称。"}]},"similar":{"note":{"en":"The first group separates cytoplasm from the fluid inside it and from the other compartments; the second separates it from neighbouring levels of cell description.","cn":"第一组把 cytoplasm 与它内部的液体以及其它隔间分开；第二组把它与邻近的细胞描述层次分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cytosol","ipa":"/ˈsaɪtəsɒl/","tag":"fluid only","definition":"The gel-like fluid of the cytoplasm excluding organelles; it is the narrower part of the same compartment.","definitionCN":"指细胞质中不含细胞器的胶状液体，是同一隔间里更窄的那部分。"},{"word":"nucleoplasm","ipa":"/ˈnjuːkliəplæzəm/","tag":"inside the nucleus","definition":"The material inside the nucleus; it is the counterpart of cytoplasm, not a synonym.","definitionCN":"指细胞核内的物质，是细胞质的对应物，而不是同义词。"},{"word":"cytoplasmic","ipa":"/ˌsaɪtəˈplæzmɪk/","tag":"the adjective","definition":"The adjective meaning 'of the cytoplasm'; cytoplasm is the noun, cytoplasmic describes location or origin.","definitionCN":"是形容词，意为「细胞质的」；cytoplasm 是名词，cytoplasmic 用于描述位置或来源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"protoplasm","ipa":"/ˈprəʊtəplæzəm/","tag":"older total term","definition":"An older word for all the living substance of a cell, nucleus included; cytoplasm replaced it for the part outside the nucleus.","definitionCN":"较老的说法，指细胞的全部活物质，包括细胞核；cytoplasm 取代它来指核外部分。"},{"word":"organelle","ipa":"/ˌɔːɡəˈnel/","tag":"structure, not material","definition":"A membrane-bound structure inside the cell; it floats in the cytoplasm and is counted as part of it in loose usage.","definitionCN":"指细胞内具膜的结构，漂浮在细胞质中，在宽松用法里算作细胞质的一部分。"},{"word":"matrix","ipa":"/ˈmeɪtrɪks/","tag":"general term","definition":"A surrounding substance in which things are embedded; it describes the same role without naming the cell.","definitionCN":"指物体嵌入其中的周围物质，描述同一角色但不点明细胞。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"cyto- 'cell' + -plasm 'moulded substance': the substance of the cell.","cn":"cyto-「细胞」+ -plasm「被塑形的物质」：细胞里的物质。"},{"en":"The family runs cytoplasmic, cytosol, cytoskeleton and organelle.","cn":"同族词有 cytoplasmic、cytosol、cytoskeleton、organelle。"},{"en":"Fixed phrases: cytoplasm streaming, cytoplasm and nucleus, cytoplasm volume.","cn":"固定搭配：细胞质流动、细胞质与细胞核、细胞质体积。"},{"en":"The nucleus is the office; the cytoplasm is the workshop floor.","cn":"细胞核是办公室，细胞质是车间地面。"},{"en":"cytosol is the fluid alone; cytoplasm includes what floats in it.","cn":"cytosol 只指液体，cytoplasm 还包括浮在里面的东西。"}],"abstract":[{"en":"Picture a jelly-filled room with machines suspended in it, all working without a floor plan.","cn":"想象一间装满果冻的房间，机器悬在其中，全都没有平面图也能干活。"},{"en":"Cytoplasm streaming is a slow conveyor belt made of liquid.","cn":"细胞质流动就是一条由液体组成的慢速传送带。"},{"en":"Inheriting cytoplasm is inheriting the mother's workshop, tools included.","cn":"继承细胞质就是继承母亲的车间，连工具一起。"}]},"examples":[{"en":"Ribosomes in the cytoplasm translate messenger RNA into protein.","cn":"细胞质中的核糖体把信使 RNA 翻译成蛋白质。"},{"en":"The dye spreads through the cytoplasm but not into the nucleus.","cn":"染料在细胞质中扩散，却不进入细胞核。"},{"en":"In a mature plant cell the cytoplasm is pressed against the wall by the vacuole.","cn":"在成熟植物细胞中，细胞质被液泡压到紧贴细胞壁。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cyto（细胞）+ plasm（塑成的物质）」→ 细胞里被塑成的那团物质 → 细胞质","word":"cytoplasm"},"root":"希腊语 kytos「中空容器、巢室」→ cyto-「细胞」；希腊语 plasma「被塑形之物」（源自 plassein「塑造」）→ -plasm；19 世纪中叶合成为 cytoplasm。","sensesIntro":{"en":"Eight senses treat one compartment in different ways: as material, as material plus organelles, as fluid alone, as a place, as something that moves, as maternal inheritance, as plant-cell shape, and as a classroom image.","cn":"八个义项从不同角度处理同一个隔间：作为物质、作为物质加细胞器、仅作液体、作为地点、作为会流动的东西、作为母源遗传、作为植物细胞的形态，以及作为课堂图像。"},"semanticMap":{"core":{"en":"CORE IMAGE: a jelly-filled room with small machines floating inside it.","cn":"核心意象：一间装满果冻的房间，里面浮着各种小机器。"},"chain":["SUBSTANCE OF A CELL","OUTSIDE THE NUCLEUS","CONTAINS ORGANELLES","A PLACE FOR REACTIONS","FLOWS AND MOVES","PASSED FROM THE EGG"],"branches":[{"senses":"S1 · S2","en":"MATERIAL: the cell substance, first as what lies outside the nucleus, then including the organelles.","cn":"物质：细胞里的物质，先指核外部分，再包括细胞器。"},{"senses":"S3","en":"THE FLUID ALONE: a stricter use that separates the liquid from the structures.","cn":"仅指液体：更严格的使用，把液体与结构分开。"},{"senses":"S4 · S5","en":"PLACE AND MOTION: a location for reactions, and a substance that streams.","cn":"地点与运动：反应发生的场所，以及会流动的物质。"},{"senses":"S6","en":"INHERITANCE: the egg's cytoplasm carries maternal factors.","cn":"遗传：卵细胞的细胞质携带母源因子。"},{"senses":"S7 · S8","en":"SHAPE AND SIMPLIFICATION: the compressed plant-cell layer, and the textbook jelly.","cn":"形态与简化：植物细胞中被压薄的一层，以及教科书里的果冻。"}]},"affixes":{"intro":{"en":"Cytoplasm is a Greek-Greek compound; both elements are still productive in cell biology.","cn":"cytoplasm 是希腊语与希腊语的复合词，两个成分在细胞生物学中仍然能产。"},"latinIntro":{"en":"Both elements are Greek: kytos for a hollow vessel and plasma for something moulded. Latin contributes no root here.","cn":"两个成分都来自希腊语：kytos 指中空容器，plasma 指被塑形之物。这里没有拉丁词根参与。"},"items":[{"word":"cytoplasm","structure":"cyto- + -plasm","meaning":"the substance of a cell outside the nucleus","meaningCN":"细胞核以外的细胞物质","example":"The cytoplasm contains most of the cell's water.","exampleCN":"细胞质含有细胞的大部分水分。"},{"word":"cytoplasmic","structure":"cytoplasm + -ic","meaning":"relating to the cytoplasm","meaningCN":"与细胞质有关的","example":"The protein has a cytoplasmic tail.","exampleCN":"这种蛋白有一段细胞质尾部。"},{"word":"cytosol","structure":"cyto- + sol (solution)","meaning":"the fluid part of the cytoplasm","meaningCN":"细胞质中的液体部分","example":"The cytosol is rich in enzymes.","exampleCN":"细胞质基质富含酶。"},{"word":"cytoskeleton","structure":"cyto- + skeleton","meaning":"the internal framework of the cell","meaningCN":"细胞的内部骨架","example":"The cytoskeleton shapes the cell.","exampleCN":"细胞骨架决定细胞的形状。"},{"word":"organelle","structure":"organ + -elle (diminutive)","meaning":"a small organ-like structure in the cell","meaningCN":"细胞内类似小器官的结构","example":"Each organelle has its own job.","exampleCN":"每个细胞器都有自己的任务。"},{"word":"protoplasm","structure":"proto- (first) + -plasm","meaning":"the whole living substance of a cell","meaningCN":"细胞的全部活物质","example":"Protoplasm was an older term for cell material.","exampleCN":"protoplasm 是细胞物质的旧称。"},{"word":"nucleoplasm","structure":"nucleo- + -plasm","meaning":"the material inside the nucleus","meaningCN":"细胞核内的物质","example":"Nucleoplasm surrounds the chromatin.","exampleCN":"核质包围着染色质。"},{"word":"plasma","structure":"Greek plasma, 'moulded thing'","meaning":"the fluid part of blood; an ionised gas","meaningCN":"血液的液体部分；电离气体","example":"Plasma carries the blood cells.","exampleCN":"血浆运载血细胞。"},{"word":"plastid","structure":"Greek plastos (moulded) + -id","meaning":"a plant-cell organelle such as a chloroplast","meaningCN":"植物细胞器，如叶绿体","example":"The plastid stores starch.","exampleCN":"该质体储存淀粉。"}],"latinEntries":[{"word":"κύτος","structure":"Greek noun, 'hollow vessel, cell'","meaning":"a hollow container; a honeycomb cell","meaningCN":"中空容器；蜂房巢室"},{"word":"πλάσμα","structure":"Greek noun from plassein, 'to mould'","meaning":"something moulded or shaped","meaningCN":"被塑造之物"},{"word":"πλάσσειν","structure":"Greek verb","meaning":"to mould, to shape","meaningCN":"塑造；使成形"}]}},{"word":"cytoplasmic","ipa_uk":"/ˌsaɪtəˈplæzmɪk/","ipa_us":"/ˌsaɪtəˈplæzmɪk/","definition_zh":"细胞质的；位于或发生在细胞质中的","definition_en":"relating to the cytoplasm, or located and occurring within it","core_image":"细胞核外那团果冻里，一条条蛋白质伸出的尾巴","scene":"The receptor's cytoplasmic tail carries the signal into the cell.","sceneCN":"这里 cytoplasmic 指「位于细胞质内的」（第 2 个义项：位于细胞质中的结构部分）；句意：该受体的胞质尾部把信号传入细胞。","pos":[{"tag":"adj.","zh":"细胞质的；细胞质内的；胞质的"}],"collocations":[{"phrase":"cytoplasmic membrane","zh":"胞质膜；细菌质膜"},{"phrase":"cytoplasmic streaming","zh":"胞质环流"},{"phrase":"cytoplasmic inheritance","zh":"细胞质遗传"},{"phrase":"cytoplasmic domain","zh":"胞质结构域"},{"phrase":"cytoplasmic tail","zh":"胞质尾"},{"phrase":"cytoplasmic granules","zh":"胞质颗粒"}],"forms":[{"label":"比较级","form":"more cytoplasmic"},{"label":"最高级","form":"most cytoplasmic"},{"label":"名词形式","form":"cytoplasm（细胞质）"},{"label":"副词形式","form":"cytoplasmically（在细胞质层面，少用）"}],"derivatives":[{"word":"cytoplasm","pos":"n.","zh":"细胞质"},{"word":"cytoplasmically","pos":"adv.","zh":"在细胞质层面（少用）"},{"word":"cytosol","pos":"n.","zh":"细胞质基质"},{"word":"cytoskeleton","pos":"n.","zh":"细胞骨架"},{"word":"cytokinesis","pos":"n.","zh":"胞质分裂"}],"senses":[{"no":"01","title":"Of the cytoplasm","titleCN":"细胞质的","definition":"relating to the cytoplasm as a substance or compartment","definitionCN":"与细胞质这一物质或隔间有关的","example":"Cytoplasmic volume shrinks as the cell divides.","exampleCN":"细胞分裂时，细胞质的体积会缩小。","why":"The suffix -ic turns cytoplasm into an adjective, so any description of that material or its amount can use it.","whyCN":"后缀 -ic 把 cytoplasm 变成形容词，因此任何描述这种物质或其数量的说法都能用它。"},{"no":"02","title":"Located inside the cytoplasm","titleCN":"位于细胞质内的","definition":"situated within the cytoplasm rather than in the nucleus or the membrane","definitionCN":"位于细胞质内，而不是细胞核或细胞膜中","example":"Cytoplasmic proteins are translated on free ribosomes.","exampleCN":"胞质蛋白在游离核糖体上翻译。","why":"Once the noun names a place, the adjective marks what lies inside that place, often in contrast with nuclear.","whyCN":"一旦名词命名了一个地点，形容词就标出位于该地点内部的东西，常与 nuclear 相对。"},{"no":"03","title":"Bacterial plasma membrane","titleCN":"胞质膜；细菌质膜","definition":"in bacteria, describing the membrane that bounds the cytoplasm","definitionCN":"在细菌中，指包围细胞质的膜","example":"The cytoplasmic membrane separates the cell from its surroundings.","exampleCN":"胞质膜把细胞与外界隔开。","why":"Bacteria have no separate inner membranes, so the membrane around their cytoplasm is named with this adjective.","whyCN":"细菌没有独立的内膜，因此包围其细胞质的那层膜就用这个形容词来命名。"},{"no":"04","title":"Streaming","titleCN":"胞质环流的","definition":"describing the flowing movement of cytoplasm inside a cell","definitionCN":"描述细胞质在细胞内部的流动","example":"Cytoplasmic streaming mixes the contents of the cell.","exampleCN":"胞质环流使细胞内的物质混合。","why":"The movement belongs to the cytoplasm, so the adjective plus the noun streaming names a process rather than a structure.","whyCN":"这种运动属于细胞质，因此这个形容词加名词 streaming 命名的是一种过程，而不是结构。"},{"no":"05","title":"Inheritance through cytoplasm","titleCN":"细胞质遗传的","definition":"describing genes inherited through cytoplasmic organelles rather than the nucleus","definitionCN":"指通过细胞质中的细胞器而非细胞核遗传的基因","example":"Mitochondrial disease shows a cytoplasmic pattern of inheritance.","exampleCN":"线粒体疾病表现出细胞质遗传模式。","why":"Mitochondria sit outside the nucleus, so their genes pass with the cytoplasm and need a separate label.","whyCN":"线粒体位于细胞核之外，其基因随细胞质传递，因此需要一个单独的标签。"},{"no":"06","title":"Protein domains","titleCN":"胞质结构域的","definition":"describing the part of a membrane protein that projects into the cytoplasm","definitionCN":"指膜蛋白伸入细胞质的那一部分","example":"The cytoplasmic domain binds a signalling protein.","exampleCN":"胞质结构域结合一种信号蛋白。","why":"A receptor spans the membrane, and the adjective locates one of its ends on the cytoplasmic side.","whyCN":"受体横跨细胞膜，这个形容词把它的某一端定位在细胞质一侧。"},{"no":"07","title":"Granules and inclusions","titleCN":"胞质颗粒的","definition":"describing small bodies or deposits stored in the cytoplasm","definitionCN":"指储存在细胞质中的小体或沉积物","example":"Cytoplasmic granules of pigment give the cell its colour.","exampleCN":"胞质中的色素颗粒使细胞呈现颜色。","why":"Storage bodies are named by where they sit, so the adjective tells the reader they are cytoplasmic rather than nuclear.","whyCN":"储存小体按其所处位置命名，因此这个形容词告诉读者它们在细胞质而不在细胞核。"},{"no":"08","title":"Division of the cytoplasm","titleCN":"胞质分裂的","definition":"describing the physical splitting of the cytoplasm after chromosomes separate","definitionCN":"指染色体分开之后细胞质的物理性分裂","example":"Cytoplasmic division follows the completion of mitosis.","exampleCN":"胞质分裂在有丝分裂完成后进行。","why":"The last step of division is the splitting of the cytoplasm itself, so the adjective marks which part of the cell is being divided.","whyCN":"分裂的最后一步是细胞质本身的分开，因此这个形容词标出被分开的是细胞的哪一部分。"}],"etymology":{"intro":{"en":"Cytoplasmic is the adjective of cytoplasm, a Greek compound coined in 19th-century cytology, with the English suffix -ic.","cn":"cytoplasmic 是 cytoplasm 的形容词；cytoplasm 是 19 世纪细胞学造出的希腊语复合词，形容词加英语后缀 -ic。"},"items":[{"era":"GREEK KYTOS","en":"cyto- comes from Greek kytos, a hollow vessel or a honeycomb cell, which cytology adopted for 'cell'.","cn":"cyto- 出自希腊语 kytos「中空容器、蜂巢巢室」，细胞学用它表示「细胞」。"},{"era":"GREEK PLASMA","en":"plasma meant something moulded, from plassein, 'to mould'. It named the substance of the cell as distinct from its nucleus.","cn":"plasma 指被塑造之物，源自动词 plassein「塑造」。它指细胞中与细胞核相对的物质。"},{"era":"NINETEENTH-CENTURY CYTOLOGY","en":"Cytoplasm is generally dated to the mid-19th century, when the nucleus was distinguished from the rest of the cell. The adjective cytoplasmic followed the noun.","cn":"cytoplasm 一般认为出现于 19 世纪中叶，当时细胞核与细胞的其余部分被区分开来。形容词 cytoplasmic 随后出现。"},{"era":"TWENTIETH-CENTURY CELL BIOLOGY","en":"As membrane proteins and cytoplasmic inheritance were studied, the adjective became standard in compounds such as cytoplasmic domain and cytoplasmic tail.","cn":"随着膜蛋白与细胞质遗传被研究，这个形容词在 cytoplasmic domain、cytoplasmic tail 等复合词中成为标准用法。"},{"era":"MOLECULAR ERA","en":"Modern cell biology uses cytoplasmic to mark one side of the nuclear-cytoplasmic boundary in signalling and transport.","cn":"现代细胞生物学用 cytoplasmic 标出信号与运输中核与胞质分界的一侧。"}]},"similar":{"note":{"en":"The first group separates the adjective from the noun and from the fluid-specific term; the second separates cytoplasmic from the other side of the nuclear boundary and from related adjectives.","cn":"第一组把这个形容词与名词以及专指液体的术语分开；第二组把 cytoplasmic 与核质分界的另一侧及相关形容词分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cytoplasm","ipa":"/ˈsaɪtəplæzəm/","tag":"the noun","definition":"The material itself; cytoplasmic is the modifier used before nouns such as tail, domain or streaming.","definitionCN":"指物质本身；cytoplasmic 是修饰 tail、domain、streaming 等名词时使用的形式。"},{"word":"cytosolic","ipa":"/ˌsaɪtəˈsɒlɪk/","tag":"fluid only","definition":"Relating specifically to the cytosol, the fluid excluding organelles; it is narrower than cytoplasmic.","definitionCN":"专指细胞质基质，即不含细胞器的液体，比 cytoplasmic 更窄。"},{"word":"cytological","ipa":"/ˌsaɪtəˈlɒdʒɪkl/","tag":"study, not location","definition":"Relating to cytology, the study of cells; it describes a method or a field, not a position inside the cell.","definitionCN":"指与细胞学这门研究有关的，描述方法或学科，而不是细胞内部的位置。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nuclear","ipa":"/ˈnjuːkliə(r)/","tag":"opposite side","definition":"Relating to the nucleus; in cell biology it marks the other side of the boundary from cytoplasmic.","definitionCN":"指与细胞核有关的；在细胞生物学中，它标出与 cytoplasmic 相对的核一侧。"},{"word":"intracellular","ipa":"/ˌɪntrəˈseljələ(r)/","tag":"whole cell","definition":"Located anywhere inside a cell, nucleus included; cytoplasmic excludes the nucleus.","definitionCN":"指位于细胞内任何位置，包括细胞核；cytoplasmic 则排除细胞核。"},{"word":"membranous","ipa":"/ˈmembrənəs/","tag":"material, not place","definition":"Made of or resembling membrane; it describes structure rather than the cytoplasmic compartment.","definitionCN":"指由膜构成或类似膜的，描述结构而不是细胞质这一隔间。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"cytoplasm + -ic: the adjective of the material outside the nucleus.","cn":"cytoplasm + -ic：细胞核外那团物质的形容词。"},{"en":"The family runs cytoplasm, cytosol, cytoskeleton and cytokinesis.","cn":"同族词有 cytoplasm、cytosol、cytoskeleton、cytokinesis。"},{"en":"Fixed phrases: cytoplasmic tail, cytoplasmic domain, cytoplasmic streaming, cytoplasmic inheritance.","cn":"固定搭配：胞质尾、胞质结构域、胞质环流、细胞质遗传。"},{"en":"In receptor diagrams, the cytoplasmic side is the end that faces the cell's inside.","cn":"在受体示意图里，胞质一侧就是朝向细胞内部的那一端。"},{"en":"cytoplasmic and nuclear are a matched pair, like outside and inside.","cn":"cytoplasmic 与 nuclear 是一对，就像外侧与内侧。"}],"abstract":[{"en":"Think of a house with a locked study: everything in the other rooms is cytoplasmic.","cn":"想象一栋房子有一间上锁的书房：其它房间里的东西都是 cytoplasmic。"},{"en":"A receptor's cytoplasmic tail is the part of a rope that hangs inside the room.","cn":"受体的胞质尾就像一根绳子垂在房间内部的那一段。"},{"en":"Cytoplasmic inheritance is a family recipe kept in the kitchen, not in the study.","cn":"细胞质遗传像一份放在厨房而不是书房的祖传食谱。"}]},"examples":[{"en":"Cytoplasmic streaming distributes nutrients in large plant cells.","cn":"胞质环流在大植物细胞中分配养分。"},{"en":"The cytoplasmic tail of the receptor recruits an enzyme.","cn":"受体的胞质尾招募一种酶。"},{"en":"Cytoplasmic inheritance explains why mitochondrial disease passes through mothers.","cn":"细胞质遗传解释了线粒体疾病为何经母亲传递。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cytoplasm + -ic」→ 细胞质那一类的 → 细胞质的、胞质的","word":"cytoplasmic"},"root":"希腊语 kytos「中空容器」+ plasma「被塑形之物」→ cytoplasm；加形容词后缀 -ic 构成 cytoplasmic。","sensesIntro":{"en":"Eight senses locate the adjective across the cytoplasm: its substance, its interior, the bacterial membrane, its streaming, its inheritance, the cytoplasmic ends of proteins, its granules, and its division.","cn":"八个义项把这个形容词铺在细胞质各处：它的物质、它的内部、细菌的质膜、它的流动、它的遗传、蛋白质的胞质端、胞质颗粒，以及胞质分裂。"},"semanticMap":{"core":{"en":"CORE IMAGE: a protein tail hanging into the jelly outside the nucleus.","cn":"核心意象：一条蛋白质尾巴垂在细胞核外的果冻里。"},"chain":["OF THE CYTOPLASM","INSIDE THE CELL","BOUNDING MEMBRANE","STREAMING FLOW","INHERITED FACTORS","TAILS AND DOMAINS"],"branches":[{"senses":"S1 · S2","en":"SUBSTANCE AND LOCATION: the material, and things situated inside it.","cn":"物质与位置：这种物质，以及位于其中的东西。"},{"senses":"S3 · S8","en":"BOUNDARY AND SPLITTING: the bacterial membrane around it, and the division that separates it.","cn":"边界与分裂：包围它的细菌质膜，以及把它分开的分裂。"},{"senses":"S4","en":"MOTION: streaming moves the contents around.","cn":"运动：环流使内部物质移动。"},{"senses":"S5","en":"INHERITANCE: genes outside the nucleus travel with the cytoplasm.","cn":"遗传：细胞核外的基因随细胞质传递。"},{"senses":"S6 · S7","en":"MOLECULES: the cytoplasmic ends of membrane proteins, and stored granules.","cn":"分子：膜蛋白的胞质端，以及储存的颗粒。"}]},"affixes":{"intro":{"en":"Cytoplasmic adds -ic to a Greek-Greek compound; its family is dense in cell biology.","cn":"cytoplasmic 在希腊语复合词后加 -ic；其词族在细胞生物学中很密集。"},"latinIntro":{"en":"Greek kytos and plasma build the noun; the suffix -ic comes from Latin -icus and Greek -ikos. No Latin root is involved.","cn":"希腊语 kytos 与 plasma 构成名词；后缀 -ic 来自拉丁语 -icus 与希腊语 -ikos。没有拉丁词根参与。"},"items":[{"word":"cytoplasmic","structure":"cytoplasm + -ic","meaning":"relating to the cytoplasm","meaningCN":"与细胞质有关的","example":"The cytoplasmic side faces the cell interior.","exampleCN":"胞质一侧朝向细胞内部。"},{"word":"cytoplasm","structure":"cyto- + -plasm","meaning":"the material outside the nucleus","meaningCN":"细胞核外的物质","example":"The cytoplasm is mostly water.","exampleCN":"细胞质大部分是水。"},{"word":"cytosol","structure":"cyto- + sol","meaning":"the fluid part of the cytoplasm","meaningCN":"细胞质的液体部分","example":"The cytosol contains the enzymes of glycolysis.","exampleCN":"细胞质基质含有糖酵解的酶。"},{"word":"cytoskeleton","structure":"cyto- + skeleton","meaning":"the cell's internal scaffold","meaningCN":"细胞的内部支架","example":"The cytoskeleton anchors organelles.","exampleCN":"细胞骨架固定细胞器。"},{"word":"cytokinesis","structure":"cyto- + Greek kinesis (movement)","meaning":"division of the cytoplasm","meaningCN":"细胞质的分裂","example":"Cytokinesis ends with two separate cells.","exampleCN":"胞质分裂以两个独立细胞告终。"},{"word":"organelle","structure":"organ + -elle","meaning":"a structure inside the cytoplasm","meaningCN":"细胞质内的结构","example":"Mitochondria are cytoplasmic organelles.","exampleCN":"线粒体是细胞质中的细胞器。"},{"word":"intracellular","structure":"intra- + cellular","meaning":"inside a cell","meaningCN":"细胞内的","example":"The bacterium survives intracellularly.","exampleCN":"这种细菌在细胞内生存。"},{"word":"extracellular","structure":"extra- + cellular","meaning":"outside a cell","meaningCN":"细胞外的","example":"The signal starts extracellular.","exampleCN":"信号从细胞外开始。"},{"word":"nuclear","structure":"nucleus + -ar","meaning":"relating to the nucleus","meaningCN":"与细胞核有关的","example":"Nuclear proteins return to the nucleus.","exampleCN":"核蛋白会回到细胞核。"}],"latinEntries":[{"word":"κύτος","structure":"Greek noun, 'hollow vessel'","meaning":"a hollow container; a cell","meaningCN":"中空容器；细胞"},{"word":"πλάσμα","structure":"Greek noun from plassein","meaning":"something moulded","meaningCN":"被塑造之物"},{"word":"-ικός","structure":"Greek adjective suffix","meaning":"pertaining to","meaningCN":"属于……的"}]}},{"word":"nucleus","ipa_uk":"/ˈnjuːkliəs/","ipa_us":"/ˈnuːkliəs/","definition_zh":"细胞核；原子核；核心","definition_en":"the central part of a cell or atom, or the core of a group or object","core_image":"一个果核：坚硬的小圆体，所有东西都围着它转","scene":"The nucleus of a cell contains most of its DNA.","sceneCN":"这里 nucleus 指「细胞核」（第 1 个义项：细胞内保存 DNA 的中央结构）；句意：细胞核保存着细胞的大部分 DNA。","pos":[{"tag":"n.","zh":"细胞核；原子核；核心；中心部分；神经核；（音节的）核"}],"collocations":[{"phrase":"cell nucleus","zh":"细胞核"},{"phrase":"atomic nucleus","zh":"原子核"},{"phrase":"nucleus of the atom","zh":"原子核"},{"phrase":"comet nucleus","zh":"彗核"},{"phrase":"nucleus of a group","zh":"群体的核心"},{"phrase":"syllable nucleus","zh":"音节核"}],"forms":[{"label":"复数（拉丁语 -us 变 -i）","form":"nuclei"},{"label":"复数（英语化，少用）","form":"nucleuses"},{"label":"形容词","form":"nuclear（核的）"},{"label":"果核义（拉丁本义，现代英语少用）","form":"nucleus（坚果仁）"}],"derivatives":[{"word":"nuclear","pos":"adj.","zh":"核的；原子核的；细胞核的"},{"word":"nucleolus","pos":"n.","zh":"核仁"},{"word":"nucleated","pos":"adj.","zh":"有核的"},{"word":"enucleate","pos":"v.","zh":"去核"},{"word":"nucleation","pos":"n.","zh":"成核作用"}],"senses":[{"no":"01","title":"Cell nucleus","titleCN":"细胞核","definition":"the membrane-bound organelle that contains most of a cell's DNA","definitionCN":"细胞中含有大部分 DNA 的膜结合细胞器","example":"The nucleus of a human cell holds twenty-three pairs of chromosomes.","exampleCN":"人类细胞的细胞核里有二十三对染色体。","why":"The biological sense was named after the kernel of a nut: a small central body around which the rest is arranged.","whyCN":"生物学义按坚果的果核命名：一个居中的小体，其余部分围绕它安排。"},{"no":"02","title":"Atomic nucleus","titleCN":"原子核","definition":"the dense central core of an atom, made of protons and neutrons","definitionCN":"原子中由质子与中子构成的致密中心","example":"The nucleus of carbon-12 contains six protons and six neutrons.","exampleCN":"碳-12 的原子核含有六个质子和六个中子。","why":"Physics reused the kernel image for the tiny centre of an atom, because almost all its mass sits there.","whyCN":"物理学把果核意象用于原子的微小中心，因为原子几乎全部质量都在那里。"},{"no":"03","title":"Core of a group","titleCN":"核心（人群）","definition":"the central group of people around whom a larger body forms","definitionCN":"较大群体围绕其形成的核心人群","example":"A small nucleus of volunteers kept the project alive.","exampleCN":"一小群志愿者构成的核心让项目维持下去。","why":"A group with a hard centre and looser edges matches the kernel image, so the word serves for social structure as well.","whyCN":"一个有坚硬核心与松散边缘的群体符合果核意象，因此这个词也用于社会结构。"},{"no":"04","title":"Central part of an object","titleCN":"物体的中心部分","definition":"the central mass of a comet, crystal or other object","definitionCN":"彗星、晶体或其它物体的中心团块","example":"The comet's nucleus is a dirty ball of ice and rock.","exampleCN":"彗核是一个由冰与岩石组成的脏雪球。","why":"The word generalises from the kernel to any object's central solid part.","whyCN":"这个词从果核泛化，指任何物体中心那个坚实的部分。"},{"no":"05","title":"Brain nucleus","titleCN":"神经核","definition":"a cluster of nerve cells in the brain or spinal cord","definitionCN":"脑或脊髓中一簇神经细胞","example":"The nucleus accumbens is linked to reward.","exampleCN":"伏隔核与奖赏有关。","why":"Anatomists saw clustered cell bodies as kernels inside the nervous tissue, and named them accordingly.","whyCN":"解剖学家把聚在一起的细胞体看作神经组织里的果核，于是如此命名。"},{"no":"06","title":"Syllable nucleus","titleCN":"音节核","definition":"the vowel or vowel-like sound that forms the centre of a syllable","definitionCN":"构成音节中心的元音或类元音","example":"In the word 'cat', the vowel is the syllable nucleus.","exampleCN":"在 cat 这个词里，元音就是音节核。","why":"Linguists borrowed the word for the part every syllable must have at its centre, with consonants around it.","whyCN":"语言学家借用这个词，指每个音节中心必须具备的成分，辅音围绕它排列。"},{"no":"07","title":"Galactic nucleus","titleCN":"星系核","definition":"the dense central region of a galaxy","definitionCN":"星系中央的致密区域","example":"The galactic nucleus glows with billions of old stars.","exampleCN":"星系核因数十亿颗老年恒星而发光。","why":"Astronomy applies the kernel image at the largest scale, where mass and light concentrate at the centre.","whyCN":"天文学把果核意象用到最大尺度，那里质量与光都集中在中心。"},{"no":"08","title":"Nucleation centre","titleCN":"成核中心","definition":"a small particle or site where a new phase begins to form","definitionCN":"新相开始形成的小颗粒或位点","example":"Dust provides the nuclei on which cloud droplets condense.","exampleCN":"尘埃提供了云滴凝结所需的核。","why":"A growing crystal or droplet needs a seed at its centre, and the word names that starting point.","whyCN":"生长中的晶体或液滴需要中心的一个种子，这个词就命名那个起点。"},{"no":"09","title":"Nucleus of a collection","titleCN":"藏品或收藏的核心","definition":"the original small set of items around which a larger collection grows","definitionCN":"较大收藏围绕其生长的最初那一小批藏品","example":"Six paintings formed the nucleus of the museum's collection.","exampleCN":"六幅画构成了这家博物馆藏品的核心。","why":"The kernel image extends to collections: a small hard core of founding items attracts more around it.","whyCN":"果核意象延伸到收藏：一小批创始藏品构成坚硬的核心，吸引更多东西围绕它聚集。"}],"etymology":{"intro":{"en":"Nucleus is Latin for a nut's kernel; science then applied the little central body to cells, atoms, brains and galaxies.","cn":"nucleus 在拉丁语里指坚果的果核；科学随后把这个居中的小体用于细胞、原子、脑与星系。"},"items":[{"era":"LATIN NUX","en":"Latin nux, with the stem nuc-, meant a nut. Its diminutive nucleus meant the small kernel inside a shell.","cn":"拉丁语 nux（词干 nuc-）指坚果。其指小形式 nucleus 指壳内的小果仁。"},{"era":"LATIN NUCLEUS","en":"Nucleus kept the physical sense of a kernel, and by extension any hard central part. English borrowed it in the 17th century.","cn":"nucleus 保留了果仁的具体意义，并引申指任何坚硬的中心部分。英语在 17 世纪借入。"},{"era":"1831 ROBERT BROWN","en":"Robert Brown described a small body inside plant cells and called it the nucleus in 1831, a term generally credited to him.","cn":"Robert Brown 在 1831 年描述植物细胞内的一个小体并称之为 nucleus，这一术语一般认为出自他。"},{"era":"1911 ATOMIC NUCLEUS","en":"After Rutherford's scattering experiments, the dense centre of the atom was called the nucleus. The date is approximate, around 1911 to 1912.","cn":"卢瑟福散射实验之后，原子的致密中心被称为 nucleus。年代约为 1911 至 1912 年。"},{"era":"TWENTIETH-CENTURY EXTENSIONS","en":"The word spread to astronomy, neuroanatomy and linguistics, always keeping the shape of a centre with surrounding parts.","cn":"这个词扩散到天文学、神经解剖学与语言学，始终保留「中心加周围部分」的形状。"}]},"similar":{"note":{"en":"The first group separates nucleus from the adjective and from the smaller body inside it; the second separates it from general words for a centre.","cn":"第一组把 nucleus 与它的形容词以及它内部更小的结构分开；第二组把它与泛指的「中心」词分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nuclear","ipa":"/ˈnjuːkliə(r)/","tag":"the adjective","definition":"The adjective meaning 'of a nucleus'; it is used in nuclear physics and nuclear envelope, while nucleus is the countable noun.","definitionCN":"是形容词，意为「核的」，用于核物理与核膜等；nucleus 是可数名词。"},{"word":"nucleolus","ipa":"/ˌnjuːkliˈəʊləs/","tag":"a body inside the nucleus","definition":"A small structure within the cell nucleus where ribosomes are assembled; it is not the nucleus itself.","definitionCN":"指细胞核内组装核糖体的小结构，不是细胞核本身。"},{"word":"nucleotide","ipa":"/ˈnjuːkliətaɪd/","tag":"a molecule, not a body","definition":"The building block of DNA and RNA; it shares the nuc- root through the idea of a core, but names a molecule.","definitionCN":"指 DNA 与 RNA 的构件；它通过「核心」的观念共享 nuc- 词根，但指的是分子。"}]},{"heading":"NEAR MEANING","entries":[{"word":"core","ipa":"/kɔː(r)/","tag":"general centre","definition":"The central part of anything, often of an apple or the earth; it is the everyday synonym of nucleus outside science.","definitionCN":"指任何事物的中心部分，常见于苹果核或地核；是 nucleus 在科学之外的日常同义词。"},{"word":"centre","ipa":"/ˈsentə(r)/","tag":"geometric middle","definition":"The middle point or area of a space; it describes position, not a distinct body with surrounding parts.","definitionCN":"指空间的中心点或区域，描述位置，而不是一个带周围部分的独立小体。"},{"word":"kernel","ipa":"/ˈkɜːnl/","tag":"literal source image","definition":"The edible part inside a nut, and the literal sense behind nucleus; it is also used figuratively for the essence of a matter.","definitionCN":"指坚果内的可食部分，是 nucleus 背后的字面义；也比喻事情的要点。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"nucleus is Latin for a nut's kernel: the hard thing in the middle.","cn":"nucleus 是拉丁语的「果仁」：中间那个硬东西。"},{"en":"The family runs nuclear, nucleolus, nucleated, enucleate and nucleation.","cn":"同族词有 nuclear、nucleolus、nucleated、enucleate、nucleation。"},{"en":"Fixed phrases: cell nucleus, atomic nucleus, comet nucleus, syllable nucleus.","cn":"固定搭配：细胞核、原子核、彗核、音节核。"},{"en":"The plural is nuclei, not nucleuses, in scientific writing.","cn":"科学写作中复数用 nuclei，而不用 nucleuses。"},{"en":"Every use keeps the same picture: a centre with a surrounding body.","cn":"每个用法都保留同一幅图：一个中心加一个围绕它的整体。"}],"abstract":[{"en":"Picture a peach: the stone is the nucleus, the flesh is everything that surrounds it.","cn":"想象一只桃子：桃核是 nucleus，果肉是围绕它的一切。"},{"en":"An atom is a tiny solar system with the nucleus as its sun.","cn":"原子像一个微型太阳系，原子核就是它的太阳。"},{"en":"A nucleus of volunteers is a seed crystal around which a project forms.","cn":"志愿者的核心就是一颗种子晶体，项目围绕它生长。"}]},"examples":[{"en":"The nucleus stores the cell's chromosomes and controls gene expression.","cn":"细胞核储存细胞的染色体并控制基因表达。"},{"en":"Protons and neutrons occupy the atomic nucleus.","cn":"质子与中子占据原子核。"},{"en":"A small nucleus of supporters organised the campaign.","cn":"一小群支持者构成的核心组织了这场运动。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nucleus 就是果核」→ 中间那个核 → 细胞核、原子核、核心","word":"nucleus"},"root":"拉丁语 nux（坚果，词干 nuc-）→ 指小形式 nucleus「果仁、小核」→ 英语 nucleus；细胞核义始于 1831 年 Robert Brown，原子核义约始于 1911 年。","sensesIntro":{"en":"Nine senses keep one shape: a compact centre surrounded by a larger body. The kernel becomes a cell organelle, an atomic core, a group of people, a comet's heart, a brain cluster, a syllable's vowel, a galactic centre, a seed crystal, and finally the founding core of a collection.","cn":"九个义项保持同一种形状：一个紧凑的中心，被更大的整体包围。果仁先后变成细胞器、原子核心、人群核心、彗星中心、脑内细胞簇、音节元音、星系中心、成核种子，最后成为一批藏品围绕其生长的收藏核心。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hard kernel at the centre, with everything else arranged around it.","cn":"核心意象：中央一颗坚硬的果核，其余一切都围着它安排。"},"chain":["KERNEL OF A NUT","SMALL CENTRAL BODY","CELL AND ATOM","DENSE CENTRE","GROUP AND SYLLABLE","SEED AND FOUNDING CORE"],"branches":[{"senses":"S1 · S2","en":"THE TWO SCIENTIFIC CENTRES: the organelle that holds DNA, and the dense core of the atom.","cn":"两个科学中心：保存 DNA 的细胞器，以及原子的致密核心。"},{"senses":"S3 · S4","en":"SOCIAL AND PHYSICAL CORES: a founding group, and the solid centre of a comet or crystal.","cn":"社会与物理核心：一个创始群体，以及彗星或晶体的坚实中心。"},{"senses":"S5 · S7","en":"ANATOMY AND ASTRONOMY: clustered nerve cells, and the centre of a galaxy.","cn":"解剖与天文：聚成一团的神经细胞，以及星系的中心。"},{"senses":"S6","en":"LINGUISTICS: the vowel at the centre of a syllable.","cn":"语言学：音节中心的元音。"},{"senses":"S8 · S9","en":"SEED AND SOURCE: the site where growth starts, and the founding core of a collection.","cn":"种子与本源：生长开始的位点，以及一批藏品围绕其生长的收藏核心。"}]},"affixes":{"intro":{"en":"Nucleus is a Latin diminutive with no prefix; its family is built with -ar, -olus and -ation.","cn":"nucleus 是拉丁语指小词，不带前缀；其词族由 -ar、-olus、-ation 等构成。"},"latinIntro":{"en":"Latin nux and its diminutive nucleus supply the root. The adjective nuclear adds -ar; nucleolus is a further diminutive; nucleation adds -ation.","cn":"拉丁语 nux 及其指小形式 nucleus 提供词根。形容词 nuclear 加 -ar；nucleolus 是再一层指小；nucleation 加 -ation。"},"items":[{"word":"nucleus","structure":"Latin nucleus, diminutive of nux","meaning":"kernel; central body","meaningCN":"果仁；中心小体","example":"The nucleus is bounded by a membrane.","exampleCN":"细胞核由一层膜包围。"},{"word":"nuclear","structure":"nucleus + -ar","meaning":"relating to a nucleus","meaningCN":"与核有关的","example":"Nuclear fission releases energy.","exampleCN":"核裂变释放能量。"},{"word":"nucleolus","structure":"nucleus + -olus (diminutive)","meaning":"a small body inside the nucleus","meaningCN":"细胞核内的小体","example":"The nucleolus assembles ribosomes.","exampleCN":"核仁组装核糖体。"},{"word":"nucleated","structure":"nucleus + -ate + -ed","meaning":"having a nucleus","meaningCN":"有核的","example":"Nucleated cells are larger than bacteria.","exampleCN":"有核细胞比细菌大。"},{"word":"enucleate","structure":"e- (out) + nucleus + -ate","meaning":"to remove the nucleus","meaningCN":"去除细胞核","example":"The researchers enucleated the egg.","exampleCN":"研究者去除了卵细胞的核。"},{"word":"nucleation","structure":"nucleate + -ion","meaning":"the formation of a first small centre","meaningCN":"最初小核心的形成","example":"Nucleation starts when the liquid cools.","exampleCN":"液体冷却时成核开始。"},{"word":"nucleotide","structure":"nucleo- + -tide","meaning":"the building block of nucleic acids","meaningCN":"核酸的构件","example":"Each nucleotide carries a base.","exampleCN":"每个核苷酸携带一个碱基。"},{"word":"nucleic","structure":"nucleus + -ic","meaning":"relating to the nucleus, used in nucleic acid","meaningCN":"与核有关的，用于「核酸」","example":"Nucleic acids store genetic information.","exampleCN":"核酸储存遗传信息。"},{"word":"karyon","structure":"Greek karyon, 'nut, kernel'","meaning":"the nucleus, in Greek compounds","meaningCN":"希腊语复合词中的「核」","example":"Karyotype pictures the whole nucleus.","exampleCN":"核型图展示整个细胞核。"}],"latinEntries":[{"word":"nux","structure":"Latin noun, stem nuc-, 'nut'","meaning":"a nut","meaningCN":"坚果"},{"word":"nucleus","structure":"Latin diminutive of nux","meaning":"kernel; small central body","meaningCN":"果仁；中心小体"},{"word":"nucleolus","structure":"Latin further diminutive of nucleus","meaning":"a little kernel","meaningCN":"小果仁"}]}},{"word":"nuclear","ipa_uk":"/ˈnjuːkliə(r)/","ipa_us":"/ˈnuːkliər/","definition_zh":"核的；原子核的；核能的；细胞核的","definition_en":"relating to a nucleus, especially the atomic nucleus or the cell nucleus","core_image":"一个极小的中心，周围绕着一圈电子或一层膜","scene":"The country gets most of its electricity from nuclear power plants.","sceneCN":"这里 nuclear 指「核能的」（第 2 个义项：由原子核反应释放能量的）；句意：该国大部分电力来自核电站。","pos":[{"tag":"adj.","zh":"核的；原子核的；核能的；核武器的；细胞核的；核心家庭的"}],"collocations":[{"phrase":"nuclear power","zh":"核能；核电"},{"phrase":"nuclear weapon","zh":"核武器"},{"phrase":"nuclear energy","zh":"核能"},{"phrase":"nuclear family","zh":"核心家庭"},{"phrase":"nuclear physics","zh":"核物理学"},{"phrase":"nuclear medicine","zh":"核医学"},{"phrase":"nuclear envelope","zh":"核膜"}],"forms":[{"label":"比较级","form":"more nuclear"},{"label":"最高级","form":"most nuclear"},{"label":"名词形式","form":"nucleus（核）"},{"label":"复合成分","form":"nuclear-（用于 nuclear-powered、nuclear-free 等）"}],"derivatives":[{"word":"nucleus","pos":"n.","zh":"核；原子核；细胞核"},{"word":"nuclear-powered","pos":"adj.","zh":"核动力的"},{"word":"nuclear-free","pos":"adj.","zh":"无核的"},{"word":"nuclear-capable","pos":"adj.","zh":"具备核能力的"},{"word":"nucleonics","pos":"n.","zh":"核工程学（少用）"}],"senses":[{"no":"01","title":"Of the atomic nucleus","titleCN":"原子核的","definition":"relating to the nucleus of an atom","definitionCN":"与原子核有关的","example":"Nuclear size is measured in femtometres.","exampleCN":"原子核的尺度以飞米计。","why":"The adjective simply attaches the noun nucleus to atomic physics, where the centre of the atom is the object of study.","whyCN":"这个形容词把 nucleus 直接接到原子物理上，那里研究的对象就是原子的中心。"},{"no":"02","title":"Nuclear energy","titleCN":"核能的","definition":"describing energy released by changes in atomic nuclei","definitionCN":"指由原子核变化释放的能量","example":"Nuclear power supplies a fifth of the country's electricity.","exampleCN":"核电供应全国五分之一的电力。","why":"Because the energy comes from the nucleus rather than from chemical bonds, the adjective names the source of the power.","whyCN":"因为能量来自原子核而不是化学键，这个形容词命名的就是能量的来源。"},{"no":"03","title":"Nuclear weapons","titleCN":"核武器的","definition":"describing weapons whose explosive force comes from nuclear reactions","definitionCN":"指爆炸力来自核反应的武器","example":"The treaty limits the number of nuclear warheads.","exampleCN":"该条约限制核弹头的数量。","why":"The same source of energy, released deliberately and instantly, yields a weapon, so the adjective marks the mechanism of the blast.","whyCN":"同一种能量来源若被有意瞬间释放，就成为武器，因此这个形容词标出爆炸的机制。"},{"no":"04","title":"Nuclear physics","titleCN":"核物理的","definition":"relating to the branch of physics that studies nuclei and their reactions","definitionCN":"与研究核及其反应的物理分支有关","example":"Nuclear physics grew out of radioactivity research.","exampleCN":"核物理学从放射性研究中发展出来。","why":"A discipline named after its object takes the adjective as a fixed modifier, as in nuclear physics or nuclear chemistry.","whyCN":"以研究对象命名的学科会把形容词作为固定修饰语，如 nuclear physics 或 nuclear chemistry。"},{"no":"05","title":"Of the cell nucleus","titleCN":"细胞核的","definition":"relating to the nucleus of a living cell","definitionCN":"与活细胞的细胞核有关的","example":"Nuclear DNA is separated from the cytoplasm by a membrane.","exampleCN":"核 DNA 由一层膜与细胞质隔开。","why":"Biology uses the same adjective for the cell's centre, and compounds such as nuclear envelope keep the two senses distinct by context.","whyCN":"生物学用同一个形容词指细胞的中心，nuclear envelope 等复合词靠上下文把两个义项区分开。"},{"no":"06","title":"Nuclear family","titleCN":"核心家庭的","definition":"describing a household of parents and their dependent children","definitionCN":"指由父母与其未成年子女组成的家庭","example":"The survey compared nuclear and extended households.","exampleCN":"这项调查比较了核心家庭与大家庭。","why":"Social science borrowed the image of a small centre with close members, contrasting it with the wider extended family.","whyCN":"社会科学借用「小核心加紧密成员」的意象，用来与更宽的扩展家庭相对照。"},{"no":"07","title":"Nuclear medicine","titleCN":"核医学的","definition":"describing medical techniques that use radioactive substances","definitionCN":"指使用放射性物质的医学技术","example":"Nuclear medicine scans reveal how an organ is working.","exampleCN":"核医学扫描能显示器官的工作状况。","why":"Radioactive tracers are read by their nuclear emissions, so the medical branch is named after the physical process.","whyCN":"放射性示踪剂靠其核辐射被读取，因此这个医学分支按物理过程命名。"},{"no":"08","title":"Nuclear envelope","titleCN":"核膜的","definition":"describing the membrane that surrounds the cell nucleus","definitionCN":"指包围细胞核的那层膜","example":"The nuclear envelope breaks down during mitosis.","exampleCN":"核膜在有丝分裂过程中解体。","why":"An anatomical compound uses the adjective to say which structure the membrane belongs to.","whyCN":"解剖学复合词用这个形容词说明这层膜属于哪个结构。"},{"no":"09","title":"Figurative extreme option","titleCN":"引申：极端手段","definition":"in politics, describing an extreme measure reserved as a last resort","definitionCN":"政治语境中指留作最后手段的极端措施","example":"Both sides avoided the nuclear option in the talks.","exampleCN":"双方在谈判中都避免使用极端手段。","why":"The destructive power of nuclear weapons supplies a metaphor for any step that would end the game.","whyCN":"核武器的破坏力为任何「一出手就终结局面」的步骤提供了比喻。"}],"etymology":{"intro":{"en":"Nuclear is the adjective of nucleus, formed with -ar; its history splits between atomic physics and cell biology.","cn":"nuclear 是 nucleus 的形容词，由 -ar 构成；它的历史分为原子物理与细胞生物学两条线。"},"items":[{"era":"LATIN NUCLEUS","en":"Nucleus, diminutive of nux 'nut', meant a kernel. English borrowed the noun in the 17th century.","cn":"nucleus 是 nux「坚果」的指小形式，意为果仁。英语在 17 世纪借入这个名词。"},{"era":"NINETEENTH-CENTURY ADJECTIVE","en":"The adjective nuclear is recorded in the 19th century in general senses such as 'relating to a kernel or centre'. The precise first date is uncertain.","cn":"形容词 nuclear 在 19 世纪有「与果核或中心有关的」这类一般义。确切首见年代不确定。"},{"era":"1831 CELL NUCLEUS","en":"Robert Brown's nucleus gave biology its own central body, and nuclear later described the structures around it.","cn":"Robert Brown 的 nucleus 为生物学提供了自己的中心小体，nuclear 后来用于描述它周围的结构。"},{"era":"1911 ATOMIC PHYSICS","en":"Rutherford's model placed nearly all atomic mass in a tiny nucleus, and nuclear physics was born around 1911 to 1912.","cn":"卢瑟福的模型把原子几乎全部质量放进一个极小的核，核物理学约在 1911 至 1912 年诞生。"},{"era":"1945 AND AFTER","en":"The nuclear age fixed the word in public language through weapons and power stations, adding figurative uses such as the nuclear option.","cn":"1945 年之后的核时代通过武器与电站把这个词固定进公共语言，并增加了「极端手段」这类比喻用法。"}]},"similar":{"note":{"en":"The first group separates nuclear from the noun and from near-looking words; the second separates its atomic sense from its biological and social senses.","cn":"第一组把 nuclear 与名词及形近词分开；第二组把它的原子义与生物、社会义分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nucleus","ipa":"/ˈnjuːkliəs/","tag":"the noun","definition":"The central body itself; nuclear is the adjective used in nuclear power, nuclear physics or nuclear envelope.","definitionCN":"指中心小体本身；nuclear 是用于 nuclear power、nuclear physics、nuclear envelope 的形容词。"},{"word":"nucleolus","ipa":"/ˌnjuːkliˈəʊləs/","tag":"a smaller body","definition":"A structure inside the cell nucleus, not the nucleus; it is a noun and never replaces nuclear as a modifier.","definitionCN":"指细胞核内的一个结构，不是细胞核本身；它是名词，不能像 nuclear 那样作修饰语。"},{"word":"nucleic","ipa":"/njuːˈkliːɪk/","tag":"chemical adjective","definition":"Used almost only in nucleic acid; it refers to the chemistry of nuclei, not to nuclear energy.","definitionCN":"几乎只用于 nucleic acid；它指核的化学，而不是核能。"}]},{"heading":"NEAR MEANING","entries":[{"word":"atomic","ipa":"/əˈtɒmɪk/","tag":"whole atom","definition":"Relating to atoms as wholes; atomic energy can mean energy from the atom generally, while nuclear pins it to the nucleus.","definitionCN":"指与整个原子有关的；atomic energy 可泛指原子能，而 nuclear 明确限定在原子核。"},{"word":"radioactive","ipa":"/ˌreɪdiəʊˈæktɪv/","tag":"property, not structure","definition":"Describing unstable nuclei that emit radiation; a material can be radioactive without being part of a nuclear reactor.","definitionCN":"指不稳定的核发出辐射；某种材料可以具有放射性，却与核反应堆无关。"},{"word":"central","ipa":"/ˈsentrəl/","tag":"position, not physics","definition":"Located at the middle; it is the everyday word for position and never means atomic or cell nuclei.","definitionCN":"指位于中间，是表示位置的日常词，从不指原子核或细胞核。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"nucleus + -ar: the adjective of the kernel.","cn":"nucleus + -ar：果核的形容词。"},{"en":"The family runs nucleus, nuclear-powered, nuclear-free and nucleonics.","cn":"同族词有 nucleus、nuclear-powered、nuclear-free、nucleonics。"},{"en":"Fixed phrases: nuclear power, nuclear weapon, nuclear family, nuclear envelope.","cn":"固定搭配：核能、核武器、核心家庭、核膜。"},{"en":"Context decides whether the nucleus is in an atom or in a cell.","cn":"上下文决定这个核是在原子里还是在细胞里。"},{"en":"The nuclear option is a metaphor borrowed from the bomb.","cn":"nuclear option 是从核弹借来的比喻。"}],"abstract":[{"en":"An atom is a tiny sun with a nucleus at the centre and electrons in orbit.","cn":"原子像一颗微型太阳，原子核在中心，电子在轨道上。"},{"en":"A nuclear family is a small core with a clear boundary, like a nucleus with its membrane.","cn":"核心家庭像一个有清晰边界的小核心，如同带膜的细胞核。"},{"en":"The nuclear option is the move that ends the game, like a bomb in a board game.","cn":"极端手段是终结整局棋的那一步，就像棋盘游戏里的炸弹。"}]},"examples":[{"en":"Nuclear power produces electricity without burning coal.","cn":"核能发电不燃烧煤炭。"},{"en":"The nuclear envelope separates the cell's DNA from the cytoplasm.","cn":"核膜把细胞的 DNA 与细胞质隔开。"},{"en":"The country expanded its nuclear medicine programme.","cn":"该国扩大了核医学项目。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nucleus（核）+ -ar」→ 跟核有关的 → 原子核的、核能的、细胞核的","word":"nuclear"},"root":"拉丁语 nux「坚果」→ nucleus「果仁、小核」→ 英语 nucleus；加形容词后缀 -ar 构成 nuclear。","sensesIntro":{"en":"Nine senses divide into three families: atomic physics and its power and weapons, cell biology and its envelope, and social or figurative cores such as the nuclear family and the nuclear option.","cn":"九个义项分成三族：原子物理及其能量与武器，细胞生物学及其核膜，以及核心家庭、极端手段这类社会或比喻性的核心。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tiny centre with electrons or a membrane wrapped around it.","cn":"核心意象：一个极小的中心，外面绕着一圈电子或一层膜。"},"chain":["OF A NUCLEUS","ATOMIC CORE","RELEASE ENERGY","BUILD WEAPONS","CELL CORE","SMALL CENTRAL GROUP"],"branches":[{"senses":"S1 · S4","en":"ATOMIC SCIENCE: the nucleus as an object of study and the discipline built around it.","cn":"原子科学：作为研究对象的原子核，以及围绕它建立的学科。"},{"senses":"S2 · S3 · S7","en":"ENERGY AND MEDICINE: power from the nucleus, weapons from the same source, and radioactive tracers.","cn":"能量与医学：来自核的能量，同源的武器，以及放射性示踪剂。"},{"senses":"S5 · S8","en":"CELL BIOLOGY: the nucleus of a living cell and the membrane around it.","cn":"细胞生物学：活细胞的细胞核及其周围的膜。"},{"senses":"S6","en":"SOCIAL CORE: the small household built around parents and children.","cn":"社会核心：围绕父母与子女建立的小家庭。"},{"senses":"S9","en":"METAPHOR: the destructive force of the bomb becomes a last-resort political move.","cn":"比喻：核弹的破坏力变成政治上最后才用的手段。"}]},"affixes":{"intro":{"en":"Nuclear adds the Latin adjective ending -ar to nucleus; the word then multiplies in compounds.","cn":"nuclear 在 nucleus 后加拉丁语形容词词尾 -ar；随后在复合词中大量增殖。"},"latinIntro":{"en":"Latin nux and nucleus supply the root; -ar comes from Latin -aris. Compounds such as nuclear-powered and nuclear-free are English formations.","cn":"拉丁语 nux 与 nucleus 提供词根；-ar 来自拉丁语 -aris。nuclear-powered、nuclear-free 等复合词是英语构造。"},"items":[{"word":"nuclear","structure":"nucleus + -ar","meaning":"relating to a nucleus","meaningCN":"与核有关的","example":"Nuclear reactions change the identity of atoms.","exampleCN":"核反应改变原子的身份。"},{"word":"nucleus","structure":"Latin nucleus","meaning":"a kernel or central body","meaningCN":"果仁或中心小体","example":"The nucleus is the cell's control centre.","exampleCN":"细胞核是细胞的控制中心。"},{"word":"nuclear-powered","structure":"nuclear + power + -ed","meaning":"driven by nuclear energy","meaningCN":"由核能驱动的","example":"A nuclear-powered submarine can stay under for months.","exampleCN":"核动力潜艇能在水下停留数月。"},{"word":"nuclear-free","structure":"nuclear + free","meaning":"without nuclear weapons or power","meaningCN":"没有核武器或核能的","example":"The zone was declared nuclear-free.","exampleCN":"该区域被宣布为无核区。"},{"word":"nucleonics","structure":"nucleus + -ics","meaning":"the technology of nuclear processes","meaningCN":"核过程的技术","example":"Nucleonics covers reactors and isotopes.","exampleCN":"核工程学涵盖反应堆与同位素。"},{"word":"atomic","structure":"Greek atomos (indivisible) + -ic","meaning":"relating to atoms","meaningCN":"与原子有关的","example":"Atomic theory predates nuclear physics.","exampleCN":"原子论早于核物理学。"},{"word":"radioactive","structure":"radio- + active","meaning":"emitting radiation from unstable nuclei","meaningCN":"不稳定核发出辐射的","example":"Radioactive waste needs long storage.","exampleCN":"放射性废料需要长期储存。"},{"word":"envelope","structure":"French enveloppe","meaning":"a surrounding membrane or cover","meaningCN":"包围的膜或覆盖物","example":"The nuclear envelope has pores.","exampleCN":"核膜上有孔。"},{"word":"fission","structure":"Latin fissio, from findere (to split)","meaning":"the splitting of a nucleus","meaningCN":"原子核的分裂","example":"Nuclear fission releases heat.","exampleCN":"核裂变释放热量。"}],"latinEntries":[{"word":"nux","structure":"Latin noun, stem nuc-, 'nut'","meaning":"a nut","meaningCN":"坚果"},{"word":"nucleus","structure":"Latin diminutive of nux","meaning":"kernel; central body","meaningCN":"果仁；中心小体"},{"word":"fissio","structure":"Latin noun from findere, 'to split'","meaning":"a splitting","meaningCN":"分裂"}]}},{"word":"membrane","ipa_uk":"/ˈmembreɪn/","ipa_us":"/ˈmembreɪn/","definition_zh":"膜；薄膜；细胞膜；隔膜","definition_en":"a thin layer of tissue or material that separates two regions or covers a surface","core_image":"一层薄而柔韧的皮，把两边隔开又允许某些东西通过","scene":"The membrane around the cell controls what enters and leaves.","sceneCN":"这里 membrane 指「细胞膜」（第 2 个义项：包围细胞的薄膜）；句意：细胞周围的膜控制物质的进出。","pos":[{"tag":"n.","zh":"膜；薄膜；细胞膜；隔膜；（鼓、扬声器的）振动膜"}],"collocations":[{"phrase":"cell membrane","zh":"细胞膜"},{"phrase":"plasma membrane","zh":"质膜"},{"phrase":"mucous membrane","zh":"黏膜"},{"phrase":"tympanic membrane","zh":"鼓膜"},{"phrase":"membrane protein","zh":"膜蛋白"},{"phrase":"semipermeable membrane","zh":"半透膜"},{"phrase":"membrane potential","zh":"膜电位"}],"forms":[{"label":"复数","form":"membranes"},{"label":"形容词","form":"membranous（膜的；膜状的）"},{"label":"形容词","form":"membranal（膜的，少用）"},{"label":"指小形式","form":"membranelle（小膜，生物学用语）"}],"derivatives":[{"word":"membranous","pos":"adj.","zh":"膜的；膜状的"},{"word":"membranal","pos":"adj.","zh":"膜的（少用）"},{"word":"membranelle","pos":"n.","zh":"小膜"},{"word":"membrane-bound","pos":"adj.","zh":"膜结合的"},{"word":"bilayer","pos":"n.","zh":"双分子层"}],"senses":[{"no":"01","title":"Thin separating layer","titleCN":"薄膜；隔膜","definition":"a thin sheet of material that separates two spaces or covers a surface","definitionCN":"把两个空间隔开或覆盖表面的薄片","example":"A membrane kept the salt water from mixing with the fresh water.","exampleCN":"一层膜阻止盐水与淡水混合。","why":"The Latin word named a thin skin, and the core sense remains any thin layer that divides one region from another.","whyCN":"拉丁词本指一层薄皮，核心义仍是把两个区域隔开的任何薄层。"},{"no":"02","title":"Cell membrane","titleCN":"细胞膜","definition":"the thin layer that surrounds a cell and controls what passes through","definitionCN":"包围细胞并控制物质通过的薄膜","example":"The cell membrane is a double layer of lipids.","exampleCN":"细胞膜是脂质的双层结构。","why":"Every cell is separated from its surroundings by a skin, so biology uses the word for the boundary of life itself.","whyCN":"每个细胞都靠一层皮与外界隔开，因此生物学用这个词指生命本身的边界。"},{"no":"03","title":"Mucous membrane","titleCN":"黏膜","definition":"the moist lining of body cavities such as the mouth and nose","definitionCN":"口腔、鼻腔等体腔的湿润内衬","example":"The virus enters through the mucous membrane of the nose.","exampleCN":"病毒经由鼻腔的黏膜进入。","why":"Anatomy names the lining of a cavity by its thin membranous character, and the fixed phrase mucous membrane marks the wet ones.","whyCN":"解剖学按薄而似膜的特征命名体腔内衬，固定说法 mucous membrane 标出其中湿润的那类。"},{"no":"04","title":"Synthetic membrane","titleCN":"人工膜；滤膜","definition":"a manufactured film used to filter or separate substances","definitionCN":"用于过滤或分离物质的人造薄膜","example":"The plant uses a membrane to remove salt from seawater.","exampleCN":"该厂用一层膜从海水中除盐。","why":"Engineers copy the biological boundary with synthetic films, and the same word follows the function rather than the material.","whyCN":"工程师用人工薄膜复制生物边界，同一个词跟随的是功能而不是材料。"},{"no":"05","title":"Eardrum","titleCN":"鼓膜","definition":"the thin membrane in the ear that vibrates with sound","definitionCN":"耳中随声音振动的薄膜","example":"A loud noise can rupture the tympanic membrane.","exampleCN":"巨大的噪声可能震破鼓膜。","why":"The eardrum is literally a small stretched membrane, so anatomy borrows the general word without metaphor.","whyCN":"鼓膜字面上就是一张绷紧的小膜，因此解剖学直接借用这个通用词，并不构成比喻。"},{"no":"06","title":"Membrane proteins","titleCN":"膜蛋白；膜系统","definition":"the proteins and lipids that make up a biological membrane","definitionCN":"构成生物膜的蛋白质与脂质","example":"Membrane proteins pump ions across the bilayer.","exampleCN":"膜蛋白把离子泵过双分子层。","why":"Once the membrane is an object, its components need names, and compounds such as membrane protein locate them in that layer.","whyCN":"一旦膜成为对象，它的组成部分就需要名字，membrane protein 这类复合词就把它们定位在这层结构中。"},{"no":"07","title":"Membrane potential","titleCN":"膜电位","definition":"the voltage difference across a biological membrane","definitionCN":"生物膜两侧的电压差","example":"The membrane potential changes when an ion channel opens.","exampleCN":"离子通道打开时膜电位会改变。","why":"Because a membrane separates two compartments, a difference in charge can build across it, giving the word a physical role.","whyCN":"由于膜把两个隔间分开，电荷差会在它两侧积累，于是这个词有了物理学角色。"},{"no":"08","title":"Tensile structure","titleCN":"张拉膜结构","definition":"a thin fabric or sheet stretched to carry loads in architecture","definitionCN":"建筑中绷紧以承载的薄织物或薄片","example":"The stadium roof is a membrane supported by cables.","exampleCN":"体育场的屋顶是由钢索支撑的张拉膜。","why":"Architecture uses the word for a surface that works by tension, the same idea of a thin skin doing a structural job.","whyCN":"建筑用这个词指靠张力工作的表面，仍是「一层薄皮承担结构任务」的同一想法。"},{"no":"09","title":"Vibrating diaphragm","titleCN":"振动膜（鼓面、扬声器）","definition":"the stretched sheet in a drum, speaker or microphone that produces or senses sound","definitionCN":"鼓、扬声器或麦克风中产生或感知声音的绷紧薄片","example":"The microphone's membrane moves with the slightest sound.","exampleCN":"麦克风的振动膜会随极轻微的声音移动。","why":"A thin sheet stretched over a frame is the physical shape of every drumhead, so the word covers that everyday object too.","whyCN":"绷在框架上的薄片正是每个鼓面的物理形态，因此这个词也涵盖这种日常物件。"}],"etymology":{"intro":{"en":"Membrane is Latin for a thin skin; its link to the word for a limb is plausible but not certain.","cn":"membrane 在拉丁语里指一层薄皮；它与表示「肢体」的词的联系看似合理，但并不确定。"},"items":[{"era":"LATIN MEMBRANA","en":"Latin membrana meant a thin skin, parchment or the surface of a body part. English borrowed it in the 15th century for anatomical coverings.","cn":"拉丁语 membrana 指薄皮、羊皮纸或身体某部分的表面。英语在 15 世纪借入，用于解剖上的覆盖层。"},{"era":"LINK TO MEMBRUM","en":"Many dictionaries connect membrana with membrum, 'limb, member of the body'. The connection is plausible but not proven, so it is uncertain.","cn":"许多词典把 membrana 与 membrum「肢体、身体的一部分」联系起来。这一联系看似合理但未被证实，属于来源不确定。"},{"era":"SEVENTEENTH-CENTURY MICROSCOPY","en":"As microscopy revealed thin boundaries in plants and animals, membrane became the general word for any such layer. Hooke and his contemporaries described membranes in cork and in tissue.","cn":"显微镜揭示动植物中的薄边界之后，membrane 成为指这类薄层的通用词。Hooke 及其同代描述了软木与组织中的膜。"},{"era":"NINETEENTH-CENTURY CELL THEORY","en":"Cell theory gave the cell membrane its modern role as the boundary of the cell. The phrase cell membrane is 19th century or later.","cn":"细胞学说赋予细胞膜「细胞边界」的现代角色。cell membrane 这一说法出现于 19 世纪或更晚。"},{"era":"TWENTIETH-CENTURY BIOPHYSICS","en":"In the 20th century the lipid bilayer, membrane proteins and membrane potential became standard terms in biophysics.","cn":"20 世纪，脂质双分子层、膜蛋白与膜电位成为生物物理学的标准术语。"}]},"similar":{"note":{"en":"The first group separates membrane from words for its material and from the specific cell boundary; the second separates it from other thin layers and coverings.","cn":"第一组把 membrane 与指其材料的词以及专指细胞边界的词分开；第二组把它与其它薄层和覆盖物分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"membranous","ipa":"/ˈmembrənəs/","tag":"the adjective","definition":"The adjective meaning 'of membrane' or 'membrane-like'; membrane is the countable noun.","definitionCN":"是形容词，意为「膜的」或「膜状的」；membrane 是可数名词。"},{"word":"member","ipa":"/ˈmembə(r)/","tag":"person or part, different word","definition":"A person in a group or a limb; it may share a Latin source with membrane, but its meaning is unrelated to thin layers.","definitionCN":"指群体中的成员或肢体；它可能与 membrane 共享拉丁来源，但词义与薄层无关。"},{"word":"membranelle","ipa":"/ˈmembrənel/","tag":"small technical structure","definition":"A small membrane-like structure in a cell, used in specialist biology; it is not a general synonym.","definitionCN":"指细胞中膜状的小结构，属于专业生物学术语，不是通用同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"film","ipa":"/fɪlm/","tag":"thin layer, general","definition":"A thin layer of any material, often on a surface; a membrane usually separates two spaces and has a function.","definitionCN":"指任何材料的薄层，常附在表面；membrane 通常分隔两个空间并具有功能。"},{"word":"lining","ipa":"/ˈlaɪnɪŋ/","tag":"inner covering","definition":"A layer covering the inside of something; a mucous membrane is a lining, but not every lining is a membrane.","definitionCN":"指覆盖在内部的一层；黏膜是一种内衬，但不是所有内衬都是膜。"},{"word":"barrier","ipa":"/ˈbæriə(r)/","tag":"function, not material","definition":"Anything that blocks movement; a membrane can act as a barrier but may also let selected substances through.","definitionCN":"指阻挡运动的东西；膜可以起屏障作用，但也可能让特定物质通过。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin membrana 'thin skin': a sheet that separates two spaces.","cn":"拉丁语 membrana「薄皮」：把两个空间隔开的一层薄片。"},{"en":"The family runs membranous, membranal, membranelle, membrane-bound and bilayer.","cn":"同族词有 membranous、membranal、membranelle、membrane-bound、bilayer。"},{"en":"Fixed phrases: cell membrane, mucous membrane, tympanic membrane, semipermeable membrane.","cn":"固定搭配：细胞膜、黏膜、鼓膜、半透膜。"},{"en":"The same word covers a soap bubble film, an eardrum and a stadium roof.","cn":"同一个词涵盖肥皂泡的薄膜、鼓膜与体育场屋顶。"},{"en":"A membrane is defined by being thin and by separating something.","cn":"膜的定义特征就是薄，并且把某物隔开。"}],"abstract":[{"en":"A membrane is a border checkpoint: it does not just block, it chooses.","cn":"膜像一个边境检查站：它不只是阻挡，还会选择。"},{"en":"Think of a drum: a stretched skin turns a hit into a sound, and a cell membrane turns a signal into a response.","cn":"想象一面鼓：绷紧的皮把敲击变成声音，细胞膜则把信号变成反应。"},{"en":"A stadium roof is a membrane holding up the sky, the same thin sheet doing a structural job.","cn":"体育场屋顶像一层托住天空的膜，同样是薄片承担结构任务。"}]},"examples":[{"en":"The cell membrane controls which ions enter the cell.","cn":"细胞膜控制哪些离子进入细胞。"},{"en":"A semipermeable membrane lets water through but holds salt back.","cn":"半透膜让水通过，却把盐挡住。"},{"en":"The mucous membrane of the nose traps dust and viruses.","cn":"鼻腔黏膜会截留灰尘与病毒。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「membrane 像一层薄皮」→ 把两边隔开的薄膜 → 细胞膜、黏膜、隔膜","word":"membrane"},"root":"拉丁语 membrana「薄皮、羊皮纸」→ 英语 membrane；与 membrum「肢体」的联系看似合理但未证实。","sensesIntro":{"en":"Nine senses all describe a thin layer with a job: separating, covering, filtering, vibrating, or carrying a voltage. The cell membrane, mucous lining, filter, eardrum, roof and drumhead are all the same shape.","cn":"九个义项都描述一层有任务的薄层：分隔、覆盖、过滤、振动或承载电压。细胞膜、黏膜、滤膜、鼓膜、屋顶与鼓面都是同一种形状。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thin flexible skin that separates two sides and lets some things through.","cn":"核心意象：一层薄而有弹性的皮，把两边隔开，允许某些东西通过。"},"chain":["THIN SKIN","SEPARATE TWO SPACES","BOUND THE CELL","LINE A CAVITY","FILTER OR SELECT","VIBRATE OR CARRY LOAD"],"branches":[{"senses":"S1","en":"THE GENERAL LAYER: any thin sheet that divides two regions.","cn":"一般薄层：任何把两个区域分开的薄片。"},{"senses":"S2 · S6 · S7","en":"THE CELL BOUNDARY: the membrane itself, its proteins, and the voltage across it.","cn":"细胞边界：膜本身、它的蛋白，以及跨膜的电压。"},{"senses":"S3","en":"ANATOMICAL LINING: the wet membrane covering a body cavity.","cn":"解剖内衬：覆盖体腔的湿润薄膜。"},{"senses":"S4 · S5","en":"FUNCTIONAL SHEETS: synthetic filters and the eardrum.","cn":"功能性薄片：人工滤膜与鼓膜。"},{"senses":"S8 · S9","en":"ENGINEERED AND VIBRATING: tensile roofs and the stretched diaphragm of instruments.","cn":"工程与振动：张拉屋顶与乐器、麦克风的绷紧膜片。"}]},"affixes":{"intro":{"en":"Membrane is a Latin noun with no prefix; its family is built with -ous, -al and the diminutive -elle.","cn":"membrane 是不带前缀的拉丁名词；其词族由 -ous、-al 与指小后缀 -elle 构成。"},"latinIntro":{"en":"Latin membrana supplies the root; the adjective ending -ous comes from Latin -osus, and -elle is a French/Latin diminutive.","cn":"拉丁语 membrana 提供词根；形容词词尾 -ous 来自拉丁语 -osus，-elle 是法语与拉丁语的指小成分。"},"items":[{"word":"membrane","structure":"Latin membrana","meaning":"a thin skin or layer","meaningCN":"薄膜或薄层","example":"The membrane is only a few molecules thick.","exampleCN":"这层膜只有几个分子厚。"},{"word":"membranous","structure":"membrane + -ous","meaning":"made of or like membrane","meaningCN":"由膜构成或似膜的","example":"The tissue has a membranous cover.","exampleCN":"该组织有一层膜状覆盖。"},{"word":"membranal","structure":"membrane + -al","meaning":"relating to membrane (rare)","meaningCN":"与膜有关的（少用）","example":"Membranal proteins differ from soluble ones.","exampleCN":"膜蛋白与可溶性蛋白不同。"},{"word":"membranelle","structure":"membrane + -elle","meaning":"a small membrane-like structure","meaningCN":"小的膜状结构","example":"The membranelle beats water toward the mouth.","exampleCN":"小膜把水扇向口部。"},{"word":"membrane-bound","structure":"membrane + bound","meaning":"attached to or enclosed by a membrane","meaningCN":"附着于膜或被膜包围的","example":"Membrane-bound receptors sit at the surface.","exampleCN":"膜结合受体位于表面。"},{"word":"bilayer","structure":"bi- (two) + layer","meaning":"a double layer of molecules","meaningCN":"分子的双层结构","example":"The lipid bilayer forms the cell membrane.","exampleCN":"脂质双分子层构成细胞膜。"},{"word":"permeable","structure":"per- (through) + meare (to pass) + -able","meaning":"allowing fluid to pass","meaningCN":"允许流体通过的","example":"The membrane is permeable to water.","exampleCN":"该膜对水是可透的。"},{"word":"impermeable","structure":"im- (not) + permeable","meaning":"not allowing fluid to pass","meaningCN":"不允许流体通过的","example":"The cuticle is impermeable to water.","exampleCN":"表皮对水不可透。"},{"word":"mucous","structure":"mucus + -ous","meaning":"relating to mucus","meaningCN":"与黏液有关的","example":"The mucous membrane secretes mucus.","exampleCN":"黏膜分泌黏液。"}],"latinEntries":[{"word":"membrana","structure":"Latin noun, first declension","meaning":"thin skin; parchment","meaningCN":"薄皮；羊皮纸"},{"word":"membrum","structure":"Latin noun, second declension","meaning":"limb; member of a body","meaningCN":"肢体；身体的一部分"},{"word":"membranaceus","structure":"Latin adjective from membrana","meaning":"membranous","meaningCN":"膜状的"}]}}]);
